SELECT 'moj-all-verified-judgments-review-002-chunk-174' AS batch_name,
       (SELECT count(*) FROM public.legal_documents WHERE id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"6cdefa82-7d64-5f44-9555-94421f6a9209","document_type":"judgment","category":"judicial","subcategory":"general","title":"إجارة -إجارة عمارة سكن حجاج -مطالبة بإعادة أجرة مدفوعة لتعذر إخراج تصريح إسكان حجاج -إقرار بالعقد واستالم املبلغ وإعادة بعضه وإنكار تعذر إخراج التصريح -إقرار خطي -الدفع بأنه نزع منه بالقوة -عدم البينة على الدفع -إلزام املدعى عليه برد باقي األجرة -رفع احلكم حملكمة الاستئناف لتعذر تبليغ املدعي عليه باحلكم.","document_number":"3443385","case_number":"32350279","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبكة املكرمة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/2/20","year":"1434","subject":"إجارة -إجارة عمارة سكن حجاج -مطالبة بإعادة أجرة مدفوعة لتعذر إخراج تصريح إسكان حجاج -إقرار بالعقد واستالم املبلغ وإعادة بعضه وإنكار تعذر إخراج التصريح -إقرار خطي -الدفع بأنه نزع منه بالقوة -عدم البينة على الدفع -إلزام املدعى عليه برد باقي األجرة -رفع احلكم حملكمة الاستئناف لتعذر تبليغ املدعي عليه باحلكم.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/2/20 :‬هـ  ‬\n                        ‫ُ‬                ‫َر ْق ُم َّ‬\n                            ‫الص ِّك‪3443385 :‬‬\n                          ‫َر ْق ُم الدعوى‪32350279 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                  ‫‪ 34201660‬تاريخه‪1434/4/30 :‬هـ‬\n\n\n\n      ‫إجــارة ‪ -‬إجــارة عمــارة ســكن حجــاج ‪ -‬مطالبــة بإعــادة أجــرة مدفوعــة‬\n      ‫لتعــذر إخــراج تصريــح إســكان حجــاج ‪ -‬إقــرار بالعقــد واســتالم املبلــغ‬\n      ‫وإعــادة بعضــه وإنــكار تعــذر إخــراج التصريــح ‪ -‬إقــرار خطــي ‪ -‬الدفــع‬\n      ‫بأنــه نــزع منــه بالقــوة ‪ -‬عــدم البينــة علــى الدفــع ‪ -‬إلــزام املدعــى عليــه‬\n      ‫بــرد باقــي األجــرة‪ -‬رفــع احلكــم حملكمــة االســتئناف لتعــذر تبليــغ‬\n                                                             ‫املدعــي عليــه باحلكــم‪.‬‬\n\n\n\n\n      ‫مــا أســتند إليــه القاضــي مــن املبــادئ العامــة وقواعــد العدالــة الــواردة‬\n                                                                ‫يف تســبيب حكمــه ‪.‬‬\n\n\n\n\n      ‫تقــدم املدعــي بدعــوى ضــد املدعــى عليه بأنه اســتأجر عمارة لالســتفادة‬\n      ‫منهــا يف موســم احلــج بأجــرة معلومــة محــددة وســلم بعضــه وبقــي البعــض‬\n      ‫إال أنــه ظهــر بأنــه ال ميكــن االســتفادة منهــا للتأجيــر علــى احلجــاج لوجــود‬\n      ‫مخالفــة بنــاء يف الــدور العلــوي مــن العمارة مما يتعــذر معه خروج تصريح‬\n      ‫إلســكان احلجــاج لــذا فقــد طلــب مــن املدعــى عليــه إعــادة اجلــزء املســلم‬\n      ‫مــن األجــرة فأعــاد بعضــه ووعــد بتســليم الباقــي إال أنــه امتنــع لــذا فقــد‬\n      ‫طلــب إلزامــه بــرد باقــي األجــرة املســلمة‪ ،‬أقــر املدعــى عليــه بالدعــوى‬\n‫‪375‬‬\n\f‫إال أنــه أنكــر وجــود مخالفــة وتعــذر االســتفادة منهــا إلســكان احلجــاج‬\n‫ودفــع بــأن عــدم خــروج تصريــح إســكان احلجــاج كان بتفريــط مــن‬\n‫املدعــي وأمــا رده لبعــض األجــرة فــكان جبــرا خلوفــه مــن تهديــده ويطلب‬\n‫رد طلــب املدعــي‪ ،‬بعرضــه علــى املدعــي قــرر بــأن الصحيــح مــا ورد يف‬\n‫دعــواه وبطلــب البينــة منــه أبــرز ســندات قبــض كمــا أبــرز إقــرار ًا محررا‬\n‫مــن املدعــى عليــه مضمونــه إقــرار املدعــى عليــه بــأن يــرد للمدعــي املبلــغ‬\n‫املدعــى بــه باقــي األجــرة املســلمة‪ ،‬بعــرض اإلقــرار احملــرر علــى املدعــى‬\n‫عليــه دفــع بأنــه نــزع منــه بالقــوة فطلبــت البينــة علــى دفعــه فطلــب مهلــة‬\n‫إال أنــه لــم يحضــر يف اجللســة التــي أجلــت لــه لذلــك‪ ،‬عليــه وألن املدعــى‬\n‫عليــه وكالــة أقــر بصحــة اإلقــرار الصــادر مــن موكلــه واملتضمــن بــأن‬\n‫بذمتــه لصالــح املدعــي أصالــة املبلــغ املدعــى بــه وأن آخــر دفعــة مــن هــذا‬\n‫املبلــغ تســلم يف ‪1431/8/30‬ه ـ ولدفــع املدعــى عليــه وكالــة بــأن هــذا‬\n‫اإلقــرار قــد أخــذ منــه بالقــوة واإلكــراه وطلــب مهلــة لســؤال موكلــه عن‬\n‫البينــة ولتخلفــه عــن اجللســة املقــررة وألن تخلفــه يعــد نكــو ًال عــن اجلــواب‬\n‫وبنــاء علــى املــادة اخلامســة واخلمســن والفقــرة الثانيــة مــن الئحــة املــادة‬\n‫الثالثــة بعــد املائــة مــن نظــام املرافعــات الشــرعية وألن وكالــة املدعــى‬\n‫عليــه تخولــه حــق اإلقــرار لذلــك فقــد حكمــت الدائــرة علــى املدعــى‬\n‫عليــه حضوريـ ًا بــأن يدفــع للمدعــي املبلــغ املدعــى بــه‪ ،‬جــرى بعــث صــورة‬\n‫مــن احلكــم للمدعــى عليــه بواســطة محضــر اخلصــوم فعــادت اإلفــادة‬\n‫بأنــه مت الوصــول إلــى عنوانــه ولــم يعثــر عليــه وبالســؤال عــن كفيــل‬\n‫املدعــى عليــه أفــاد أحــد العاملــن بأنــه خــارج مكــة وباالتصــال علــى‬\n‫الهاتــف لــم يــرد عليــه أحــد ولتعــذر تســليم املدعــى عليــه لشــخصه نســخة‬\n‫مــن إعــام احلكــم وبنــاء علــى املــادة ‪ 5/176‬مــن نظــام املرافعــات فقــد‬\n\n\n                                                                                        ‫‪376‬‬\n\f      ‫تقــرر رفــع كامــل املعاملــة حملكمــة االســتئناف لتدقيــق احلكــم حســب‬\n                            ‫املتبع‪،‬صــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪   ...................‬القاضــي يف احملكمــة‬\n      ‫العامــة مبكــة املكرمــة   وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n      ‫رئيــس احملكمــة العامــة مبكــة املكرمــة برقــم ‪ 32137953‬وتاريــخ‬\n      ‫‪ 1432/04/23‬هــ   املقيــدة باحملكمــة برقــم ‪ 32350279‬وتاريــخ‬\n      ‫‪ 1432/04/08‬هــ  ففــي يــوم  األربعــاء املوافق‪ 1433/05/12‬هـ افتتحت‬\n      ‫اجللســة الســاعة  احلاديــة عشــرة وفيهــا حضــر ‪ .....................‬ســعودي‬\n      ‫ا عــن‬ ‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ....................‬بصفتــه وكيـ ً‬\n      ‫‪ ......................‬مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل الثانيــة‬\n      ‫مبكــة املكرمــة برقــم ‪  37937‬يف ‪1429/7/13‬ه ـ ولــه فيهــا حــق‬\n      ‫املرافعــة واملدافعــة واإلقــرار ومراجعــة احملاكــم  واإلنــكار والتنــازل‬\n      ‫والصلــح ‪ ...‬الــخ وادعــى علــى احلاضــر معــه ‪ ......................‬ســعودي‬\n      ‫ا‬\n      ‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪ .....................‬بصفتــه وكي ـ ً‬\n      ‫عــن ‪ .................‬مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل الثانيــة‬\n      ‫مبكــة املكرمــة برقــم ‪ 13872‬يف ‪1431/4/25‬ه ـ اجللــد ‪ 4498‬ولــه‬\n      ‫فيهــا حــق املرافعــة واملدافعــة وحضــور اجللســات واإلقــرار واإلنــكار‪....‬‬\n      ‫ا يف دعــواه عليــه لقــد مت االتفــاق بــن موكلــي و‪..................‬‬ ‫الــخ قائ ـ ً‬\n      ‫علــى أن يســتأجر موكلــي العمــارة الكائنــة يف حــي ‪....‬مبكة املكرمة‬\n      ‫وذلــك ملوســم حــج عــام ‪1429‬ه ـ مببلــغ وقــدره ثالثمائــة وخمســون ألــف‬\n      ‫ريــال مت تســليم  مبلــغ وقــدره مائــة وتســعون ألــف ريــال وذلــك للمدعــو‬\n\n‫‪377‬‬\n\f  ‫‪ ......‬واململوكــة لـ ــ‪ ......‬وقــد اســتأجرها املدعــو ‪ .......‬لعــدة ســنوات‬\n  ‫ولكــن موكلــي لــم يســتلم العمــارة املذكــورة ولــم ينتفــع بهــا وذلــك‬\n  ‫لوجــود مخالفــة بنــاء يف الــدور العلــوي مــن العمــارة ولــم يتــم اســتخراج‬\n  ‫تصريــح إســكان مــن جلنــة احلــج وقــد طلــب موكلــي مــن املدعــى عليــه‬\n  ‫إعــادة املبلــغ املذكــور والــذي اســتلم املدعــى عليــه جــزء منــه وذلــك‬\n  ‫بتفويــض مــن ‪ ..........‬فأعــاد ملوكلــي مبلــغ وقــدره خمســون ألــف ريــال‬\n  ‫ثــم  اتضــح بعــد ذلــك أن املدعــو ‪ ...........‬ليــس لــه ســوى االســم يف العمــارة‬\n  ‫وصاحــب املنفعــة هــو املدعــى عليــه وقــد التــزم املدعــى عليــه بإعــادة‬\n  ‫املبلــغ املتبقــي وقــدره مائــة وأربعــون ألــف ريــال لذلــك فموكلــي يطلــب‬\n  ‫إلــزام املدعــى عليــه بإعــادة املبلــغ املذكــور يف الدعــوى هــذه دعــواي‬\n  ‫ا مــا ذكــره املدعــي‬    ‫وبعــرض الدعــوى علــى املدعــى عليــه أجــاب قائ ـ ً‬\n  ‫وكالــة يف دعــواه مــن أنــه مت االتفــاق بــن موكلــه وموكلــي علــى أن‬\n  ‫يســتأجر العمــارة الكائنــة يف ‪....‬وذلــك ملوســم حــج عــام ‪1429‬ه ـ وذلــك‬\n  ‫مببلــغ وقــدره ثالثمائــة وخمســون ألــف وذلــك مبوجــب ســندات قبــض‬\n‫واململوكــة لــ‪ ................‬وقــد اســتأجرها املدعــو ‪ ...............‬لعــدة ســنوات  ‬\n  ‫فهــذا صحيــح ولكــن موكلــي شــريك مــع املدعــو ‪ ...............‬يف هــذه‬\n  ‫العمــارة ومــا ذكــره املدعــي وكالــة مــن املبالــغ التــي اســتلمها موكلــي‬\n  ‫فهــذا ال علــم لــي بــه وأمــا مــا ذكــره املدعــى عليــه مــن أن موكلــه لــم‬\n  ‫يســتفد مــن العمــارة فهــذا صحيــح ولكــن موكلــي قــد ســلم العمــارة‬\n  ‫املذكــورة للمدعــي أصالــة ولــم مينعــه مــن االنتفــاع بهــا وقــد تأخــر عــن‬\n  ‫التقــدمي للجنــة إســكان احلــج ولــم يســتطع ذلــك وأمــا مــا ذكــره املدعــي‬\n  ‫وكالــة مــن وجــود مخالفــة علــى العمــارة املذكــورة فهــذا غيــر صحيــح‬\n‫ومــا ذكــره املدعــي وكالــة مــن أن موكلــي أعــاد ملوكلــه مبلــغ وقــدره  ‬\n\n\n                                                                                             ‫‪378‬‬\n\f      ‫خمســون ألــف ريــال فهــذا صحيــح ولكــن ذلــك بعــد التهديــد واإلجبــار‬\n      ‫وقــد مت أخــذ املبلــغ منــه بغيــر وجــه حــق  ومــا طلبــه املدعــي وكالــة مــن‬\n      ‫إعــادة املبلــغ فموكلــي غيــر مســتعد بذلــك هكــذا أجــاب وبعــرض ذلــك‬\n      ‫ا الصحيــح مــا ذكــرت ولــدي البينــة‬         ‫علــى املدعــي وكالــة أجــاب قائ ـ ً‬\n      ‫علــى ذلــك هكــذا قــرر وبطلــب البينــة مــن املدعــي وكالــة أبــرز ســندات‬\n      ‫قبــض ‪ :‬األول برقــم ‪ 45951‬يف ‪1429/9/16‬ه ـ وفيــه مبلــغ  تســعون‬\n      ‫ألــف ريــال وذلــك مقابــل الدفعــة األولــى مــن إيجــار العمــارة الكائنــة ‪....‬‬\n      ‫واملســتلم ‪ ...............‬والثانــي برقــم ‪ 1204‬يف ‪1429/9/14‬ه ـ وفيــه مبلــغ‬\n      ‫عشــرة آالف ريــال  وذلــك عبــارة عــن عربــون إيجــار العمــارة الكائنــة‬\n      ‫‪....‬واملســتلم ‪ ................‬والثالــث برقــم ‪ 45966‬يف ‪1429/11/6‬ه ـ وفيــه‬\n      ‫مبلــغ عشــرة آالف ريــال وذلــك مقابــل عمــل أشــغال يف عمــارة ‪....‬واملســتلم‬\n      ‫‪ ...........‬والرابــع  برقــم ‪ 1225‬يف ‪1429/9/27‬ه ـ وفيــه مبلــغ خمســة‬\n      ‫وثالثــون ألــف ريــال  وذلــك مقابــل إيجــار العمــارة الكائنــة ‪....‬واملســتلم‬\n      ‫ا أطلب مهلة‬    ‫‪ .......‬أه ـ وبعــرض ذلــك علــى املدعــى عليــه وكالــة قــرر قائـ ً‬\n      ‫لعــرض ذلــك علــى موكلــي وســؤاله عــن املبالــغ التــي اســتلمها كمــا‬\n      ‫أبــرز إقــرار صــادر مــن املدعــى عليــه ونصــه كمــا يلــي ‪ :‬أقــر أنــا املدعــو‬\n      ‫‪ .............‬بنغالديشــي اجلنســية مبوجــب إقامــة رقــم ‪ ............‬بأنــه يف ذمتــي‬\n      ‫لصالــح ‪ ...........‬مائــة وأربعــون ألــف ريــال (‪ 140.000‬ريــال ) وذلــك نظيــر‬\n      ‫إعــادة إيجــار العمــارة التــي ســبق أن اســتأجرها املدعــو ‪ ............‬مــن األخ‬\n      ‫‪ .................‬الكائنــة ‪....‬حيــث إننــي أنــا صاحــب الصالحيــة بهــذا املبنــى‬\n      ‫واملدعــو ‪ .........‬لــه االســم وفائــدة بســيطة مــن قبلــي ومســتعد بإرجــاع‬\n      ‫املبلــغ هــذا علــى دفعــات بتاريــخ ‪1430/11/30‬ه ـ مبلــغ وقــدره  عشــرة‬\n      ‫اآلف ريــال وبتاريــخ ‪1430/12/30‬ه ـ عشــرون ألــف ريــال وبتاريــخ‬\n\n\n‫‪379‬‬\n\f   ‫‪1431/8/30‬ه ـ مبلــغ وقــدره (‪ 110.000‬ريــال (  مائــة وعشــرة اآلف‬\n   ‫ريــال ويف حالــة تأخــري عــن دفــع أي دفعــة مــن الدفعــات عــن تاريخهــا‬\n   ‫ا دون‬    ‫احملــدد وملــدة يومــن يصبــح كامــل املبلــغ واجــب الدفــع كام ـ ً‬\n   ‫مماطلــة أو تأخيــر  كمــا أقــر بــأن كامــل املبلــغ املذكــور مســئوليتي‬\n   ‫مســؤولية كاملــة كمــا ذكــرت ســابق ًا ومذيــل اإلقــرار بتوقيــع املقــر‬\n   ‫مبــا فيــه ‪............‬و‪ ..............‬والشــاهد ‪ ...................‬وبعرضــه علــى‬\n   ‫ا إن هــذا اإلقــرار صــادر‬     ‫املدعــى عليــه وكالــة صــادق عليــه وقــرر قائ ـ ً‬\n   ‫مــن موكلــي ولكنــه قــد أخــذ منــه باإلكــراه والقــوة اجلبريــة وقــد وضــع‬\n   ‫موكلــي إبهامــه عليــه وهــو ال يعلــم مضمونــه هكــذا قــرر وبعــرض ذلــك‬\n   ‫ا مــا ذكــره املدعــي وكالــة مــن أنــه مت‬       ‫علــى املدعــي وكالــة قــرر قائـ ً‬\n   ‫أخــذ اإلقــرار بالقــوة اجلبريــة فهــذا غيــر صحيــح هكــذا قــرر وبســؤال‬\n   ‫املدعــى عليــه وكالــة هــل لــدى موكلــك بينــة علــى أنــه مت أخــذ هــذا‬\n   ‫ا أطلــب مهلــة لســؤال موكلــي‬        ‫اإلقــرار باإلكــراه واإلجبــار فأجــاب قائـ ً‬\n   ‫واإلجابــة يف اجللســة القادمــة هكــذا أجــاب وقــرر وبســؤال املدعــي‬\n   ‫ا مت‬   ‫وكالــة متــى مت مطالبــة املدعــى عليــه بإعــادة املبلــغ فأجــاب قائ ـ ً‬\n‫مطالبتــه بإعــادة املبلــغ قبــل احلــج يف ‪1429/11/15‬ه ـ هكــذا أجــاب   ‬\n   ‫ا مــا ذكــره املدعــي‬     ‫وبعــرض ذلــك علــى املدعــى عليــه وكالــة قــرر قائـ ً‬\n   ‫وكالــة غيــر صحيــح فاملدعــي أصالــة لــم يطالــب موكلــي باملبلــغ إال بعد‬\n   ‫نهايــة احلــج هكــذا قــرر وبســؤال املدعــى عليه وكالة هــل لدى موكلك‬\n   ‫ا أطلــب مهلــة‬    ‫بينــة علــى تســليم العمــارة للمدعــي أصالــة فأجــاب قائ ـ ً‬\n   ‫لعــرض ذلــك علــى موكلــي واإلجابــة يف اجللســة القادمــة هكــذا أجــاب‬\n   ‫وقــرر ولطلــب املدعــى عليــه وكالــة فقــد رفعــت اجللســة ويف يــوم  األحــد‬\n   ‫املوافــق‪ 1433/11/21‬ه ـ افتتحــت اجللســة الســاعة  الثانيــة عشــرة ظهــر ًا‬\n\n\n                                                                                            ‫‪380‬‬\n\f        ‫وفيهــا حضــر  املدعــي وكالــة ولــم يحضــر املدعــى عليــه وال مــن ينــوب‬\n        ‫عنــه  وقــد جــرى طلبــه عــن طريــق محضــري اخلصــوم  بخطابنــا رقــم‬\n      ‫‪ 331398291‬يف  ‪1433/7/26‬هــ  فوردنــا منهــم شــرح ًا علــى اخلطــاب  ‬\n        ‫بتبلــغ املوظــف لــدى املؤسســة واســمه  ‪  .........‬ومذيــل احملضــر بتوقيــع‬\n      ‫محضــر اخلصــوم  ‪  .......‬ورئيــس قســم محضــري اخلصوم وبســؤال املدعي  ‬\n        ‫وكالــة هــل لديــك مــا تريــد  إضافتــه  فأجــاب بالنفــي  فبنــاء علــى مــا‬\n        ‫تقــدم  مــن الدعــوى اإلجابــة  ومبــا أن املدعــى عليــه وكالــة  قــد أقــر‬\n        ‫بصحــة  اإلقــرار  الصــادر  مــن موكلــه واملتضمــن  أن بذمتــه  لصالــح‬\n        ‫املدعــي أصالــة  املبلــغ املدعــى بــه   وأن آخــر دفعــة  مــن هــذا املبلــغ  تســلم‬\n        ‫يف ‪1431/8/30‬هــ  ولدفــع  املدعــى عليــه وكالــة بــأن هــذا اإلقــرار  قــد‬\n        ‫أخــذ  منــه بالقــوة   واإلكــراه  وطلــب مهلــة لســؤال  موكلــه عــن البينــة‬\n        ‫ولتخلفــه عــن اجللســة  املاضيــة وهــذه اجللســة  وألن تخلفــه يعــد نكــو ًال‬\n        ‫عــن اجلــواب  وبنــاء علــى املــادة  اخلامســة واخلمســون  والفقــرة الثانيــة‬\n      ‫مــن الئحــة املــادة  الثالثــة  بعــد املائــة   مــن نظــام املرافعــات  الشــرعية  ‬\n        ‫وألن  وكالــة املدعــى عليــه تخولــه  حــق  اإلقــرار  لذلــك فقــد حكمــت‬\n        ‫علــى املدعــى عليــه  حضوري ـ ًا بــأن يدفــع للمدعــي مبلــغ  وقــدره مائــة‬\n        ‫وأربعــون ألــف ريــال وبعــرض احلكــم  علــى املدعــي وكالــة قــرر قناعتــه‬\n        ‫باحلكــم وانتهــت اجللســة الســاعة  الثانيــة عشــرة والنصــف  ‪ ..‬وبــاهلل‬\n        ‫التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر‬\n                                                                         ‫يف  ‪ 1433/11/21‬ه ـ‬\n        ‫احلمــد هلل وحــده وبعــد   لــدي أنــا ‪ ......................‬القاضــي باحملكمــة‬\n        ‫العامــة مبكــة املكرمــة والقائــم بعمــل الشــيخ ‪ .....................‬أنــه يف يــوم‬\n        ‫االثنــن املوافــق ‪1434/4/1‬ه ـ افتتحــت اجللســة وقــد وردنــا خطــاب مدير‬\n\n\n‫‪381‬‬\n\f    ‫احملضريــن باحملكمــة برقــم ‪ 34498523‬يف  ‪1434/2/27‬هــ  بشــأن‬\n    ‫إبــاغ املدعــى عليــه الغائــب عــن مجلــس احلكــم ‪   ...............‬واملتضمــن‬\n    ‫بأنــه مت الوصــول إلــى عنــوان املذكــور أعــاه ولــم جنــده وبالســؤال عــن‬\n    ‫كفيــل املدعــى عليــه أفــاد أحــد العاملــن إنــه خــارج مكــة وباالتصــال‬\n    ‫علــى الهاتــف لــم يــرد علينــا أحــد أهــ  ومذيــل احملضــر بتوقيــع احملضــر‬\n    ‫‪ .......‬ورئيــس قســم احملضريــن   ‪ ....................‬وحيــث تعــذر تســليم‬\n    ‫املدعــى عليــه لشــخصه نســخة مــن إعــام احلكــم وبنــاء  علــى املــادة‬\n    ‫‪ 5/176‬مــن نظــام املرافعــات فقــد أمــرت بضبــط ذلــك وإحلاقــه بصكــه‬\n    ‫وســجله ورفــع كامــل املعاملــة حملكمــة االســتئناف لتدقيــق احلكــم‬\n    ‫حســب املتبــع وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                    ‫وصحبــه وســلم ‪ .‬حــرر يف  ‪ 1434/04/01‬ه ـ‬\n    ‫احلمــد هلل وحــده وبعــد ويف يــوم  األحــد     املوافــق  ‪ 1434/5/26‬ه ـ‬\n    ‫افتتحــت اجللســة وقــد وردتنــا املعاملــة اخلاصــة بدعــوى ‪ ..................‬ضــد‬\n    ‫املدعــى عليــه ‪    .......................‬مــن الدائــرة احلقوقيــة الســابعة مبحكمــة‬\n    ‫االســتئناف مبكــة املكرمــة  واملتضمــن احلمــد هلل وحــده وبعــد فقــد‬\n‫اطلعنــا علــى هــذا الصــك رقــم   ‪       3443385‬يف ‪1434/2/20‬ه ـ    ‬\n    ‫الصــادر مــن فضيلــة الشــيخ ‪ ........................... /‬القاضــي باحملكمــة‬\n    ‫العامــة مبكــة املكرمــة وأصدرنــا القــرار رقــم ‪     34201660‬يف‬\n    ‫‪1434/4/30‬هــ  املتضمــن املوافقــة علــى احلكــم أهــ  ‪ .‬عضــو ‪ ....‬ختمــه‬\n‫وتوقيعــه  عضــو ‪  ....‬ختمــه وتوقيعــه رئيــس الدائــرة  ‪ .....‬ختمــه وتوقيعــه  ‬\n‫عليــه فقــد أمــرت بضبــط ذلــك وإحلاقــه بصكــه وســجله حتــى ال يخفـى   ‬\n    ‫وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                 ‫وســلم ‪ .‬حــرر يف  ‪ 1434/5/26‬ه ـ‬\n\n\n                                                                                              ‫‪382‬‬\n\f        ‫احلمــد هلل وحــده‪ ،‬والصــاة والســام علــى مــن ال نبــي بعــده‪ ،‬وبعــد‪:‬‬\n        ‫‪ -‬فقــد جــرى منــا نحــن قضــا َة الدائــرة احلقوقيــة الســابعة مبحكمــة‬\n        ‫االســتئناف يف منطقــة مكــة املكرمــة االطال ُع علــى املعاملة الواردة من‬\n      ‫فضيلــة رئيــس احملكمــة العامــة مبكــة املكرمــة برقــم‪  321090281‬‬\n        ‫وتاريــخ ‪1434/  04 / 22‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلــة‬\n        ‫الشــيخ‪ ................... /‬القاضــي باحملكمــة العامــة مبكــة املكرمــة‬\n        ‫املســجل برقــم   ‪ 3443385‬وتاريــخ    ‪20/ 02 / 1434‬ه ـ املتضمــن‬\n      ‫دعــوى‪ ....................... /‬ضــد‪ .......................... /‬بنجالديشــي اجلنســية‪  ،‬‬\n        ‫وبدراســة الصــك وص ــورة ضبط ــه تق ــررت املوافق ــة عل ــى احلكــم‪ .‬واهلل‬\n             ‫املوفــق وصل ــى اهلل عل ــى نبينــا محمــد وعل ــى آل ــه وصحب ــه وســلم ‪.‬‬\n\n\n\n\n‫‪383‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"2e380a2f-49d8-5199-a84b-d3b37251547c","source_page_start":375,"source_page_end":383,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"6b7b54a87b30bcaa4f29e9bee4d5be7cfd91137f21f8827928ec3df101c9aee1","normalized_text_hash":"2e11a995b52e27dc6daa93092815c929ef0ebda44044e57cb9743451a1e5a5e3","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v6-p375-3443385"},{"id":"4a2d1d2b-2947-5ab3-8e82-4b543d43745a","document_type":"judgment","category":"judicial","subcategory":"general","title":"إجارة -محل وقف -سداد أجرة مستحقة -نظر الدعوى غيابي ا يف حق املدعى عليه -وجوب الوفاء بالعقود -اليمن تشرع يف جانب أقوى املتداعين -احلكم بدفع مبلغ األجرة على غائب تعذر تبليغه -الغائب على حجته متى حضر -رفع احلكم الغيابي حملكمة الاستئناف لتعذر تبليغ املدعي عليه.","document_number":"34186236","case_number":"33305127","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة جدة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/13","year":"1434","subject":"إجارة -محل وقف -سداد أجرة مستحقة -نظر الدعوى غيابي ا يف حق املدعى عليه -وجوب الوفاء بالعقود -اليمن تشرع يف جانب أقوى املتداعين -احلكم بدفع مبلغ األجرة على غائب تعذر تبليغه -الغائب على حجته متى حضر -رفع احلكم الغيابي حملكمة الاستئناف لتعذر تبليغ املدعي عليه.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"    ‫تاريخه‪1434/4/13 :‬هـ‬\n                     ‫ُ‬                 ‫َر ْق ُم َّ‬\n                         ‫الص ِّك‪34186236 :‬‬\n                        ‫َر ْق ُم الدعوى‪33305127 :‬‬\n        ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                ‫‪ 34237961‬تاريخه‪1434/6/12 :‬هـ‬\n\n\n\n    ‫إجــارة ‪ -‬محــل وقــف ‪ -‬ســداد أجــرة مســتحقة ‪ -‬نظــر الدعــوى غيابي ـ ًا‬\n    ‫يف حــق املدعــى عليــه ‪ -‬وجــوب الوفــاء بالعقــود ‪ -‬اليمــن تشــرع يف‬\n    ‫جانــب أقــوى املتداعيــن ‪ -‬احلكــم بدفــع مبلــغ األجــرة علــى غائــب‬\n    ‫تعــذر تبليغــه ‪ -‬الغائــب علــى حجتــه متــى حضــر ‪ -‬رفــع احلكــم الغيابــي‬\n                            ‫حملكمــة االســتئناف لتعــذر تبليــغ املدعــي عليــه‪.‬‬\n\n\n\n\n                         ‫‪ .1‬قوله تعالى {يأيها الذين آمنوا أوفوا بالعقود}‪.‬‬\n    ‫‪ .2‬قولــه صلــى اهلل عليــه وســلم (املســلمون علــى شــروطهم) رواه‬\n                                                        ‫الترمــذي وأبــو داوود‪.‬‬\n    ‫‪ .3‬قولــه صلــى اهلل عليــه وســلم (البينــة علــى املدعــي واليمــن علــى مــن‬\n                                                             ‫أنكــر) رواه الترمــذي‪.‬‬\n                        ‫‪ .4‬املادة ‪ 55‬واملادة ‪ 176‬من نظام املرافعات الشرعية‪.‬‬\n\n\n\n\n    ‫ادع ــى املدعــي ض ــد املدع ــى علـ ــيه الغائـ ــب مبطالبتــه بأجــرة محــل‬\n    ‫وقـ ــف‪ ،‬حيــث اســتأجر املدعــى عليــه مــن مــوكل املدعــي ناظــر الوقــف‬\n    ‫محــل يف مجمــع محــات واقعــه يف حــي ‪ ...‬يف جــدة وهــي وقــف وقــد‬\n    ‫أخلــى احملــل عــن طريــق وكيلــه واملبلــغ املتبقــي مــن األجــرة قــدره مائــه‬\n‫‪5‬‬\n\f‫وخمســة وعشــرون ألــف ريــال ‪ ،‬تعــذر تبليغــه حيــث مت البحــث عنــه‬\n‫طريــق الشــرطة ولــم يتــم العثــور عليــه ولــم يتوصــل إلــى أي معلومــة تفيــد‬\n‫مبــكان تواجــده ‪ ،‬حضــر املدعــي أصالــة بصفتــه ناظــر الوقــف وأبــرز‬\n‫أصــل صــك النظــارة وأصــل عقــد اإليجــار ‪ ،‬أحضــر شــاهدين شــهدا‬\n‫باســتئجار املدعــى عليــه احملــل وأنــه أقفــل احملــل منــذ عامــن وعــدم‬\n‫رؤيتــه بعــد إقفــال احملــل وأن وكيــل املدعــي حضــر قبــل عــام وبــاع‬\n‫كامــل بضاعــة احملــل ‪ ،‬مت تعديلهمــا شــرعا ‪ ،‬ثــم جــرى عــرض اليمــن‬\n‫علــى املدعــي علــى صحــة دعــواه وعــدم اســتالمه األجــرة املدعــى بهــا‬\n‫مــن املدعــى عليــه‪ ،‬حلــف املدعــي علــى ذلــك‪ ،‬بنــاء علــى البينــة املعدلــة‬\n‫شــرع ًا وعقــد اإليجــار ومبــا أن األصــل عــدم دفــع األجــرة ومبــا أن اليمــن‬\n‫تشــرع يف جانــب أقــوى املتداعيــن وبنــاء علــى ميــن املدعــي علــى صحــة‬\n‫الدعــوى وعــدم دفــع األجــرة ‪ ،‬صــدر احلكــم بإلــزام املدعــى عليــه بدفــع‬\n‫مبلــغ وقــدره خمســة وعشــرون ألــف ريــال للمدعــي أصالــة بصفتــه ناظــر‬\n‫الوقــف ‪ ،‬إفهــام املدعــي بــأن الغائــب علــى حجتــه متــى حضــر‪ ،‬رفــع‬\n‫احلكــم إلــى محكمــة االســتئناف لتدقيقــه كونــه حكــم علــى غائــب‬\n‫تعــذر تبليغــه ‪ ،‬صــدق احلكــم مــن الدائــرة احلقوقيــة اخلامســة مبحكمــة‬\n                                       ‫االســتئناف مبنطقــة مكــة املكرمــة‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪....‬القاضــي يف احملكمــة العامــة‬\n‫مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة العامــة مبحافظــة جدة‪/‬املســاعد برقــم ‪ 33305127‬وتاريــخ‬\n‫‪1433/05/02‬ه ـ املقيــدة باحملكمــة برقــم ‪ 33687015‬وتاريــخ‬\n\n                                                                                     ‫‪6‬‬\n\f    ‫‪1433/04/12‬ه ـ ففــي يــوم الثالثــاء املوافق‪1433/06/17‬ه ـ افتتحــت‬\n    ‫اجللســة الســاعة ‪ 11 : 30‬وفيهــا حضــر ‪.... ....‬ســعودي اجلنســية مبوجــب‬\n    ‫الســجل املدنــي رقــم ‪....‬بصفتــه وكيــا عــن ‪....‬ســعودي اجلنســية مبوجــب‬\n    ‫الســجل املدنــي رقــم ‪....‬بالوكالــة الصــادرة مــن كتابــة عــدل الثانيــة‬\n    ‫شــمال جــدة برقــم ‪ 23862‬وتاريــخ ‪1432/3/16‬ه ـ جلــد ‪ ، 10430‬ولــم‬\n    ‫يحضــر املدعــى عليــه ‪....‬وال مــن ميثلــه ‪ ،‬ولــم يردنــا مــا يفيــد تبليغــه ‪،‬‬\n    ‫وقــرر املدعــي وكالــة قائــا ‪ :‬أننــي ال أعــرف للمدعــى عليــه أي عنــوان‬\n    ‫‪ ،‬وأطلــب التعميــم عنــه عــن طريــق البحــث والتحــري ‪ .‬ثــم رفعــت اجللســة‬\n    ‫لذلــك ‪ .‬ويف يــوم الســبت املوافــق ‪1433/08/24‬ه ـ افتتحــت اجللســة‬\n    ‫الســاعة ‪ 10 : 30‬وفيهــا حضــر املدعــي ولــم يحضــر املدعــى عليــه ‪ ....‬وال‬\n    ‫مــن ميثلــه ‪ ،‬وقــد وردنــا خطــاب مديــر شــعبة التحريــات والبحــث اجلنائــي‬\n    ‫رقــم ‪/4/20/15825‬ع‪ 21‬وتاريــخ ‪1433/7/14‬هـ املتضمن أنه بالرجوع‬\n    ‫للحاســب اآللــي طرفنــا اتضــح بــأن للمدعــى عليــه عــدة عناويــن األول يف‬\n    ‫جــدة حــي ‪ ...‬شــارع ‪....‬هاتــف ‪....‬جــوال ‪ ،....‬وعنــوان آخــر ‪ .....‬أه ـ ثــم‬\n    ‫رفعــت اجللســة لطلــب املدعــى عليــه عــن طريــق العنــوان املبــن عــن طريــق‬\n    ‫شــعبة التحريــات والبحــث اجلنائــي ‪ .‬ويف يــوم األحــد املوافــق‬\n    ‫‪1434/04/07‬هـ افتتحت اجللســة الســاعة ‪ 11 : 30‬وفيها حضر املدعي‬\n    ‫وكالــة ‪ ،‬ولــم يحضــر املدعــى عليــه ‪....‬وال مــن ميثلــه ‪ ،‬وقــد وردنــا خطاب‬\n    ‫مديــر شــرطة محافظــة جــدة برقــم ‪ 10/1/2/2235‬وتاريــخ‬\n    ‫‪1433/4/11‬ه ـ واملتضمــن (أنــه بالبحــث عــن املذكــور لــم يتــم العثــور‬\n    ‫عليــه ولــم يتــم التوصــل إلــى أي معلومــة تفيــد مبــكان تواجــده) أه ـ‬\n    ‫وعليــه فقــد قــررت النظــر يف الدعــوى غيابيــا يف حــق املدعــى عليــه ‪،‬‬\n    ‫وادعــى املدعــي وكالــة قائــا ‪ :‬لقــد اســتأجر املدعــى عليــه عقــارا هــو‬\n\n\n‫‪7‬‬\n\f‫عبــارة عــن محــل رقــم ‪15‬يف مجمــع محــات واقعــة يف حــي ‪....‬مبحافظــة‬\n‫جــدة ‪ ،‬وهــي وقــف مــن أوقــاف ‪ ...‬الشــهير بوقــف ‪ ...‬بالصــك الصــادر مــن‬\n‫هــذه احملكمــة برقــم ‪ 13/557/11‬وتاريــخ ‪1425/5/23‬ه ـ ‪ ،‬والناظــر‬\n‫علــى هــذا الوقــف هــو موكلــي مبوجــب صــك النظــارة الصــادر مــن‬\n‫محكمــة شــرق املــكال برقــم القيــد ‪ 40‬يف ‪2010/4/22‬م واملصــادق‬\n‫مــن ســفارة اململكــة العربيــة الســعودية يف صنعــاء برقــم ‪ 173983‬يف‬\n‫‪1421/5/4‬ه ـ ومــن وزارة اخلارجيــة برقــم ‪ 18‬يف ‪1431/6/26‬ه ـ ومــن‬\n‫فــرع وزارة العــدل بجــدة رقــم ‪ 5605‬يف ‪1431/6/26‬ه ـ ‪ ،‬وقــد اســتأجره‬\n‫املدعــى عليــه مــن موكلــي بأجــرة ســنوية قدرهــا خمســة وخمســون ألــف‬\n‫ريــال تســلم بدايــة شــهر محــرم لــكل عــام هجــري ‪ ،‬اعتبــارا مــن تاريــخ‬\n‫‪1426/5/1‬ه ـ وينتهــي يف ‪1426/12/29‬ه ـ ‪ ،‬ثــم يبدأ يف ‪1427/1/1‬هـ‬\n‫وحتــى ‪1427/12/29‬ه ـ ويتجــدد املــدة تلقائيــا مــا لــم يخطــر أحــد‬\n‫الطرفــن اآلخــر بعــدم رغبتــه يف التجديــد قبــل انتهــاء مــدة العقــد‬\n‫بشــهرين علــى األقــل ‪ ،‬مبوجــب عقــد اإليجــار املــؤرخ يف ‪1426/5/26‬ه ـ‬\n‫واحملــرر علــى أوراق وقــف ‪ ، ....‬ثــم مت تخفيــض األجــرة الســنوية لتكــون‬\n‫خمســون ألــف ريــال ‪ ،‬وقــد دفــع مــن أجــرة العقــار مــن عــام ‪1430‬ه ـ‬\n‫مبلغــا قــدره خمســة وعشــرون ألــف ريــال وهــي متثــل نصــف أجــرة ذلــك‬\n‫العــام ‪ ،‬ومنــذ النصــف الثانــي مــن عــام ‪1430‬ه ـ وحتــى اآلن لــم يدفــع‬\n‫شــيئا ‪ ،‬وقــد اســتلم موكلــي احملــل يف ‪1433/1/30‬ه ـ عــن طريــق أحــد‬\n‫وكالء املدعــى عليــه واســمه ‪ ،....‬وقــد ترتــب بذمــة املدعــى عليــه للوقف‬\n‫مــن أجــرة العقــار محــل الدعــوى مبلغــا قــدره مائــة وخمســة وعشــرون‬\n‫ألــف ريــال ‪ ،‬وأطلــب إلــزام املدعــى عليــه بدفــع ذلــك املبلــغ ‪ .‬هــذه دعــواي‬\n‫‪ .‬ثــم أبــرز املدعــي وكالــة صــورة مــن صــك النظــارة وصــورة مــن عقــد‬\n\n\n                                                                                       ‫‪8‬‬\n\f    ‫اإليجــار وصــورة مــن صــك احلكــم الصــادر مــن هــذه احملكمــة ‪ ،‬ومت‬\n    ‫إرفاقهــا باملعاملــة ‪ ،‬وبســؤال املدعــي وكالــة عــن موكلــه ألداء اليمــن‬\n    ‫علــى صحــة الدعــوى وعــدم اســتالمه مــن مبلــغ الدعــوى مــن أجــرة العقــار‬\n    ‫محــل الدعــوى شــيئا قــال ‪ :‬أطلــب اإلمهــال إلحضــاره يف اجللســة القادمــة‬\n    ‫‪ .‬ثــم رفعــت اجللســة لذلــك ويف يــوم األربعــاء املوافــق ‪1434/04/10‬ه ـ‬\n    ‫افتتحــت اجللســة الســاعة ‪ 11 : 15‬وفيهــا حضــر املدعــي أصالــة ‪....‬‬\n    ‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪....‬بصفتــه الناظــر علــى‬\n    ‫الوقــف محــل الدعــوى مبوجــب صــك النظــارة الصــادر مــن محكمــة‬\n    ‫شــرق املــكال برقــم القيــد ‪ 40‬يف ‪2010/4/22‬م واملصــادق مــن ســفارة‬\n    ‫اململكــة العربيــة الســعودية يف صنعــاء برقــم ‪ 173983‬يف ‪1421/5/4‬هـ‬\n    ‫ومــن وزارة اخلارجيــة برقــم ‪ 18‬يف ‪1431/6/26‬ه ـ ومــن فــرع وزارة العدل‬\n    ‫بجــدة رقــم ‪ 5605‬يف ‪1431/6/26‬ه ـ ‪ ،‬ولــم يحضــر املدعــى عليــه ‪....‬وال‬\n    ‫مــن ميثلــه ‪ ،‬وأبــرز املدعــي أصــل صــك النظــارة ‪ ،‬وقــد ســبق إرفــاق صــورة‬\n    ‫منــه باملعاملــة ‪ ،‬كمــا أبــرز املدعــي أصــل عقــد اإليجــار املــؤرخ يف‬\n    ‫‪1426/5/26‬ه ـ واحملــرر علــى أوراق وقــف ‪ ، .....‬ومت تزويــد املعاملــة‬\n    ‫بنســخة منــه ‪ ،‬وبســؤاله زيــادة بينــة علــى دعــواه أحضــر للشــهادة وأدائهــا‬\n    ‫كال مــن ‪....‬مينــي اجلنســية مبوجــب اإلقامــة رقــم ‪....‬وهــو مــن مواليــد‬\n    ‫‪1962‬م ‪ ،‬ويعمــل يف شــركة ‪ ،....‬ويســكن يف حــي ‪ ،....‬وليــس بينــه‬\n    ‫وبــن طــريف الدعــوى قرابــة ‪.... ،‬مينــي اجلنســية مبوجــب اإلقامــة رقــم ‪....‬‬\n    ‫وهــو مــن مواليــد ‪1978‬م ‪ ،‬ويعمــل يف مؤسســة بــا ‪ ،....‬ويســكن يف حــي‬\n    ‫‪ ،....‬وليــس بينــه وبــن طــريف الدعــوى قرابــة ‪ ،‬وشــهد األول قائــا ‪:‬‬\n    ‫أشــهد هلل بأننــي أعمــل يف محــل مجــاور حملــل مســتأجر مــن قبــل املدعــى‬\n    ‫عليــه ‪.... ....‬يف مجمــع محــات واقعــة يف حــي ‪....‬واملعــروف باســم‪،....‬‬\n\n\n‫‪9‬‬\n\f‫واملدعــى عليــه مســتأجر لــه منــذ أكثــر مــن خمســة أعــوام ‪ ،‬وقــد أقفــل‬\n‫املدعــى عليــه احملــل منــذ حوالــي عامــن ‪ ،‬ولــم نــره بعــد إقفــال احملــل ‪،‬‬\n‫وقــد حضــر وكيــل للمدعــى عليــه قبــل حوالــي عــام ‪ ،‬وقــام ببيــع كامــل‬\n‫البضاعــة املوجــود يف احملــل بأربعــة آالف ريــال ‪ ،‬وهــي تســاوي أكثــر ‪.‬‬\n‫هكــذا شــهد ‪ .‬وشــهد الثانــي قائــا ‪ :‬أشــهد هلل بأننــي أعمــل يف محــل‬\n‫مجــاور حملــل مســتأجر مــن قبــل املدعــى عليــه ‪....‬يف مجمــع محــات‬\n‫واقعــة يف حــي ‪....‬واملعــروف باســم ‪ ،....‬واملدعــى عليــه مســتأجر لــه منــذ‬\n‫أكثــر مــن ثمانيــة أعــوام ‪ ،‬وقــد أقفــل املدعــى عليــه احملــل منــذ حوالــي‬\n‫عامــن ‪ ،‬ولــم نــره بعــد إقفــال احملــل ‪ ،‬وقــد حضــر وكيــل للمدعــى عليــه‬\n‫قبــل حوالــي عــام ‪ ،‬وقــام ببيــع كامــل البضاعــة املوجــود يف احملــل بأربعة‬\n‫آالف ريــال ‪ ،‬وهــي تســاوي أكثــر ‪ .‬هكــذا شــهد ‪ .‬وعــدال مــن قبــل ‪....‬‬\n‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪....‬و‪....‬ســعودي اجلنســية‬\n‫مبوجــب الســجل املدنــي رقــم ‪....‬وشــهد كل واحــد منهمــا مبفــرده بثقــة‬\n‫وعدالــة الشــاهدين ‪ ،‬وبعــرض اليمــن علــى املدعــي أصالــة علــى صحــة‬\n‫الدعــوى وعــدم اســتالمه مــن مبلــغ الدعــوى شــيئا ‪ ،‬اســتعد لذلــك ‪ ،‬ثــم‬\n‫حلــف قائــا ‪ :‬واهلل العظيــم الــذي ال إلــه إال هــو أن املدعــى عليــه ‪....‬‬\n‫اســتأجر عقــارا هــو عبــارة عــن محــل رقــم ‪15‬يف مجمــع محــات واقعــة‬\n‫يف حــي ‪....‬مبحافظــة جــدة ‪ ،‬وهــي وقــف مــن أوقــاف ‪.........‬الشــهير بوقف‬\n‫‪...‬بالصــك الصــادر مــن هــذه احملكمــة برقــم ‪ 13/557/11‬وتاريــخ‬\n‫‪1425/5/23‬ه ـ ‪ ،‬والناظــر علــى هــذا الوقــف هــو أنــا مبوجــب صــك‬\n‫النظــارة الصــادر مــن محكمــة شــرق املــكال برقــم القيــد ‪ 40‬يف‬\n‫‪2010/4/22‬م واملصــادق مــن ســفارة اململكــة العربيــة الســعودية يف‬\n‫صنعــاء برقــم ‪ 173983‬يف ‪1421/5/4‬ه ـ ومــن وزارة اخلارجيــة برقــم ‪18‬‬\n\n\n                                                                                     ‫‪10‬‬\n\f     ‫يف ‪1431/6/26‬ه ـ ومــن فــرع وزارة العــدل بجــدة رقــم ‪ 5605‬يف‬\n     ‫‪1431/6/26‬ه ـ ‪ ،‬وقــد اســتأجره املدعــى عليــه منــي بأجــرة ســنوية‬\n     ‫قدرهــا خمســة وخمســون ألــف ريــال تســلم بدايــة شــهر محــرم لــكل عــام‬\n     ‫هجــري ‪ ،‬اعتبــارا مــن تاريــخ ‪1426/5/1‬هـ وينتهــي يف ‪1426/12/29‬هـ‬\n     ‫‪ ،‬ثــم يبــدأ يف ‪1427/1/1‬ه ـ وحتــى ‪1427/12/29‬ه ـ ويتجــدد املــدة‬\n     ‫تلقائيــا مــا لــم يخطــر أحــد الطرفــن اآلخــر بعــدم رغبتــه يف التجديــد‬\n     ‫قبــل انتهــاء مــدة العقــد بشــهرين علــى األقــل ‪ ،‬مبوجــب عقــد اإليجــار‬\n     ‫املــؤرخ يف ‪1426/5/26‬ه ـ واحملــرر علــى أوراق وقــف ‪ ،...‬ثــم مت تخيــض‬\n     ‫األجــرة الســنوية لتكــون خمســون ألــف ريــال ‪ ،‬وقــد دفــع مــن أجــرة‬\n     ‫العقــار مــن عــام ‪1430‬ه ـ مبلغــا قــدره خمســة وعشــرون ألــف ريــال وهــي‬\n     ‫متثــل نصــف أجــرة ذلــك العــام ‪ ،‬ومنــذ النصــف الثانــي مــن عــام ‪1430‬ه ـ‬\n     ‫وحتــى اآلن لــم يدفــع شــيئا ‪ ،‬وقــد اســتلمت احملــل يف ‪1433/1/30‬ه ـ‬\n     ‫عــن طريــق أحــد وكالء املدعــى عليــه واســمه ‪ ،....‬وقــد ترتــب بذمــة‬\n     ‫املدعــى عليــه للوقــف مــن أجــرة العقــار محــل الدعــوى مبلغــا قــدره مائــة‬\n     ‫وخمســة وعشــرون ألــف ريــال ‪ ،‬ولــم اســتلم مــن مبلــغ الدعــوى شــيئا حتــى‬\n     ‫اليــوم ‪ .‬هكــذا حلــف ‪ .‬ثــم رفعــت اجللســة لضيــق الوقــت ورغبــة احلضــور‬\n     ‫االنصــراف ويف يــوم الســبت املوافــق ‪1434/04/13‬ه ـ افتتحــت اجللســة‬\n     ‫الســاعة ‪ 12 : 30‬وفيهــا حضــر املدعــي أصالــة ‪....‬ســعودي اجلنســية‬\n     ‫مبوجــب الســجل املدنــي رقــم ‪....‬بصفتــه الناظــر علــى الوقــف محــل‬\n     ‫الدعــوى ‪ ،‬ولــم يحضــر املدعــى عليــه ‪....‬وال مــن ميثلــه ‪ ،‬وبعــد التأمــل ‪،‬‬\n     ‫وبنــاء علــى مــا تقــدم مــن الدعــوى والبينــة املتمثلــة يف صــك النظــارة‬\n     ‫الصادر من محكمة شــرق املكال برقم القيد ‪ 40‬يف ‪2010/4/22‬م‪،‬‬\n     ‫وصــك الصــادر مــن هــذه احملكمــة برقــم ‪ 13/557/11‬وتاريــخ‬\n\n\n‫‪11‬‬\n\f‫‪1425/5/23‬ه ـ ‪ ،‬وشــهادة كال مــن ‪....‬و‪ ....‬واملعدلــة شــرعا ‪ ،‬وبنــاء‬\n‫علــى عقــد اإليجــار املــؤرخ يف ‪1426/5/26‬ه ـ ‪ ،‬وبناء علــى إقرار املدعي‬\n‫وكالة واملدعي أصالة باستالم العني محل الدعوى يف ‪1433/1/30‬هـ‬\n‫عــن طريــق أحــد وكالء املدعــى عليــه واســمه ‪ ،....‬وبنــاء علــى ميــن‬\n‫املدعــي أصالــة علــى صحــة الدعــوى وعــدم اســتالم املدعــي مــن مبلــغ‬\n‫الدعــوى شــيئا ‪ ،‬ومبــا أن األصــل عــدم دفــع األجــرة ‪ ،‬وبنــاء علــى أن‬\n‫اليمــن تشــرع يف جانــب أقــوى املتداعيــان كمــا قــرر ذلــك أهــل العلــم ‪،‬‬\n‫ولقولــه تعالــى (يــا أيهــا الذيــن آمنــوا أوفوا بالعقود) ‪ ،‬وحلديث (املســلمون‬\n‫علــى شــروطهم) رواه الترمــذي وأبــو داوود ‪ ،‬وحلديــث (البينــة علــى‬\n‫املدعــي واليمــن علــى املدعــى عليــه) رواه الترمــذي ‪ ،‬قــال أبــو عيســى ‪:‬‬\n‫العمــل عنــد أهــل العلــم مــن أصحــاب النبــي صلــى اهلل عليــه وســلم‬\n‫وغيرهــم أن البينــة علــى املدعــي واليمــن علــى املدعــى عليــه ‪ ،‬وبنــاء‬\n‫علــى املــادة ‪ 55‬و ‪ 176‬مــن نظــام املرافعــات الشــرعية ‪ ،‬لذلــك كلــه ‪،‬‬\n‫فقــد حكمــت علــى املدعــى عليــه ‪ ....‬بدفــع مبلــغ قــدره مائــة وخمســة‬\n‫وعشــرون ألــف ريــال تســلم للمدعــي ‪ ........‬بصفتــه الناظــر علــى الوقــف‬\n‫محــل الدعــوى ‪ ،‬وأفهمــت املدعــي بــأن الغائــب علــى حجتــه متــى حضــر ‪.‬‬\n‫وبــه حكمــت ‪ .‬وبــه قنــع املدعــي ‪ ،‬وقــررت بعــث املعاملــة حملكمــة‬\n‫االســتئناف لتدقيــق احلكــم كــون احلكــم علــى غائــب تعــذر تبليغــه ‪.‬‬\n‫وأقفلــت اجللســة الســاعة ‪ . 12 : 40‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى‬\n         ‫نبينا محمد وعلى آله وصحبه وسلم ‪ .‬حرر يف ‪1434/04/13‬هـ‬\n‫احلمــد هلل وحــده ‪ ،‬والصــاة والســام علــى رســول اهلل ‪ ،‬وبعــد ‪ :‬ـ نحــن‬\n‫قضــا َة االســتئناف بالدائــرة احلقوقيــة اخلامســة يف محكمــة االســتئناف‬\n‫مبنطقــة مكــة املكرمــة جــرى م ّنــا االطــا ُع علــى هــذا احلكــم الصــادر‬\n\n\n                                                                                    ‫‪12‬‬\n\f     ‫مــن فضيلــة الشــيخ ‪....‬القاضــي باحملكمــة العامــة بجــدة املســجل‬\n     ‫بعــدد ‪ 34186236‬وتاريــخ ‪1434/4/13‬ه ـ املتضمــن دعــوى ‪....‬ضــد‬\n     ‫‪....‬احملكــوم في ــه مبــا دون باطــن الصــك ‪ ،‬وبدراســة احلكــم وص ــورة‬\n     ‫ضبط ــه تق ــررت املوافق ــة عل ــى احلكــم والغائــب علــى حجتــه اذا حضــر ‪.‬‬\n     ‫وباهلل التوفيق وصل ــى اهلل عل ــى نبينا محمد وعل ــى آل ــه وصحب ــه وسلم‪.‬‬\n\n\n\n\n‫‪13‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"612f1ba9-3f27-52bc-993f-69d3ecdc8564","source_page_start":5,"source_page_end":13,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"840db73ddbc1a5141004c95ad3477e1e7f78e920af2825c208f6ddc34599d8a8","normalized_text_hash":"91b347974e6ce7e609d0568329e54df742f40b99bb0299b4d40ac848d3168475","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v7-p5-34186236"},{"id":"3c09ccb0-3d19-506a-b720-90292a7a0d00","document_type":"judgment","category":"judicial","subcategory":"general","title":"إجارة -شيول مسروق -حكم سابق بالتسلم -مطالبة اجره مدة بقاء شيول لدى مشريه -اخلراج بالضمان -العن يف ضمان املدعى عليه -احلكم برد دعوى املدعي.","document_number":"34325602","case_number":"33333050","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض ف","circuit":"الدائرة برد دعوى املدعي وكالة وأخلت سبيل املدعى عليه أصالة","issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/9/24","year":"1434","subject":"إجارة -شيول مسروق -حكم سابق بالتسلم -مطالبة اجره مدة بقاء شيول لدى مشريه -اخلراج بالضمان -العن يف ضمان املدعى عليه -احلكم برد دعوى املدعي.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫تاريخه‪1434/9/24 :‬هـ‬\n                      ‫ُ‬                ‫َر ْق ُم َّ‬\n                         ‫الص ِّك‪34325602 :‬‬\n                        ‫َر ْق ُم الدعوى‪33333050 :‬‬\n        ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n              ‫‪ 34385546‬تاريخه‪1434/12/23 :‬هـ‬\n\n\n\n     ‫إجــارة ‪ -‬شــيول مســروق ‪-‬حكــم ســابق بالتســلم ‪ -‬مطالبــة اجــره مــدة‬\n     ‫بقــاء شــيول لــدى مشــريه ‪ -‬اخلــراج بالضمــان ‪ -‬العــن يف ضمان املدعى‬\n                                       ‫عليــه ‪ -‬احلكــم بــرد دعــوى املدعــي‪.‬‬\n\n\n\n\n     ‫غالمــا فأقــام‬\n                   ‫ً‬     ‫أن رجــا ابتــاع‬‫‪ -1‬مــا روي عــن عائشــة رضــي اهلل عنهــا َّ‬\n     ‫فخاصمــه إلــى النبـ ِّـي‬\n                           ‫َ‬       ‫عيبــا‬\n                                      ‫هلل أن يقيـ َـم ثــم وجــد بــه ً‬   ‫عنــده مــا شــاء ا ُ‬\n     ‫ـتغل غالمــي‬                                                                    ‫ص َّلــى ا ُ‬\n                 ‫هلل علي ـ ِه وس ـ َّل َم فقــال الرجـ ُـل يــا رســولَ اهلل قــد اسـ َّ‬\n     ‫فقــال النبــي عليــه الصــاة والســام (اخلــراج بالضمــان) ‪ ،‬أخرجــه‬\n                                        ‫الترمــذي وأبــو داود يف ســننهما وغيرهمــا‪.‬‬\n     ‫‪ -2‬قــال اإلمــام الســيوطي تعليقــا علــى قاعــدة (اخلــراج بالضمــان) يف‬\n     ‫كتابــه األشــباه والنظائــر‪ :‬قــال أبوعبيــد ‪ :‬اخلــراج يف هــذا احلديــث‬\n     ‫غلــة العبــد يشــتريه الرجــل فيســتغله زمانــا ‪ ،‬ثــم يعثــر منــه علــى عيــب‬\n     ‫دلســه البائــع ‪ ،‬فيــرده ‪ ،‬ويأخــذ جميــع الثمــن ‪ .‬ويفــوز بغلتــه كلهــا؛‬\n                ‫ألنــه كان يف ضمانــه ‪ ،‬ولــو هلــك هلــك مــن مالــه ‪ ،‬انتهــى ‪.‬‬\n     ‫‪ -3‬وكــذا قــال الفقهــاء ‪ :‬معنــاه مــا خــرج مــن الشــيء ‪ :‬مــن غلــة ‪،‬‬\n     ‫ومنفعــة ‪ ،‬وعــن ‪ ،‬فهــو للمشــتري عــوض مــا كان عليــه مــن ضمــان‬\n     ‫امللــك ‪،‬فإنــه لــو تلــف املبيــع كان مــن ضمانــه ‪ ،‬فالغلــة لــه ‪ ،‬ليكــون‬\n                                                    ‫الغنــم يف مقابلــة الغــرم‪ .‬انتهــى‪.‬‬\n\n‫‪25‬‬\n\f‫ادعــى املدعــي بدعــوى ضــد املدعــى عليــه بأنــه صــدر لــه حكــم يقضــي‬\n‫بــأن الشــيول الــذي بحــوزة املدعــى عليــه ملكــه لــذا فيطلــب تقديــر أجرة‬\n‫فتــرة بقائــه يف يــد املدعــى عليــه وإلزامــه بدفعــه لــه ‪ ،‬أقــر املدعــى عليــه‬\n‫بأنــه صــدر عليــه حكــم يلزمــه بتســليم الشــيول الــذي بحوزتــه للمدعــي‬\n‫إال أنــه دفــع بأنــه لــم يســرقه منــه بــل تعــرض لنصــب واحتيــال حيــث قــام‬\n‫بشــرائه من شــخص ظهر فيما بعد بأن املســتند الذي اعتمد عليه مزور‬\n‫لــذا فيطلــب صــرف النظــر عــن دعــواه ‪ ،‬جــرى االطــاع علــى احلكــم‬\n‫الســابق امللــزم للمدعــى عليــه بتســليم العــن للمدعــي بعدمــا ظهــر تزويــر‬\n‫الوثيقــة ‪ -‬ألن املدعــى عليــه وكالــة قــد أقــر بصحــة مــا ذكــره املدعــى‬\n‫وكالــة مــن دخــول املعــدة املدعــى بهــا يف حيــازة موكلــه بطريــق مشــروع‬\n‫«بالشــراء ممــن ادعــى ملكيتــه لهــا» ‪ ،‬وأنــه تعــرض للنصــب واالحتيــال‪،‬‬\n‫غالمــا فأقــام‬‫ً‬      ‫أن رجــا ابتــاع‬\n                                    ‫وملــا روي عــن عائشــة رضــي اهلل عنهــا أن َّ‬\n‫فخاصمــه إلــى النبـ ِّـي ص َّلــى‬    ‫عيبــا‬                           ‫ُ‬\n                              ‫َ‬          ‫عنــده مــا شــاء اهلل أن يقيـ َـم ثــم وجــد بــه ً‬\n‫اهلل علي ِــه وس ـل ََّم فقــال الرجــلُ يــا رســولَ اهلل قــد اســتغلَّ غالمــي فقــال‬ ‫ُ‬\n‫النبــي عليــه الصــاة والســام (اخلــراج بالضمــان) ‪ ،‬أخرجــه الترمــذي‬\n‫وأبــو داود يف ســننهما وغيرهمــا‪ ،‬قــال اإلمــام الســيوطي تعليقــا علــى‬\n‫قاعــدة (اخلــراج بالضمــان) يف كتابــه األشــباه والنظائــر‪« :‬قــال أبوعبيد‪:‬‬\n‫اخلــراج يف هــذا احلديــث غلــة العبــد يشــتريه الرجــل فيســتغله زمانــا‪ ،‬ثــم‬\n‫يعثــر منــه علــى عيــب دلســه البائــع ‪ ،‬فيــرده‪ ،‬ويأخــذ جميع الثمــن ‪ .‬ويفوز‬\n‫بغلتــه كلهــا ‪ ،‬ألنــه كان يف ضمانــه‪ ،‬ولــو هلــك هلــك مــن ماله‪ ،‬انتهى‪،‬‬\n‫وكــذا قــال الفقهــاء ‪ :‬معنــاه مــا خــرج مــن الشــيء‪ :‬مــن غلــة‪ ،‬ومنفعــة‪،‬‬\n\n\n                                                                                                ‫‪26‬‬\n\f     ‫وعــن ‪ ،‬فهــو للمشــتري عــوض مــا كان عليــه مــن ضمــان امللــك ‪،‬فإنــه‬\n     ‫لــو تلــف املبيــع كان مــن ضمانــه ‪ ،‬فالغلــة لــه ‪ ،‬ليكــون الغنــم يف مقابلــة‬\n     ‫الغــرم» انتهــى ‪ ،‬وألن املعــدة طيلــة بقائهــا يف يــد املدعــى عليــه أصالــة يف‬\n     ‫ضمانــه وليســت يف ضمــان مالكهــا ‪ ،‬وقــد نهــى النبــي عليــه الصــاة‬\n     ‫والســام عــن ربــح مــا لــم يضمــن ‪ ،‬ولــكل مــا تقــدم فقــد حكمــت‬\n     ‫الدائــرة بــرد دعــوى املدعــي وكالــة وأخلــت ســبيل املدعــى عليــه أصالــة‬\n     ‫منهــا ‪ ،‬بعــرض احلكــم علــى املدعــي وكالــة قــرر اعتراضــه عليــه فأفهم‬\n                        ‫بالتعليمــات ‪ ،‬صــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n     ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد فلــدي‬\n     ‫أنــا ‪ ...........................‬القاضــي يف احملكمــة العامــة بالريــاض ففــي‬\n     ‫يــوم الثالثــاء املوافــق ‪ 1434/09/22‬ه ـ افتتحــت اجللســة الســاعة‬\n     ‫الواحــدة والنصــف ‪ ،‬حضــر ‪ ............................‬حامــل الســجل املدنــي‬\n     ‫رقــم ‪ ..................‬مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل الثانيــة‬\n     ‫بالدمــام برقــم ‪ 34205‬يف ‪1432/7/6‬ه ـ عــن ‪ ......................‬حامــل‬\n     ‫الســجل املدنــي رقــم ‪ ...................‬والتــي تخولــه حــق املطالبــة واملرافعــة‬\n     ‫واملخاصمــة وإقامــة الدعــاوى انتهــى مضمونهــا‪ ،‬وادعــى علــى احلاضــر‬\n     ‫معــه ‪ ........................‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n     ‫‪ .....................‬بصفتــه وكيــا عــن ‪ ...........................‬ســعودي اجلنســية‬\n     ‫مبوجــب الســجل املدنــي رقــم ‪ .................‬وذلــك بالوكالــة الصــادرة‬\n     ‫مــن كتابــة العــدل الثانيــة بشــرق الريــاض برقــم ‪ 341277286‬وتاريــخ‬\n     ‫‪1434/9/21‬ه ـ قائــا يف دعــواه عليــه ‪ :‬إنــه ملوكلــي شــيول حجــم ‪2966‬‬\n\n‫‪27‬‬\n\f‫نــوع ‪ ....‬ويحمــل رقــم الهيــكل ‪ ...‬صنــع عــام ‪1976‬م ‪ ،‬وقد فقده موكلي‬\n‫واتضــح أنــه مســروق ووجــده بحــوزة املدعــى عليــه أصالة وتقــدم موكلي‬\n‫بدعــوى انتهــت باحلكــم بإلــزام املدعــى عليــه أصالــة بتســليم الشــيول‬\n‫ملوكلــي وذلــك بالصــك الصــادر مــن هــذه احملكمــة برقــم ‪32326862‬‬\n‫يف ‪1432/11/20‬ه ـ ‪ ،‬ونظــرا ألن الشــيول كان بحــوزة املدعــى عليــه‬\n‫مــن تاريــخ ‪1432/6/25‬ه ـ إلــى تاريــخ تســليمه لنــا يف ‪1433/5/4‬ه ـ‬\n‫ونظــرا ألن أجــرة الشــيول اليوميــة ثمامنائــة ريــال لــذا فأطلــب إلــزام‬\n‫املدعــى عليــه أصالــة بأجــرة الشــيول مــدة بقائــه لديــه والبالــغ قدرهــا‬\n‫مائتــان وأربعــون ألــف ريــال هــذه دعــواي ‪ ،‬وبعــرض مــا جــاء يف الدعــوى‬\n‫علــى املدعــى عليــه وكالــة أجــاب قائــا ‪ :‬مــا جــاء يف دعــوى املدعــي‬\n‫وكالــة كلــه صحيــح ‪ ،‬ولكــن موكلــي غــرر بــه حيــث أنــه اشــترى‬\n‫الشــيول مــن شــخص يدعــى ‪ ...........‬مببلــغ قــدره مائــة وثالثــون ألــف ريــال‬\n‫‪ ،‬ولــدي مبايعــة موقعــة بذلــك ‪ ،‬وقــد قــدم لــي ‪ ........‬مــا يثبــت شــراءه‬\n‫للشــيول مــن مالكــه املدعــي أصالــة ‪ ،‬واتضــح فيمــا بعــد أن املســتند‬\n‫الــذي قدمــه لنــا ‪...‬مــزور وغيــر صحيــح ‪ ،‬ومثبــت ذلــك بالصــك املشــار‬\n‫إليــه يف الدعــوى ‪ ،‬وقــد تقــدم موكلــي بدعــوى ضــد ‪ ..........‬ال زالــت‬\n‫قيــد النظــر ‪ ،‬وبنــاء عليــه فــإن موكلــي مغــرر بــه ووقــع ضحيــة نصــب‬\n‫واحتيــال لــذا فــإن موكلــي غيــر مســتعد بدفــع األجــرة املدعــى بهــا‬\n‫هكــذا أجــاب ‪ ،‬وبعــرض مــا جــاء يف جوابــه علــى املدعــي وكالــة أجــاب‬\n‫قائــا مــا ذكــره املدعــي وكالــة مــن أنــه اشــترى الشــيول بنــاء علــى‬\n‫مبايعــة مــزورة ‪ ،‬وأنــه قــد وقــع ضحيــة نصــب واحتيــال صحيــح ‪ ،‬والبائــع‬\n‫املســمى ‪ ..............‬ال يعــرف لــه مــكان وال هويــة ولــم جنــد عنــه معلومــات‬\n‫‪ ،‬ولكــن موكلــي يطلــب بإلزامــه بأجــرة الفتــرة التــي بقي فيها الشــيول‬\n\n\n                                                                                       ‫‪28‬‬\n\f     ‫حتــت تصرفــه هكــذا أجــاب ‪ ،‬فأفهمــت املدعــي وكالــة بــأن وكالتــه‬\n     ‫ال تخولــه اإلقــرار عــن موكلــه فأجــاب قائــا أطلــب إمهالــي إلبــاغ‬\n     ‫موكلــي باحلضــور أو تزويــدي بوكالــة تخولنــي اإلقــرار هكــذا قــرر‬\n     ‫ثــم جــرى االطــاع علــى الصــك املشــار إليــه يف الدعــوى فوجدتــه تضمــن‬\n     ‫تبــن تزويــر املســتند املتضمــن املبايعــة مــن املدعــي أصالــة للمدعــو ‪،...‬‬\n     ‫وتضمــن احلكــم علــى املدعــى عليــه ‪ ..............‬بتســليم الشــيول املدعــى‬\n     ‫بــه للمدعــي ‪ ............‬ا‪.‬ه ـ ‪ ،‬ثــم رفعــت اجللســة إلمهــال املدعــي وكالــة‬\n     ‫إلــى يــوم اخلميــس املوافــق ‪1434/9/24‬ه ـ الســاعة الواحــدة ‪ .‬ويف املوعــد‬\n     ‫احملــدد حضــر املدعــي وكالــة وقــدم وكالتــه عــن موكلــه الصــادرة من‬\n     ‫كاتــب العــدل باحلرجــة برقــم ‪ 33‬يف ‪1434/9/23‬ه ـ اجللد ‪ 116‬واملخول‬\n     ‫لــه فيهــا باإلقــرار واإلنــكار وقبــول األحــكام واالعتــراض عليهــا فيمــا‬\n     ‫يخــص الشــويل اخلــاص بــه انتهــى مضمونهــا ‪ ،‬كمــا حضــر املدعــى عليه‬\n     ‫وكالــة ‪ ،‬فجــرى عــرض مــا ســبق ضبطــه عليهمــا فصادقــا عليــه ‪ ،‬فبناء‬\n     ‫علــى مــا تقــدم مــن الدعــوى واإلجابــة ومــا قــرره الطرفــان ‪ ،‬ومبــا أن‬\n     ‫املدعــى عليــه وكالــة قــد أقــر بصحــة مــا ذكــره املدعــى عليــه وكالــة‬\n     ‫مــن أن دخــول املعــدة املدعــى بهــا يف حيازة موكله كان بطريق مشــروع‬\n     ‫بالشــراء ممــن ادعــى ملكيتــه لهــا ‪ ،‬وأنــه تعــرض للنصــب واالحتيــال‪،‬‬\n     ‫غالمــا فأقــام‬‫ً‬      ‫أن رجـ ًـا ابتــاع‬\n                                           ‫وملــا روي عــن عائشــة رضــي اهلل عنهــا أن َّ‬\n     ‫فخاصمــه إلــى النبـ ِّـي ص َّلــى‬      ‫عيبــا‬                           ‫ُ‬\n                                   ‫َ‬            ‫عنــده مــا شــاء اهلل أن يقيـ َـم ثــم وجــد بــه ً‬\n     ‫اهلل علي ِــه وس ـل ََّم فقــال الرجــلُ يــا رســولَ اهلل قــد اســتغلَّ غالمــي فقــال‬   ‫ُ‬\n     ‫النبــي عليــه الصــاة والســام (اخلــراج بالضمــان) ‪ ،‬أخرجــه الترمــذي‬\n     ‫وأبــو داود يف ســننهما وغيرهمــا‪ ،‬قــال اإلمــام الســيوطي تعليقــا علــى‬\n     ‫قاعــدة (اخلــراج بالضمــان) يف كتابــه األشــباء والنظائــر‪ « :‬قــال أبــو‬\n\n\n‫‪29‬‬\n\f‫عبيــد‪ :‬اخلــراج يف هــذا احلديــث غلــة العبــد يشــتريه الرجــل فيســتغله‬\n‫زمانــا‪ ،‬ثــم يعثــر منــه علــى عيــب دلســه البائــع ‪ ،‬فيــرده ‪ ،‬ويأخــذ جميــع‬\n‫الثمــن ‪ .‬ويفــوز بغلتــه كلهــا؛ ألنــه كان يف ضمانــه ‪ ،‬ولــو هلــك هلــك‬\n‫مــن مالــه ‪ ،‬انتهــى ‪ ،‬وكــذا قــال الفقهــاء ‪ :‬معنــاه مــا خــرج مــن الشــيء‬\n‫‪ :‬مــن غلــة ‪ ،‬ومنفعــة ‪ ،‬وعــن ‪ ،‬فهــو للمشــتري عــوض مــا كان عليــه‬\n‫مــن ضمــان امللــك ‪ ،‬فإنــه لــو تلــف املبيــع كان مــن ضمانــه ‪ ،‬فالغلــة لــه‬\n‫‪ ،‬ليكــون الغنــم يف مقابلــة الغــرم» انتهــى ‪ ،‬وألن املعــدة طيلــة بقائهــا يف‬\n‫يــد املدعــى عليــه أصالــة وهــي يف ضمانــه وليســت يف ضمــان مالكهــا ‪،‬‬\n‫وقــد نهــى النبــي عليــه الصــاة والســام عــن ربــح مــا لــم يضمــن ‪ ،‬ولــكل‬\n‫مــا تقــدم فقــد حكمــت بــرد دعــوى املدعــي وكالــة وأخليــت ســبيل‬\n‫املدعــى عليــه أصالــة منهــا ‪ ،‬وبعــرض احلكــم علــى املدعــى وكالــة قــرر‬\n‫اعتراضــه عليــه مســتعدا بتقــدمي الئحــة اعتراضيــة ‪ ،‬فأفهــم بأنــه ســيتم‬\n‫تســليمه نســخة مــن صــك احلكــم حــاال ‪ ،‬ولــه تقــدمي اعتراضــه عليــه‬\n‫خــال ثالثــن يومــا مــن تاريــخ هــذا اليــوم ‪ ،‬وإذا لــم يتقــدم باعتراضــه‬\n‫خاللهــا ســقط حقــه يف االعتــراض واكتســب احلكــم القطعيــة ففهــم‬\n‫ذلــك ‪ ،‬وختمــت اجللســة الســاعة الواحــدة والنصــف ‪ ،‬وبــاهلل التوفيــق‪،‬‬\n‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n                                                                ‫‪1434/9/24‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد‪ ..‬فقــد اطلعنــا نحــن قضــاة الدائــرة اجلزائيــة‬\n‫األولــى مبحكمــة االســتئناف بالريــاض علــى املعاملــة الــواردة مــن‬\n‫فضيلــة رئيــس احملكمــة العامــة بالريــاض برقــم ‪ 33905024‬وتاريــخ‬\n‫‪1434/11/13‬ه ـ واملرفــق بهــا الصــك الصــادر مــن فضيلــة القاضــي بالم‬\n‫حكمــة‪ ............................/‬برقــم ‪ 34325602‬وتاريــخ ‪1434/9/24‬ه ـ‬\n\n\n                                                                                    ‫‪30‬‬\n\f     ‫واخلــاص بدعــوى‪ ، ............ /‬ضــد‪ ،................. /‬وموضوعهــا أجــرة‬\n     ‫شــيول‪ ،‬وانتهــت الدراســة والتدقيــق باملصادقــة علــى احلكــم لعــدم‬\n     ‫موجــب املالحظــة ‪ ،‬واهلل املوفــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                                             ‫آلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n‫‪31‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"612f1ba9-3f27-52bc-993f-69d3ecdc8564","source_page_start":25,"source_page_end":31,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"1fa74e8a1a861dde619b832d1d99a65f805baec647867061058d83cd42dd3e9e","normalized_text_hash":"06a238eba7a1f630a4d3eb0b6cf6e32c042009ded87ee7bc294643113ed2165e","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v7-p25-34325602"},{"id":"fb8d65f6-4331-59c3-b371-6c0e11161699","document_type":"judgment","category":"judicial","subcategory":"general","title":"إجارة -أيجار منتهي بالتملك -مطالبة بتسليم سيارة بديلة ورفع اسم من القائمة السوداء وتعويض عن ضرر -دفع املدعى عليها بفسخ العقد واملطالبة بأجرة -رد دعوى املدعي وإلزامه بدفع أجرة فترة بقاء السيارة بيده ورفع اسمه من القائمة بعدها.","document_number":"4311281","case_number":"33360874","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة جدة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/9/2","year":"1434","subject":"إجارة -أيجار منتهي بالتملك -مطالبة بتسليم سيارة بديلة ورفع اسم من القائمة السوداء وتعويض عن ضرر -دفع املدعى عليها بفسخ العقد واملطالبة بأجرة -رد دعوى املدعي وإلزامه بدفع أجرة فترة بقاء السيارة بيده ورفع اسمه من القائمة بعدها.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"  ‫تاريخه‪1434/9/2 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                     ‫الص ِّك‪4311281 :‬‬\n                   ‫َر ْق ُم الدعوى‪33360874 :‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n            ‫‪ 35105065‬تاريخه‪1435/1/4 :‬هـ‬\n\n\n\n‫إجــارة ‪ -‬أيجــار منتهــي بالتملــك ‪ -‬مطالبــة بتســليم ســيارة بديلة ورفع‬\n‫اســم مــن القائمــة الســوداء وتعويــض عــن ضــرر ‪ -‬دفــع املدعــى عليهــا‬\n‫بفســخ العقــد واملطالبــة بأجــرة ‪ -‬رد دعــوى املدعــي وإلزامــه بدفــع أجــرة‬\n              ‫فتــرة بقــاء الســيارة بيــده ورفــع اســمه مــن القائمــة بعدهــا‪.‬‬\n\n\n\n\n                 ‫‪ .1‬قول اهلل تعالى‪ « :‬يا أيها الذين آمنوا أوفوا بالعقود »‪.‬‬\n‫‪ .2‬قول النبي صلى اهلل عليه وســلم‪« :‬املســلمون على شــروطهم»أخرجه‬\n                                                              ‫الترمذي وأبو داوود‪.‬‬\n‫‪ .3‬قــول النبــي صلــى اهلل عليــه وســلم‪ « :‬البينــة علــى املدعــي واليمــن‬\n‫علــى املدعــى عليــه» أخرجــه الترمــذي وقــال العمــل عنــد أهــل العلــم‬\n‫مــن أصحــاب النبــي صلــى اهلل عليــه وســلم وغيرهــم أن البينــة علــى‬\n                                          ‫املدعــي واليمــن علــى املدعــى عليــه‪.‬‬\n‫‪ .4‬قــال البهوتــي يف الــروض املربــع ‪« :‬وهــي أي اإلجــارة عقــد الزم مــن‬\n‫الطرفــن ألنهــا نــوع مــن البيــع فليــس ألحدهمــا فســخها لغيــر عيــب أو‬\n‫نحــوه ‪ ،‬فــإن آجــره شــيئا ومنعــه أي منــع املؤجــر املســتأجر الشــيء املؤجــر‬\n‫كل املــدة أو بعضهــا بــأن ســلمه العــن ‪ ،‬ثــم حولــه قبــل تقضــي املــدة فــا‬\n‫شــيء لــه مــن األجــرة ألنــه لــم يســلم لــه مــا تناولــه عقــد اإلجــارة ‪ ،‬فلــم‬\n‫يســتحق شــيئا ‪ ،‬وإن بــدأ اآلخــر أي املســتأجر فتحــول قبــل انقضائها أي‬\n\n                                                                                         ‫‪32‬‬\n\f     ‫انقضــاء مــدة اإلجــارة فعليــه جميــع األجــرة ألنهــا عقــد الزم ‪ ،‬فترتــب‬\n     ‫مقتضاهــا ‪ ،‬وهــو ملــك املؤجــر األجــر واملســتأجر املنافــع ‪ ...‬وإن وجــد‬\n     ‫املســتأجر العــن معيبــة أو حــدث بهــا عنــده عيــب ‪ -‬وهــو مــا يظهــر بــه‬\n     ‫تفــاوت األجــر‪ -‬فلــه الفســخ إن لــم يــزل بــا ضــرر يلحقــه وعليــه أجــرة‬\n     ‫مــا مضــى الســتيفائه املنفعــة فيــه ولــه اإلمضــاء مجانــا واخليــار علــى‬\n                                                                        ‫التراخــي»‪.‬‬\n\n\n\n\n     ‫أقــام املدعــى علــى الشــركة املدعــى عليهــا دعــوى يطالبهــا بتســليمه‬\n     ‫ســيارة بدليــه للســيارة التــي اشــتراها منهــا وتعرضــت حلــادث وقــام‬\n     ‫بتســليمها إلــى الشــركة وتعويضــه عــن اخلســائر التــي حلقــت بــه علــى‬\n     ‫حســب مــا تقــدره احملكمــة ودفعــت الشــركة بــأن العقــد املبــرم بينهمــا‬\n     ‫هــو عقــد إيجــار مــع وعــدة بهبــة وليــس عقــد بيــع وطلبــت إلــزام املدعــى‬\n     ‫بســداد باقــي املســتحق عليــه مــن قيمــة اإليجــار غيــر املدفــوع والشــرط‬\n     ‫اجلزائــي وبعــد النظــر قــررت احملكــة إلــزام املدعــى بســداد مبلــغ وقــدره‬\n     ‫ألفــان وخمســمائة واثنــان وســتون ريــا ًال وثمانــون هللــة قيمــة أجــرة‬\n     ‫مســتحقة وكذلــك مبلــغ ســتة عشــر ألف ـ ًا وثمامنائــة وأربعــة وعشــرون‬\n     ‫ألــف ريــال قيمــة شــرط جزائــي وألزمــت املدعــى عليهــا بعــد ســداد املبلــغ‬\n     ‫برفــع اســمه مــن شــركة ‪ ...‬وردت ماعــدا ذلــك مــن طلبــات وقــد اعتــرض‬\n     ‫املدعــى عليهــا علــى احلكــم‪ ،‬جــرى التصديــق مــن محكمــة االســتئناف‬\n\n\n\n\n‫‪33‬‬\n\f‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ........................‬القاضــي يف احملكمــة‬\n‫العامــة مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n‫رئيــس احملكمــة العامــة مبحافظــة جدة‪/‬املســاعد برقــم ‪33360874‬‬\n‫وتاريــخ ‪1433/05/25‬ه ـ املقيــدة باحملكمــة برقــم ‪33988853‬‬\n‫وتاريــخ ‪1433/05/25‬ه ـ ففــي يــوم الســبت املوافق‪1433/08/10‬ه ـ‬\n‫افتتحــت اجللســة الســاعة ‪ 02 : 30‬وفيهــا حضــر املدعــي ‪........................‬‬\n‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ......................‬وادعــى‬\n‫علــى احلاضــر معــه ‪ ......................‬ســعودي اجلنســية مبوجــب الســجل‬\n‫املدنــي رقــم ‪ ....................‬بصفتــه وكيــا عــن ‪ ........................‬ســعودي‬\n‫مبوجــب ســجل مدنــي رقــم ‪ ......................‬بوكالتــه عــن‪.....................‬‬\n‫اصالــة عــن نفســه وبصفتــه مديــر وشــريك يف شــركة ‪ ............‬مبوجــب‬\n‫قــرار الشــركاء املوثــق مــن كاتــب العــدل املكلــف بالغرفــه التجاريــة‬\n‫الصناعيــة بجــده برقــم ‪ 115‬صحيفــه رقــم ‪ 120‬مجلــد ‪ / 18‬ش ‪ /‬م‬\n‫يف ‪ 1429 / 02 / 06‬ه ـ واملوثــق عقــد تاسيســها لــدى كاتــب عــدل‬\n‫الغرفــه التجاريــة برقــم ‪ 181‬صحيفــه رقــم ‪ 183‬مجلــد ‪ / 10‬ش ‪ /‬م يف‬\n‫‪ 1428/ 02/03‬ه ـ والســجل التجــاري رقــم ‪ ............‬يف ‪1428/07/08‬هـ‬\n‫بالوكالــه رقــم ‪ 53832‬يف ‪ 1430 / 06 / 02‬جلــد ‪ 8471‬الصــادره مــن‬\n‫هــذه االداره وبصفتــه صاحــب مؤسســة ‪ ......................‬مبوجــب ســجل‬\n‫جتــاري رقــم ‪ 4030065137‬يف ‪1409/9/11‬ه ـ بالوكالــه رقــم ‪52749‬‬\n‫يف ‪ 1430 / 05 / 29‬ه ـ اجللــد ‪ 8460‬صــادره مــن هــذه االداره وبصفتــه‬\n‫صاحــب مؤسســة ‪ ...‬لنقــل احلجــاج فــرع ‪ ............................‬ســجل جتــاري‬\n\n                                                                                           ‫‪34‬‬\n\f     ‫رقــم ‪ ......................‬يف ‪ 1419 / 10 / 10‬ه ـ بالوكالــه رقــم ‪52735‬‬\n     ‫يف ‪1430 / 05 / 29‬ه ت اجللــد ‪ 8460‬الصــادره مــن هــذه االداره ‪،‬‬\n     ‫قائــا ‪ :‬لقــد قمــت بشــراء ســيارة مــن نــوع ‪ .......‬موديــل ‪2012‬م بنظــام‬\n     ‫التأجيــر املنتهــي بالتمليــك مببلــغ وقــدره مائــة وأربعــون الــف ريــال‬\n     ‫بأقســاط شــهري مببلــغ الفــان ومائــة ريــال ‪ ،‬وقــد وقــع حــادث ســير يف‬\n     ‫‪1432/10/11‬ه ـ ومت إدانــة الطــرف األخــر بنســبة ‪ ، %100‬وقــد ســلمت‬\n     ‫الســيارة للمدعــى عليهــا يف ‪1432/10/25‬ه ـ وحيــث أن العقــد ينــص‬\n     ‫علــى إعطائــي ســيارة بديلــة ولــم يتــم ذلــك ‪ ،‬وباعــت املدعــى عليهــا‬\n     ‫ســيارتي دون الرجــوع لــي ‪ ،‬وطالبتنــي املدعــى عليهــا بفــرق ســعر البيــع‬\n     ‫وقــدره خمســون ألــف ريــال ‪ ،‬وقــد تكبــدت مــن اخلســائر جــراء هــذا‬\n     ‫التصــرف‪ ،‬وحرمانــي مــن االســتفادة ســيارة بديلــة نتيجــة ذلــك احلــادث‪،‬‬\n     ‫وإدراج اســمي يف القائمــة الســوداء لــدى شــركة (‪ )...‬وتعطيــل جميــع‬\n     ‫مصاحلــي املاليــة ‪،‬ومنــذ ‪1432/10/25‬ه ـ وحتــى اليــوم وأنــا محــرم‬\n     ‫مــن التنقــل بســيارتي اخلاصــة ‪ ،‬واعتمــدت يف ذلــك علــى النقــل العــام‪،‬‬\n     ‫أطلــب إلــزام املدعــى عليهــا بإعطائــي ســيارة بديلــة ‪ ،‬وتعويضــي عــن‬\n     ‫خســائري بحســب مــا يــراه فضيلتكــم ‪ .‬هــذه دعــواي ‪ .‬وبســؤال املدعــي‬\n     ‫عــن العقــد املبــرم بــن الطرفــن وتقريــر احلــادث قــال ‪ :‬ليــس لــدي‬\n     ‫نســخة مــن العقــد ‪ ،‬واملدعــى عليهــا ممتنعــة مــن تســليمي نســخة منــه‬\n     ‫‪ ،‬وكل مــا يخــص احلــادث ســلمته للمدعــى عليهــا ‪ .‬وبعــرض ذلــك علــى‬\n     ‫املدعــى عليــه وكالــة قــال ‪ :‬أطلــب اإلمهــال للــرد ‪ .‬ثــم رفعــت اجللســة‬\n     ‫لذلــك ‪ .‬ويف يــوم االثنــن املوافــق ‪1433/09/18‬ه ـ افتتحــت اجللســة‬\n     ‫الســاعة ‪ 10 : 30‬وفيهــا حضــر املدعــي وحضــر ‪ .........‬ســعودي اجلنســية‬\n     ‫مبوجــب الســجل املدنــي رقــم ………………‪ ..‬بصفتــه وكيــا عــن‬\n\n\n‫‪35‬‬\n\f‫…………………‪ .‬سـع ــودي اجلنســية مبوج ــب السـج ــل املدنــي رق ــم‬\n‫‪ ....................‬بصفتــه وكيــا عــن ‪ ...........................‬بالوكالــة رقــم‬\n‫‪ 52749‬يف ‪1430 /5/ 29‬ه ـ جلــد ‪ 8460‬صــادرة مــن كتابــة عــدل‬\n‫الثانيــة شــمال محافظــة جــدة بصفتــه صاحــب مؤسســة ‪..................‬‬\n‫ســجل جتــاري رقــم ‪ ..............‬يف ‪1409/9/11‬ه ـ وبصفتــه وكيــا‬\n‫عــن ‪ .........................‬بالوكالــة رقــم ‪ 52735‬يف ‪1430/5/29‬ه ـ جلــد‬\n‫‪ 8460‬صــادرة مــن كتابــة عــدل الثانيــة شــمال محافظــة جــدة بصفتــه‬\n‫صاحــب مؤسســة‪ ................‬لنقــل احلجــاج فــرع مؤسســة ‪.........................‬‬\n‫ســجل جتــاري رقــم ‪.........................00‬يف ‪1419 / 10/10‬ه ـ وبصفتــه‬\n‫وكيــا عــن ‪ ...........................‬بالوكالــة رقــم ‪ 53832‬يف ‪1430 /6 /2‬‬\n‫ه ـ جلــد ‪ 8471‬صــادرة مــن كتابــة عــدل الثانيــة شــمال محافظــة جــدة‬\n‫بصفتــه مديــر وشــريك يف شــركة ‪ .....................‬ســجل جتــاري رقــم‬\n‫‪ ....................‬وتاريــخ ‪1428 /7/8‬ه ـ ‪ ،‬مبوجــب الوكالــة الصــادرة‬\n‫مــن كتابــة العــدل الثانيــة شــمال محافظــة جــدة برقــم ‪ 4590‬وتاريــخ‬\n‫‪1431/1/16‬ه ـ جلــد ‪ ، 9192‬وبســؤال املدعــى عليــه وكالــة عمــا طلــب‬\n‫الوكيــل الســابق اإلمهــال مــن أجلــه قــدم مذكــرة هــذا نصهــا ‪ :‬بــدأ‬\n‫املدعــي دعــواه بدايــة خاطئــة عندمــا قــال أنــه اشــترى مــن املدعــى عليهــا‬\n‫ســيارة بايجــار منتهــي بالتمليــك ‪ .‬واحلقيقــة أنــه لــم يشــتر وإمنــا اســتأجر‬\n‫الســيارة مبوجــب عقــد تأجيــر مــع الوعــد بالهبــة ‪ .‬فهــو لــم يتملــك الســيارة‬\n‫وهــو مجــرد مســتأجر ‪ .‬وأرفــق صــورة العقــد احملــرر بــن الطرفــن بتاريخ‬\n‫‪2011/4/17‬م ‪(.‬صــورة عقــد تأجيــر مــع الوعــد بالهبــة (وقــد تســلم‬\n‫املدعــي الســيارة املؤجــرة بتاريــخ ‪2011/4/20‬م وظــل ينتفــع بهــا حتــى‬\n‫ســحبت املدعــى عليهــا الســيارة وفســخت العقــد بعــد اســتعمال مدتــه‬\n\n\n                                                                                         ‫‪36‬‬\n\f     ‫(‪ )6‬أشــهر‪ ،‬وســبب الفســخ أن املدعــي أثنــاء حيازتــه للســيارة توقــف عــن‬\n     ‫دفــع أقســاط األجــرة املتفــق عليهــا يف العقــد ‪ .‬ولــم يســدد ســوى أربعــة‬\n     ‫أقســاط وجــزء مــن القســط اخلامــس مبجمــوع ‪ 14.710‬ريــال وتوقــف‬\n     ‫عــن الدفــع بتاريــخ ‪2011/9/1‬م ‪ .‬وتطبيقـ ًا لنــص املــادة ‪ 1/15‬مــن العقــد‬\n     ‫التــي تعــدد اإلخــاالت التــي جتيــز للمؤجــر فســخ العقــد ومنهــا عــدم‬\n     ‫ســداد أقســاط األجــرة الشــهرية يف مواعيدهــا ‪ ،‬قامــت املدعــى عليهــا‬\n     ‫بســحب الســيارة وفســخ العقــد بتاريــخ ‪2011/12/29‬م وبذلــك يكــون‬\n     ‫العقــد قــد انتهــى بالفســخ وفقـ ًا حلكــم املــادة ‪ 16‬مــن العقــد ‪ .‬وال معنــى‬\n     ‫ملــا جــاء بالئحــة الدعــوى مــن أن العقــد ينــص علــى اعطــاء ســيارة بديلــة‬\n     ‫‪ ،‬كمــا أنــه ال معنــى ملــا جــاء بالالئحــة مــن أن الشــركة ضربــت بذلــك‬\n     ‫عــرض احلائــط وباعــت ســيارة املدعــي دون الرجــوع إليــه ‪ ،‬فاملدعــي لــم‬\n     ‫يتملك الســيارة ولم يكن إال مســتأجر ًا لها ‪ .‬وال ســند من شــرع أو نظام‬\n     ‫أو عقــد ملــا يطلبــه املدعــي يف الئحــة دعــواه مــن اعطائــه ســيارة بديلــة‬\n     ‫وتعويــض اخلســائر املترتبــة علــى ذلــك ‪ .‬لهــذا األســباب تطلــب موكلتــي‬\n     ‫صــرف النظــر عــن دعــوى املدعــي ‪ .‬ووفقـ ًا ملــا تنــص عليــه املــادة ‪ 14‬مــن‬\n     ‫العقــد ‪ ،‬تطلــب الشــركة املدعيــة احلكــم بإلــزام املدعــي بــأن يدفــع‬\n     ‫لهــا املبالــغ اآلتيــة ‪ :‬أجــرة الســنة األولــى ‪ 50.472‬ريــال (مــادة ‪-3/14‬‬\n     ‫أ مــن العقــد) قيمــة (‪ )8‬أقســاط شــهرية ‪ 8‬؟ ‪ 16.824 = 2.103‬ريــال‬\n     ‫(مــادة ‪-3/14‬ج ـ مــن العقــد) املجمــوع ‪ 67.296‬ريــال ‪،‬يخصــم مــا ســبق‬\n     ‫ســداده مــن أقســاط ‪ 14.710‬ريــال ‪ ،‬صــايف املســتحق يف ذمــة املدعــي‬\n     ‫‪52.586‬ريــال ‪ ،‬ويثبــت العقــد املرفــق صورتــه أن املدعــي تســلم نســخة‬\n     ‫عنــد التوقيــع فليــس صحيح ـ ًا أن املدعــى عليهــا ممتنعــة عــن تســليمه‬\n     ‫صــورة العقــد ‪ .‬وتطلــب الشــركة املدعــى عليهــا احلكــم بإلــزام املدعــى‬\n\n\n‫‪37‬‬\n\f‫بــأن يدفــع لهــا مبلــغ ‪52.586‬ريــال املســتحق يف ذمتــه وفق ـ ًا ألحــكام‬\n‫العقــد وصــرف النظــر عــن دعــوى املدعــي لعــدم صحتهــا ‪ .‬وبعــرض ذلــك‬\n‫علــى املدعــي قــال ‪ :‬أطلــب اإلمهــال للــرد ‪ .‬ثــم رفعــت اجللســة لذلــك ‪ .‬ويف‬\n‫يــوم االثنــن املوافــق ‪1433/10/16‬ه ـ افتتحــت اجللســة الســاعة ‪02 : 00‬‬\n‫وفيهــا حضــر الطرفــان ‪ ،‬وقــدم املدعــي مذكــرة مكونــة مــن ورقتــن‬\n‫وعــدد ثمــان مرفقــات ‪ ،‬وتتضمــن أن الســيارة املســتأجرة محــل الدعــوى‬\n‫مأمــن عليهــا تأمينــا شــامال واحلــادث وقــع يف ‪1432/11/10‬ه ـ بنســبة‬\n‫خطــأ ‪ %100‬علــى الطــرف اآلخــر ‪ ،‬وتســلمت املدعــى عليهــا الســيارة‬\n‫يف ‪1432/11/24‬ه ـ بقصــد إصالحهــا علــى التأمــن ‪ ،‬وقامــت املدعــى‬\n‫عليهــا ببيــع الســيارة يف ‪1433/2/4‬ه ـ بعــد فســخ العقــد مــن طرفهــم ‪،‬‬\n‫مت إدراج اســم املدعــي يف القائمــة الســوداء لــدى شــركة ســمه ‪ ،‬وأنــه لــم‬\n‫يتأخــر يف ســداد األجــرة قبــل احلــادث‪ ،‬وأن آخــر أجرة دفعهــا قبل احلادث‬\n‫بشــهر ‪ ،‬ويطلــب تعويضــه عــن الضــرر املــادي واملعنــوي الــذي وقــع عليــه‬\n‫جــراء بيــع الســيارة وإدراج اســمه يف شــركة ســمه ‪ ،‬وبعرضهــا علــى‬\n‫املدعــى عليــه وكالــة قــال ‪ :‬أطلــب اإلمهــال للــرد يف اجللســة القادمــة ‪ .‬ثــم‬\n‫رفعــت اجللســة لذلــك ‪ .‬ويف يوم األربعــاء املوافق‪1433/11/10‬هـ افتتحت‬\n‫اجللســة الســاعة ‪ 10 : 00‬وفيهــا حضــر الطرفــان ‪ ،‬وقــدم املدعــى عليــه‬\n                                                 ‫وكالــة مذكــرة هــذا نصهــا ‪:‬‬\n‫‪ .1‬ال عالقــة للحــادث الــذي وقــع للســيارة ونســبة اخلطــأ بفســخ العقــد‬\n‫وســحب الســيارة ‪ ،‬فقــد ادخلــت الســيارة الورشــة بعــد احلــادث ومت‬\n‫اصالحهــا وانتهــى االصــاح علــى حســاب التأمــن واتصلــت الورشــة‬\n‫باملدعــي وأشــعرته بــأن الســيارة معــدة الســتالمها وطلبــت حضــوره‬\n                                        ‫الســتالمها ولكنــه رفــض االســتالم ‪.‬‬\n\n\n                                                                                       ‫‪38‬‬\n\f     ‫‪ .2‬كان آخــر قســط ســدده املســتأجر هــو القســط رقــم (‪ )4‬اســتحقاق‬\n     ‫‪2011/8/1‬م ومبلــغ ‪101‬ريــال جــزء مــن القســط رقــم (‪ )5‬اســتحقاق‬\n                  ‫‪2011/9/1‬م ‪ ،‬وكان هــذا الســداد بتاريــخ ‪2011/9/26‬م‬\n     ‫‪ .3‬وتوقــف املدعــي عــن ســداد األقســاط بعــد ذلــك ‪ ،‬وعندمــا وقــع‬\n     ‫احلــادث للســيارة وادخلهــا الصيانــة ومت اصالحهــا وأشــعرته الصيانــة‬\n     ‫ورفــض اســتالمها ‪ ،‬قامــت شــركة أقســاط عــن طريــق مندوبهــا‬\n     ‫‪ .................‬باالتصــال بــه حلثــه علــى ســداد األقســاط واســتالم الســيارة‬\n     ‫ولكنــه رفــض اســتالم الســيارة أو ســداد األقســاط وكانــت اجابتــه‬\n     ‫«ســيارتكم يف الورشــة وال أريدهــا ‪ -‬ســيارتكم عندكــم» وأرفــق‬\n     ‫مــع هــذا صــورة مــن بطاقــة املتابعــة وصــورة مــن مذكــرة نائــب مديــر‬\n     ‫التحصيــل املقدمــة إلــى نائــب املديــر العــام للشــركة )مســتند رقــم ‪-1‬‬\n     ‫صــورة بطاقــة متابعــة) (مســتند رقــم ‪ -2‬صــورة مذكــرة نائــب مديــر‬\n                                                                          ‫التحصيــل)‪.‬‬\n     ‫ا‬ ‫‪ .4‬وملــا كان التأخيــر يف دفــع األقســاط قــد بلــغ خمســة شــهور ‪ ،‬فضـ ً‬\n     ‫عــن افصــاح املدعــي بأنــه ال يريــد اســتالم الســيارة فقــد اســتعملت‬\n     ‫املدعــى عليهــا حقهــا يف فســخ العقــد وفق ـ ًا ملــا تقضــي بــه املــادة ‪2/14‬‬\n     ‫مــن العقــد ‪ ،‬مــن حــق الشــركة يف فســخ العقــد إذا تأخــر املســتأجر عــن‬\n     ‫ســداد أي قســط ايجــاري مســتحق مــن أقســاط االيجــار ملــدة ‪ 60‬يوم ـ ًا‬\n     ‫مــن تاريــخ االســتحقاق ‪ ،‬واملســتأجر لــم يكــن فقــط متأخــر ًا يف ســداد‬\n       ‫األقســاط ولكنــه أفصــح عــن أنــه اليريــد الســيارة ورفــض اســتالمها‪.‬‬\n     ‫‪ .5‬مــا ذهــب إليــه املدعــي مــن «أن العقــد هــو بيعتــن يف بيعــه وهــو يعــارض‬\n     ‫قواعــد الشــرع ومــا ذكــره مــن أن ســماحة مفتــي اململكــة وفضيلــة‬\n     ‫الشــيخ‪ /‬ابــن منيــع قــد افتيــا بذلــك» ‪ ،‬ال يخلــو مــن جــرأة علــى أحــكام‬\n\n\n‫‪39‬‬\n\f‫وقواعــد فقهيــة ينبغــي أن تتــرك ملــن تؤهلــه امكانياتــه للخــوض فيهــا ‪.‬‬\n‫وقــد أرفــق املدعــي مبذكرتــه صــورة بيــان مــن اللجنــة الدائمــة للبحــوث‬\n‫العلميــة واالفتــاء بشــأن االيجــار املنتهــي بالتمليــك ‪ ،‬كمــا أرفــق صــورة‬\n‫فتــوى صــادرة عــن مركــز الفتــوى بالقــرار رقــم ‪ )4/12( 110‬بشــان‬\n‫موضــوع االيجــار املنتهــي بالتمليــك وهــي التــي ميــزت بــن صــور جائــزة‬\n‫وصــور ممنوعــة لاليجــار املنتهــي بالتمليــك ‪ .‬ولــو أنصــف املدعــي وحــاول‬\n‫تفهــم الفتــوى ألدرك أن العقــد الــذي يطعــن ببطالنــه يدخــل يف الصــورة‬\n‫اجلائــزة ‪ .‬وليــس أدل علــى ذلــك مــن أن منــوذج العقــد الــذي يطعــن ببطالنــه‬\n‫معتمــد مــن قبــل الهيئــة الشــرعية املكونــة مــن كل مــن العلمــاء االجــاء‬\n        ‫‪:‬فضيلــة الشــيخ عبــد اهلل بــن منيــع فضيلــة الشــيخ يوســف الفــراج‬\n‫مــن ذلــك يتبــن أنــه ال أســاس لدعــوى املدعــي وال أحقيــة لــه يف شــيء‬\n‫ممــا يطلبــه ‪ .‬فاملدعــى عليهــا فســخت العقــد وفق ـ ًا ألحكامــه لتأخــر‬\n‫املدعــي يف ســداد األقســاط وافصاحــه عــن أنــه ال يريــد الســيارة ‪ ،‬وبعــد‬\n‫الفســخ واســترداد املدعــى عليهــا حيــازة الســيارة فمــن حقهــا أن تبيعهــا‬\n‫وتتصــرف فيهــا تصــرف املالــك يف ملكــه ‪ ،‬واملدعــي لــم يكــن مالــك ًا‬\n                                                                             ‫للســيارة ‪.‬‬\n‫ليــس ذلــك فقــط ‪ ،‬بــل أن املدعــى عليهــا تطلــب احلكــم بإلــزام املدعــي‬\n                 ‫باملبالــغ اآلتيــة وفقـ ًا ملــا تنــص عليــه املــادة ‪ 14‬مــن العقــد ‪:‬‬\n‫أجــرة الســنة األولــى ‪ 50.472‬ريــال (مــادة ‪ -3/14‬أ مــن العقــد) قيمــة‬\n‫(‪ )8‬أقســاط شــهرية ‪ 16.824 = 2.103 - 8‬ريــال (مــادة ‪-3/14‬ج ـ مــن‬\n‫العقــد ) املجمــوع ‪ 7,296‬ريــال يخصــم مــا ســبق ســداده مــن أقســاط‬\n‫‪8,513‬ريــال صــايف املســتحق يف ذمــة املدعــي‪ 58.783‬ريــال وقــد ورد‬\n‫خطــأ يف مذكرتنــا رقــم ‪ 11235‬وتاريــخ ‪1433/9/18‬ه ـ أن مــا ســبق‬\n\n\n                                                                                             ‫‪40‬‬\n\f     ‫ســداده ‪14.710‬ريــال والصحيــح ‪ 8.513‬ريــال كمــا هــو مذكــور أعاله‬\n     ‫‪ .‬وتطلــب الشــركة املدعــى عليهــا صــرف النظــر عــن دعــوى املدعــي‬\n     ‫لعــدم صحتهــا ‪ ،‬واحلكــم لهــا مببلــغ ‪ 58.783‬ريــال املســتحق يف ذمتــه‬\n     ‫وفق ـ ًا ألحــكام العقــد ‪ .‬وبعرضــه علــى املدعــي قــال ‪ :‬أطلــب اإلمهــال‬\n     ‫للــرد ‪ .‬ثــم رفعــت اجللســة لذلــك ‪ .‬ويف يوم الســبت املوافق‪1434/07/22‬هـ‬\n     ‫افتتحــت اجللســة الســاعة ‪10 : 00‬وفيهــا حضــر املدعــي ‪...................‬‬\n     ‫وحضــر ‪ ...................‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n     ‫‪ ....................‬بصفتــه وكيــا عــن ‪ ....................‬ســعودي اجلنســية‬\n     ‫ا عــن‬   ‫مبوجــب الســجل املدنــي رقــم ‪ ...................‬وبصفتــه وكي ـ ً‬\n     ‫‪ ...................‬بشــخصه وبصفتــه صاحــب مؤسســة ‪ ........................‬ســجل‬\n     ‫جتــاري رقــم ‪ 4030065137‬يف ‪1409/9/11‬ه ـ بالوكالــة رقــم ‪52749‬‬\n     ‫يف ‪1430/5/29‬ه ـ جلــد ‪ 8460‬الصــادرة عــن كتابــة عــدل جدة الثانية‪،‬‬\n     ‫وبصفتــه صاحــب مؤسســة ‪ ...‬لنقــل احلجــاج فــرع مؤسســة ‪.....................‬‬\n     ‫ســجل جتــاري رقــم ‪ ....................‬يف ‪1419/10/10‬ه ـ بالوكالــة رقــم‬\n     ‫‪ 52735‬يف ‪1430/5/29‬ه ـ جلــد ‪ 8460‬الصــادرة عــن كتابــة عــدل جدة‬\n     ‫الثانيــة ‪ ،‬وبصفــة موكلــي مديــر وشــريك يف شــركة ‪............................‬‬\n     ‫‪.....‬مبوجــب قــرار الشــركاء املوثــق مــن كاتــب العــدل املكلــف بالعمــل‬\n     ‫لــدى الغرفــة التجاريــة الصناعيــة مبحافظــة جــدة برقــم ‪ 181‬صحيفــة‬\n     ‫رقــم ‪ 183‬مجلــد ‪/10‬ش‪/‬م يف ‪1428/2/3‬ه ـ والســجل التجــاري رقــم‬\n     ‫‪ 4030171226‬يف ‪1428/7/8‬ه ـ بالوكالــة رقــم ‪ 34182524‬وتاريــخ‬\n     ‫‪1434/4/8‬ه ـ الصــادرة مــن كاتــب العــدل املكلــف بالغرفــة التجاريــة‬\n     ‫الصناعيــة مبحافظــة جــدة ‪،‬وبســؤال املدعــي عمــا طلــب اإلمهــال‬\n     ‫مــن أجلــه قــدم مذكــرة هــذا نصهــا ‪ :‬تأسيســا علــى مــا ســبق ذكــره‬\n\n\n‫‪41‬‬\n\f‫مبذكرتــي احملــررة يف ‪1433/10/16‬ه ـ وبنــاءا علــى مــا ورد مبذكــرة‬\n‫اجلهــة املدعــى عليهــا املقدمــة بجلســة ‪1433/11/10‬ه ــاقدم لفضيلتكم‬\n                                                                           ‫مــا يلــي‪:‬‬\n‫‪ .1‬ذكــر ممثــل اجلهــة املدعــى عليهــا بأننــي قــد رفضــت اســتالم ســيارتي‬\n         ‫بعــد اصالحهــا وهــذا قــول مرســل ال صحــة لــه وبــا دليــل او ســند‪.‬‬\n‫‪ .2‬ذكــروا اننــي متأخــر يف دفــع االســقاط ممــا اســتدعى اتخــاذ ذلــك‬\n‫ذريعــة املصــادرة والبيــع وهــذا ليــس بصحيــح مطلقــا فعنــد ادخــال‬\n‫ســيارتي ورشــة اجلهــة املدعــى عليهــا لــم يكــن علــى أي قســط متأخــر بــل‬\n‫مســتحق علــى قســط فقــط وليــس هنــاك تأخيــر كمــا ذكــر وممكــن‬\n                                                                ‫الرجــوع لتواريــخ‪.‬‬\n‫‪ .3‬اللجــوء الــى مصــادرة الســيارة وبالتالــي بيعهــا دون اتبــاع اجــراءات‬\n‫نظاميــة بتوجيــه انــذارات وبالرفــع للجهــات احلكوميــة املختصــة او‬\n‫توجيــه انــذارات محــررة لــي بالتاريــخ ومســببه فــان فعــل ذلــك تســلطا‬\n         ‫وتطبيــق للنظــام تعســفيا وباســتخدام وســائل اجلبــر واإلكــراه‪.‬‬\n‫‪ .4‬يــا صاحــب الفضيلــة كيــف تصــادر ســيارتي وأطالــب بتســديد مبلــغ‬\n‫‪ 58783‬ريــال ثمانيــة وخمســون الــف وســبعمائة وثالثــة وثمانــون ريــال ‪.‬‬\n‫أليــس ذلــك يــدل علــى الغــل وأكل االمــوال بالباطــل‪ .‬أليــس ذلــك خــارج‬\n    ‫عــن نطــاق املعقــول وأي إجــراءات وتخطــيء املنطــق وقواعــد التعامــل‬\n‫‪ .5‬بالعــودة ياصاحــب الفضيلــة ملــا ذكــره املدعــى عليــه بأنــه يطالــب‬\n‫مببالــغ تفاوتــت واختلفــت ثــاث مــرات بعــدة ارقــام مختلفــة ممــا يــدل‬\n                  ‫ذلــك علــى انــه يريــد الكيــد وفيــه فجــور يف اخلصومــه‪.‬‬\n‫عليــه اطلــب‪ :‬أو ًال ‪ :‬تعويضــي عــن ســيارتي التــي مت التصــرف فيهــا‬\n‫دون اجــراءات رســمية نظاميــة مبقــدار الضــرر الواقــع علــي مــن تاريــخ‬\n\n\n                                                                                         ‫‪42‬‬\n\f     ‫الســحب مــن الورشــة حتــى تاريــخ الفصــل بالدعــوى بحكــم مكتســب‬\n                             ‫القطعيــة مبقــدار ايجــار املثــل االضطــراري لذلــك‬\n     ‫ثانيــا ‪ :‬اعطائــي ســيارة بديلــه مبوديــل حديــث واحتســاب الدفعــات‬\n     ‫املقدمــة لــي ومواصلــة الدفــع والســداد حســب انظمــة البيــع املنتهــي‬\n                                                                              ‫بالتملــك ‪.‬‬\n     ‫ثالث ـ ًا ‪ :‬صــرف النظــر عــن دعواهــم يف دفــع املبلــغ الــذي يطالبــون بــه‬\n     ‫مطالبــه بــدون وجــه حــق وليــس لهــا اســاس إذ ال يجــوز املطالبــة بشــيء‬\n     ‫بــدون مقابــل ‪ .‬وبعــرض ذلــك علــى املدعــى عليــه وكالــة قــال ‪ :‬اطلــب‬\n     ‫اإلمهــال للــرد ‪ .‬ثــم رفعــت اجللســة لذلــك ‪ .‬ويف يــوم االثنــن املوافــق‬\n     ‫‪1434/08/08‬ه ـ افتتحــت اجللســة الســاعة ‪ 02 : 00‬حضــر املدعــي‬\n     ‫‪..................‬وحضــر املدعــى عليــه وكالــة ‪ ، ........................‬وبســؤال‬\n     ‫املدعــى عليــه وكالــة عمــا طلــب اإلمهــال مــن اجلــة قــدم مذكــرة‬\n                                                                  ‫جوابيــة هــذا نصهــا ‪:‬‬\n     ‫‪-1‬جــاء مبذكــرة املدعــي أن ماذكــر عــن رفضــه اســتالم الســيارة بعــد‬\n     ‫اصالحهــا هــو قــول مرســل ال صحــة لــه وبــا دليــل أو ســند‪ ،‬ويتجاهــل‬\n     ‫اننــا قــد ارفقنــا مبذكرتنــا مســتندين يثبتــان هــذه الواقعــة ‪ ،‬ه ــما صورة‬\n     ‫بطاقــة املتابعــة وصــورة مذكــرة نائــب مديــر التحصيــل ‪ ،‬وأضيــف هنــا‬\n     ‫ملزيــد مــن ادلــة االثبــات صــورة رســالة الكترونيــة مؤرخــة ‪2012/1/23‬‬\n     ‫مــن مركــز الصيانــة الــى مديــر التحصيــل بشــركة اقســاط تقــول‬\n     ‫بحصــر النــص « ان الســيارة جاهــزة مــن تاريــخ ‪ 2011/12/29‬ومت‬\n     ‫االتصــال علــى العميــل وإبالغــه أن الســيارة جاهــزة للتســليم وإلــى اآلن‬\n     ‫لــم يأتــي العميــل» فــا معنــى ملــا يقولــه املدعــى مــن أن رفضــه اســتالم‬\n                                    ‫الســيارة بعــد اصالحهــا ال صحــة لــه وال دليــل‪.‬‬\n\n\n‫‪43‬‬\n\f‫‪-2‬ان موضــوع دفــع األقســاط يف موعدهــا او تأخيرهــا ال يصلــح‬\n‫للجــدل فهــذه أرقــام وتواريــخ وليــس أصــدق مــن االرقــام يف الداللــة علــى‬\n‫الواقــع‪ ،‬وكل مــا جــاء مبذكرتنــا رقــم ‪ 11410‬وتاريــخ ‪1433/11/10‬‬\n‫عــن مدفوعــات املدعــي مــن االقســاط وتواريخهــا صحيــح ‪ ،‬ويتجاهــل‬\n‫املدعــي ان فســخ العقــد وســحب الســيارة مــن الورشــة وبيعهــا لــم يتــم‬\n‫عنــد ادخــال الســيارة الــى الورشــة يف ‪ ، 2011/10/22‬ولكــن بعــد أن‬\n‫انتهــى اصالحهــا يف ‪ 2011/12/29‬وبعــد أنطلــب مــن املدعــي اســتالمها‬\n‫وبعــد أن رفــض اســتالمها وبعــد أن رفــض ســداد االقســاط ‪،‬واجابتــه‬\n‫بــأن «ســيارتكم يف الورشــة وال اريدهــا ؟ ســيارتكم عندكــم « ولــم‬\n‫تبــع الســيارة إال بتاريــخ ‪ 2012/1/29‬وكانــت االقســاط املتأخــرة‬\n                                                               ‫خمســة أقســاط‪.‬‬\n‫‪ -3‬ال معنــى ملــا جــاء مبذكــرة املدعــي مــن أن مصــادرة الســيارة وبيعهــا‬\n‫مت دون اتبــاع اجــراءات نظاميــة وتوجيــه انــذارات والرفــع للجهــات‬\n‫احلكوميــة املختصــة ‪ ،‬النــه يتجاهــل أن العالقــة بــن الطرفني يحكمها‬\n‫وينظمهــا العقــد احملــرر بينهمــا ‪ ،‬وهــو عقــد ايجــار ملتخــرج بــه الســيارة‬\n‫عــن ملــك شــركة أقســاط حتــى يتكلــم املدعــي عــن مصادرتهــا ‪،‬‬\n‫كمــا يتجاهــل املدعــي أن العقــد ينــص يف مادتــه ‪-3/14‬أ علــى التــزام‬\n‫املســتأجر بســداد إيجــارات الســنة االولــى والســنوات املســتحقة عليــه‬\n‫بعدهــا حتــى تاريــخ التســليم الفعلــي للســيارة ‪ ،‬كمــا ينــص يف مادتــه‬\n‫‪-3/14‬ج ـ علــى التزامــه بــأن يســدد ثمانيــة أقســاط إيجاريــة ‪ ،‬وهــذا هــو‬\n    ‫مــا تطلــب الشــركة املدعــى عليهــا احلكــم بإلــزام املدعــي بســداده‪.‬‬\n‫‪ -4‬ان تصحيــح املدعــى عليهــا خلطــأ وقــع يف مبلــغ تطالــب بــه ال يــدل‬\n‫‪-‬كمــا ذهــب املدعــي ‪ -‬علــى أنهــا « تريــد الكيــد « وليــس فيــه « فجــور‬\n\n\n                                                                                    ‫‪44‬‬\n\f     ‫يف اخلصومــة» وهــي االوصــاف التــي لــم يجــد املدعــي حرجـ ًا يف نســبتها‬\n            ‫إلينــا ‪ ،‬وهــو مــا نضــرب الصفــح عنــه ‪ ،‬فغيرنــا مــن يوصــف بذلــك‪.‬‬\n     ‫وأخيــر ًا فــان طلــب املدعــي تعويضــه واعطائــه ســيارة بديلــة ال يســتند الــى‬\n     ‫أي اســاس شــرعيأ ونظامــي أو عقــدي ‪ ،‬فاملدعــى عليهــا فســخت العقــد‬\n     ‫وفقـ ًا ألحكامــه والســيارة لــم تكــن مملوكــة للمدعــي ‪ ،‬كمــا أن مــا‬\n     ‫تطلــب املدعــى عليهــا الــزام املدعــي بدفعــه لهــا هــو تطبيــق ألحــكام‬\n                                                                                 ‫العقــد‪.‬‬\n     ‫وتطلــب الشــركة املدعــى عليهــا صــرف النظــر عــن دعــوى املدعــي لعــدم‬\n     ‫صحتهــا واحلكــم لهــا مببلــغ ‪ 58.783‬ريــال املســتحق يف ذمتــه وفق ـ ًا‬\n     ‫ألحــكام العقــد ‪ .‬وبعــرض ذلــك علــى املدعــي قــال ‪ :‬أكتفــي مبــا قدمــت‬\n     ‫‪ .‬وبعــرض ذلــك علــى املدعــى عليــه وكالــة قــال‪ :‬أكتفــي مبــا قدمــت ‪.‬‬\n     ‫وبعــد التأمــل واالطــاع علــى أوراق املعاملــة قــررت طلــب ‪...............‬‬\n     ‫املوظــف بقســم املتابعــة لــدى املدعــى عليهــا فوعــد املدعــى عليــه وكالــة‬\n     ‫بإحضــاره يف اجللســة القادمــة إن كان ال يــزال علــى رأس العمــل ‪ .‬ثــم‬\n     ‫رفعــت اجللســة لذلــك ‪ .‬ويف يــوم األربعــاء املوافــق ‪1434/8/24‬ه ـ افتتحت‬\n     ‫اجللســة الســاعة ‪ 08 : 00‬وفيهــا حضــر املدعــي ‪ .....................‬وحضــر‬\n     ‫املدعــى عليــه وكالــة ‪ ، .............................‬وبســؤال املدعــى عليهوكالة‬\n     ‫عمــا طلــب الوكيــل الســابق بخصــوص حضــور موظــف قســم املتابعــة ‪...‬‬\n     ‫قــال ‪ :‬إن ‪ .....................‬قــد تــرك العمــل مبوجــب إفــادة موكلتــي‬\n     ‫بخطابهــا املــؤرخ يف ‪1434/8/21‬ه ـ ‪،‬وقــد أحضــرت معــي هــذا اليــوم‬\n     ‫مديــر قســم املتابعــة ‪ ..............‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n     ‫رقــم ‪ .................‬ليحــل محلــه ‪ .‬فحضــر ‪..............................‬ســعودي‬\n     ‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ، ....................‬وقــرر قائــا ‪:‬‬\n\n\n‫‪45‬‬\n\f‫بصفتــي مديــر قســم املتابعــة يف شــركة ‪ .................. .............‬فقــد متــت‬\n‫مخاطبــة املدعــي الســتالم الســيارة بعــد إصالحهــا مــن قبــل الورشــة بعــد‬\n‫أن وقــع عليهــا حــادث ســير ‪ ،‬إال أنــه رفــض االســتالم بنــاء علــى إفــادة‬\n‫املوظــف لدينــا ســابقا ‪ . ................‬وبعرضــه علــى املدعــي قــال ‪ :‬بــل‬\n‫الصحيــح أننــي لــم أمتنــع عــن اســتالم الســيارة ‪ ،‬وقــد راجعــت الورشــة‬\n‫مرتــن ‪ ،‬األولــى بعــد شــهر وعشــرة أيــام ‪ ،‬والثانيــة بعــد ثالثــة أســابيع‬\n‫مــن املراجعــة األولــى ‪ ،‬وأفادونــي بــأن الســيارة لــم تنتهــي بعــد ‪ .‬وبعــرض‬\n‫ذلــك علــى املدعــى عليــه وكالــة قــال ‪ :‬لقــد أدخلــت الســيارة للورشــة يف‬\n‫‪2011/10/22‬م وانتهــى إصالحهــا يف ‪2011/12/29‬م ‪ ،‬وبعــد ذلــك مت‬\n‫االتصــال علــى املدعــي الســتالم الســيارة ولكنــه رفــض ‪ ،‬وعليــه فتــم‬\n‫اســتخدام حق موكلتي فيفســخ عقد اإليجار ومت التصرف يف الســيارة‬\n‫بالبيــع وهــي ملــك ملوكلتــي يف ‪2012/1/29‬م ‪،‬والــذي يثبــت رفــض‬\n‫املدعــي الســتالم الســيارة هــو كــرت املتابعــة واملعــد مــن قبــل قســم‬\n‫املتابعــة والتحصيــل مبعرفــة املوظــف ‪ ، ................‬وكذلــك إفــادة‬\n‫املســؤول يف الورشــة ‪ ...............‬لقســم املتابعــة برســالة بالبريــد‬\n‫االلكترونــي موجهــة ل‪ ........................‬بــأن املدعــي يرفــض اســتالم‬\n‫الســيارة ‪ .‬وبعــرض ذلــك علــى املدعــي قــال ‪ :‬ليــس لــدي إضافــة ‪ .‬وبســؤال‬\n‫الطرفــن هــل لديكمــا مــا تضيفانــه قــاال ‪ :‬ال ‪ .‬لــذا فقــد قــررت قفــل‬\n‫بــاب املرافعــة بنــاء علــى املــادة ‪ 66‬مــن نظــام املرافعــات الشــرعية ‪ .‬ثــم‬\n‫رفعــت اجللســة للتأمــل ‪ .‬ويف يــوم االثنــن املوافــق ‪1434/08/29‬ه ـ‬\n‫افتتحــت اجللســة الســاعة ‪ 08 : 15‬وفيهــا حضــر املدعــي ‪....................‬‬\n‫وحضــر املدعــى عليــه وكالــة ‪، ....................‬وبعــد التأمــل ‪ ،‬قــررت‬\n‫ســؤال املدعــي عــن األقســاط اإليجاريــة التــي قــام بدفعهــا للشــركة‬\n\n\n                                                                                         ‫‪46‬‬\n\f     ‫املدعــى عليهــا قــال ‪ :‬ال أذكرهــا بالتحديــد ‪ ،‬وال أحتفــظ بشــيء يفيــد‬\n     ‫ذلــك ‪ .‬فطلبــت مــن املدعــى عليــه وكالــة إحضــار كشــف حســاب‬\n     ‫للعميــل يفيــد مبــا مت دفعــه مــن أقســاط إيجاريــة ‪،‬وإحضــار احملصــل أو‬\n     ‫احملاســب املســؤول عــن ذلــك يف اجللســة القادمــة وبرفقــه خطــاب مــن‬\n     ‫الشــركة موكلتــه يفيــد بأنــه يعمــل لديهــا بالصفــة املذكــورة أعــاه‪،‬‬\n     ‫فوعــد بذلــك يف اجللســة القادمــة ‪ .‬ثــم رفعــت اجللســة لذلــك ‪ .‬ويف يــوم‬\n     ‫األربعــاء املوافــق ‪1434/09/02‬ه ــافتتحت اجللســة الســاعة ‪10 : 30‬‬\n     ‫وفيهــا حضــر املدعــي ‪ ،...............‬وحضــر املدعــى عليــه وكالــة‬\n     ‫‪ ، .......................‬وبســؤال املدعــى عليــه وكالــة عمــا طلــب اإلمهــال مــن‬\n     ‫أجلــه أبــرز خطابــا مــن الشــركة املدعــى عليهــا وعلــى مطبوعــات‬\n     ‫شــركة ‪ ..........................‬مــؤرخ يف ‪1434/8/29‬ه ـ بخصــوص كشــف‬\n     ‫حســاب املدعــي يف عقــد الســيارة محــل الدعــوى واملتضمــن أن املدعــي‬\n     ‫ســدد أربعــة أقســاط علــى النحــو التالــي ‪ :‬األول مبلغــا قــدره ألفــان وثالثــة‬\n     ‫عشــر ريــاال بالســند رقــم ‪ 216159‬وتاريــخ ‪2011/4/23‬م ‪،‬والثانــي‬\n     ‫مبلغــا قــدره ألفــان ومائــة وعشــرة ريــاالت بالســند رقــم ‪ 76792‬وتاريــخ‬\n     ‫‪2011/6/30‬م ‪ ،‬والثالــث مبلغــا قــدره ألفــان ومائــة ريــال بالســند رقــم‬\n     ‫‪ 76793‬وتاريــخ ‪2011/8/27‬م ‪ ،‬والرابــع مبلغــا قــدره ألفــان ومئتــا ريــال‬\n     ‫بالســند رقــم ‪ 76794‬وتاريــخ ‪2011/8/1‬م ‪( ،‬ليصبــح إجمالــي مــا قــام‬\n     ‫بدفعــه العميــل مبلــغ وقــدره ‪ 8513‬ثمانيــة آالف وخمســمائة وثالثــة عشــر‬\n     ‫ريــال ال غيــر) ‪ ،‬ومت إرفاقــه باملعاملــة ‪ ،‬كمــا أحضــر املدعــى عليــه‬\n     ‫وكالــة ‪ .......‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ .......‬ويعمــل‬\n     ‫بوظيفــة محصــل لــدى الشــركة املدعــى عليهــا مبوجــب خطابهــا املــؤرخ‬\n     ‫يف ‪1434/8/30‬ه ـ املوافــق ‪2013/7/9‬م واملتضمــن أيضــا أن احملصــل‬\n\n\n‫‪47‬‬\n\f‫احلاضــر (علــى علــم باملبالــغ املســددة مــن قبــل الســيد ‪ ..............‬وكذلــك‬\n‫املبالــغ املســتحقة عليــه‪ ،‬وقــد فوضنــاه باحلضــور لــإدالء بإفادتــه فيمــا‬\n‫يخــص ذلــك) ‪،‬وبعــرض ذلــك علــى املدعــي قــال ‪ :‬مــا ورد يف كشــف‬\n‫احلســاب صحيــح ‪ ،‬ولــم أدفــع ســوى مــا ورد فيــه‪ .‬وبســؤال املدعــى عليــه‬\n‫وكالــة هــل هنــاك ضمانــات قدمــت مــن املدعــي لهــذا العقــد وهــل مت‬\n‫حتويــل راتــب املدعــي لبنــك حددتــه موكلتــك وهــل أخــذ علــى املدعــي‬\n‫كفيــل غــارم قــال ‪ :‬ال يوجــد مــن ذلــك شــيء ‪ .‬وبعرضــه علــى املدعــي‬\n‫قــال‪ :‬هــذا صحيــح ‪ .‬وبســؤال الطرفــن هــل لديكمــا مــا تضيفانــه قــاال‪:‬‬\n‫ال ‪ .‬فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة ‪،‬وبنــاء علــى العقــد‬\n‫املبــرم بــن الطرفــن محــل الدعــوى املــؤرخ يف ‪2011/4/17‬م ‪ ،‬وبنــاء‬\n‫علــى أن العقــد املبــرم بــن الطرفــن محــل الدعــوى هــو عقــد تأجيــر‬\n‫ســيارة مــع الوعــد بالهبــة‪ ،‬وبنــاء علــى املــادة الثالثــة مــن العقــد والتــي‬\n‫تنــص علــى أن مــدة اإلجــارة واحدا وســتني شــهرا تبــدأ يف ‪2011/5/1‬م‪،‬‬\n‫وبنــاء علــى إقــرار الطرفــن بوقــوع حــادث علــى الســيارة محــل الدعــوى‬\n‫والعقــد يف ‪2011/10/8‬م ‪ ،‬وإدخالهــا الورشــة يف ‪2011/10/22‬م ‪،‬‬\n‫ومبــا أن املدعــى عليــه أقــر بــأن الســيارة انتهــى إصالحهــا يف‬\n‫‪2011/12/29‬م ‪ ،‬ودفــع بــأن املدعــي رفــض اســتالمها ‪ ،‬وعليــه قامــت‬\n‫موكلتــه بفســخ العقــد ‪ ،‬وقــد باعــت الســيارة يف ‪2012/1/29‬م ‪ ،‬وبنــاء‬\n‫علــى إقــرار املدعــي مبــا مت دفعــه مــن أقســاط وقدرهــا ثمانيــة آالف‬\n‫وخمســمائة وثالثــة عشــر ريــاال والــوارد ذكرهــا فيكشــف حســاب‬\n‫املدعــي لــدى الشــركة املدعــى عليهــا ‪ ،‬وبنــاء علــى املــادة ‪ 2/14‬مــن‬\n‫العقــد والتــي تنــص علــى (إذا تأخــر الطــرف الثانــي عــن ســداد أي قســط‬\n‫إيجــاري مســتحق مــن أقســاط اإليجــار ‪ ،‬ملــدة ‪ 60‬يومــا مــن تاريــخ‬\n\n\n                                                                                       ‫‪48‬‬\n\f     ‫االســتحقاق فللطــرف األول أن يســتوفيها مــن الضمانــات املقدمــة مــن‬\n     ‫الطــرف الثانــي أو أن يقــوم باخلصــم مــن راتبــه احملــول لــدى البنــك احملدد‬\n     ‫مــن قبــل الطــرف األول أو يطالــب الطــرف الثانــي أو كفيلــه بتســديدها‬\n     ‫مباشــرة ‪،‬فــإن لــم يتمكــن مــن ذلــك ‪ ،‬أو لــم تكــن هــذه الضمانــات‬\n     ‫كافيــة فللطــرف األول أن يفســخ العقــد يف املــدة املتبقيــة منــه) ‪ ،‬ومبــا‬\n     ‫أن طــريف الدعــوى أقــرا بعــدم وجــود ضمانــات أو حتويــل راتــب لبنــك‬\n     ‫معــن أو كفيــل غــارم ‪ ،‬وبنــاء علــى املــادة ‪/3/14‬ج مــن العقــد محــل‬\n     ‫الدعــوى والتــي تنــص علــى (يف حــال فســخ العقــد أثنــاء الســنة األولــى‬\n     ‫يلتــزم الطــرف الثانــي ‪ -‬العميــل ‪ -‬بــأن يســدد إلــى الطــرف األول ثمانيــة‬\n     ‫أقســاط إيجاريــة أو املتبقــي مــن قيمــة العقــد الســنوي أيهمــا أقــل) ‪،‬‬\n     ‫واألقســاط الثمانيــة تســاوي مبلغــا قــدره ســتة عشــر ألــف او ثمامنائــة‬\n     ‫وأربعــة وعشــرون ريــاال ‪ ،‬وبنــاء علــى مــا قضــت بــه املــادة الرابعــة مــن‬\n     ‫العقدمــن أحــكام ‪ ،‬ومنهــا أن أجــرة الســنة األولــى مبلغــا قــدره خمســون‬\n     ‫ألفــا وأربعمائــة واثنــان وســبعون ريــاال ‪ ،‬وأن قيمــة كل قســط مبلغــا‬\n     ‫قــدره ألفــان ومائــة وثالثــة ريــاالت‪ ،‬فاألقســاط الثمانيــة أقــل مــن املتبقــي‬\n     ‫أجرة السنة األولى ‪ ،‬وبناء على أن املبلغ الواجب دفعه من ‪2011/5/1‬م‬\n     ‫وحتى ‪2011/10/1‬م هو عشــرة آالف وخمســمائة وخمســة عشــر رياال‪،‬‬\n     ‫واملدفــوع مــن املدعــي لنلــك الفتــرة ومــا بعدهــا مبلغــا قــدره ثمانيــة آالف‬\n     ‫وخمســمائة وثالثــة عشــر ريــاال ‪ ،‬وبنــاء علــى أن العقــد عقــد إجــارة ‪،‬‬\n     ‫وعقــد اإلجــارة عقــد علــى املنافــع ‪ ،‬فــإن تعــذر علــى املســتأجر االنتفــاع‬\n     ‫بالعــن املؤجــرة فــا يســتحق املؤجــر األجــرة يف فتــرة تعــذر االنتفــاع مــا‬\n     ‫لــم يكــن ذلــك بســبب تعــد املســتأجر أو تفريطــه ‪ ،‬ألنــه لــم يتســلم مــا‬\n     ‫تناولــه عقــد اإلجــارة ‪ ،‬فلــم يســتحق املؤجــر شــيئا ‪ ،‬كمــا قــرر ذلــك أهل‬\n\n\n‫‪49‬‬\n\f‫العلــم ‪ ،‬ومــن ذلــك مــا قــرره صاحــب الــروض املربــع ‪ ،‬ونصــه (وهــي أي‬\n‫اإلجــارة عقــد الزم مــن الطرفــن ألنهــا نــوع مــن البيــع فليــس ألحدهمــا‬\n‫فســخها لغيــر عيــب أو نحــوه ‪ ،‬فــإن آجــره شــيئا ومنعــه أي منــع املؤجــر‬\n‫املســتأجر الشــيء املؤجــر كل املــدة أو بعضهــا بــأن ســلمه العــن ‪ ،‬ثــم‬\n‫حولــه قبــل تقضــي املــدة فــا شــيء لــه مــن األجــرة ألنــه لــم يســلم لــه مــا‬\n‫تناولــه عقــد اإلجــارة ‪ ،‬فلــم يســتحق شــيئا ‪ ،‬وإن بــدأ اآلخر أي املســتأجر‬\n‫فتحــول قبــل انقضائهــا أي انقضــاء مــدة اإلجــارة فعليــه جميــع األجــرة‬\n‫ألنهــا عقــد الزم ‪ ،‬فترتــب مقتضاهــا ‪ ،‬وهــو ملــك املؤجــر األجــر‬\n‫واملســتأجر املنافــع ‪ ...‬وإن وجــد املســتأجر العــن معيبــة أو حــدث بهــا‬\n‫عنــده عيــب وهــو مــا يظهــر بــه تفــاوت األجــر فلــه الفســخ إن لــم يــزل بــا‬\n‫ضــرر يلحقــه وعليــه أجــرة مــا مضــى الســتيفائه املنفعــة فيــه ولــه اإلمضاء‬\n‫مجانــا واخليــار علــى التراخــي) وحيــث أجــازت هيئــة كبــار العلمــاء‬\n‫الشــرط اجلزائــي يف العقــود ‪ ،‬ولقولــه تعالــى (يــا أيهــا الذيــن آمنــوا أوفــوا‬\n‫بالعقــود) ‪ ،‬وحلديــث (املســلمون علــى شــروطهم) رواه الترمــذي وأبــو‬\n‫داوود ‪ ، ،‬وحلديــث (البينــة علــى املدعــي واليمــن علــى املدعــى عليــه)‬\n‫رواه الترمــذي ‪ ،‬قــال أبــو عيســى ‪ :‬العمــل عنــد أهــل العلــم مــن أصحــاب‬\n‫النبــي صلــى اهلل عليــه وســلم وغيرهــم أن البينــة علــى املدعــي واليمــن‬\n‫علــى املدعــى عليــه ‪ ،‬لذلــك كله ‪،‬فقد رددت دعوى املدعي ‪..................‬‬\n‫يف مواجهــة املدعــى عليهــا شــركة ‪ ....................‬لعــدم ثبــوت صحتهــا ‪،‬‬\n‫وحكمــت علــى املدعــي بدفــع مبلــغ قــدره ألفــان وخمســمائة واثنــان‬\n‫وســتون ريــاال وثمانــون هللــة للمدعــى عليهــا مقابــل أجــرة الســيارة محــل‬\n‫الدعــوى مــن ‪2011/5/1‬م وحتــى تاريــخ احلــادث يف ‪2011/10/8‬م بعــد‬\n‫خصــم مــا مت دفعــه مــن قبــل املدعــي ‪ ،‬وحكمــت علــى املدعــي بدفــع‬\n\n\n                                                                                         ‫‪50‬‬\n\f     ‫مبلــغ قــدره ســتة عشــر ألفــا و ثمامنائــة وأربعــة وعشــرون ريــاال للمدعــى‬\n     ‫عليهــا مقابــل الشــرط اجلزائــي الــوارد يف املــادة ‪/3/14‬ج ‪ ،‬ليكــون‬\n     ‫مجمــوع مــا يدفعــه املدعــي للمدعــى عليهــا مبلغــا قــدره تســعة عشــرألفا‬\n     ‫وثالثمائــة وســتة وثمانــون ريــاال وثمانــون هللــة ‪ ،‬وألزمــت املدعــى عليهــا‬\n     ‫بعــد ســداد املدعــي للمبلــغ محــل احلكــم رفــع اســمه مــن قائمــة ‪، ...‬‬\n     ‫ورددت مــا عــدا ذلــك مــن طلبــات لعــدم ثبــوت موجبهــا ‪ .‬وبــه حكمــت ‪.‬‬\n     ‫وبــه قنــع املدعــي ‪ ،‬وقــرر املدعــى عليــه وكالــة االعتــراض ‪ ،‬وجــرى‬\n     ‫تســليمه نســخة مــن احلكــم وإفهامــه بــأن لــه احلــق يف االعتــراض عليــه‬\n     ‫خــال ثالثــن يومــا ‪ ،‬وإال ســقط حقــه يف االعتــراض ‪ ،‬واكتســب‬\n     ‫احلكــم القطعيــة ‪ .‬وأقفلــت اجللســة الســاعة ‪ . 11 : 10‬وبــاهلل التوفيــق ‪،‬‬\n     ‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n                                                                       ‫‪1434/09/02‬هـ‬\n     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا‪ ...........‬القاضــي يف احملكمــة العامــة‬\n     ‫مبحافظــة جــدة ففــي يــوم األربعــاء املوافــق‪ 1435/02/01‬ه ـ افتتحــت‬\n     ‫اجللســة الســاعة ‪ 1 :15‬وفيهــا قــد عــادت املعاملــة مــن محكمــة‬\n     ‫االســتئناف بخطــاب رئيســها رقــم ‪ 33988853‬وتاريــخ ‪1435/1/22‬ه ـ‬\n     ‫وبالقــرار رقــم ‪ 35105065‬وتاريــخ ‪1435/1/4‬ه ـ ومضمونــه مــا يلــي‪:‬‬\n     ‫(وبدراســة احلكــم وصــورة ضبطــه والئحتــه االعتراضيــة قررنــا املوافقــة‬\n     ‫علــى احلكــم)‪ .‬وحت ــى ال يخف ــى ج ــرى إثباتــه وأقفل ــت اجل ـلـسـ ــة الســاعة‬\n     ‫‪ 1 : 25‬وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آله وصحبه‬\n                                                      ‫وســلم ‪ .‬حــرر يف ‪1435/2/1‬ه ـ‬\n     ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد‪ :‬فقــد‬\n     ‫جرى منا نحن قضاة الدائرة اجلزائية اخلامســة مبحكمة االســتئناف يف‬\n\n\n‫‪51‬‬\n\f‫منطقــة مكــة املكرمــة اإلطــاع علــى املعاملــة الواردة مــن فضيلة رئيس‬\n‫احملكمــة العامــة بجــدة برقــم (‪ )33988853‬وتاريــخ ‪1434/12/17‬ه‬\n‫املرفــق بهــا الصــك الصــادر م ــن فضيلــة الشــيخ‪ .......................‬القاضــي‬\n‫باحملكمــة العامــة بجــدة برقــم (‪ )34311281‬وت ـ ــاريخ ‪1434/9/2‬ه ـ‬\n‫الـمتضم ــن دعــوى املدعــي‪ ..............‬ســعودي اجلنســية ضــد شــركة‬\n‫‪ ....................‬يف إتــاف ممتلــكات‪ ،‬احملكــوم فيــه مبــا دون بباطــن‬\n‫الصــك‪ ،‬وبدراســة الصــك وصــورة ضبطــه والئحتــه االعتراضيــة قررنــا‬\n‫املوافقــة علــى احلكــم ‪ ،‬واهلل املوفــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                                                  ‫وعلــى آل ـ ـ ــه وصحبــه وســلم ‪...‬‬\n\n\n\n\n                                                                                         ‫‪52‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"612f1ba9-3f27-52bc-993f-69d3ecdc8564","source_page_start":32,"source_page_end":52,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"15dd58ce4e2877e3276ccb7a2230a0a6e68bc8df6edf9491961df17bf6e974f3","normalized_text_hash":"4b8101362ccc4fea3db647f700b41cf151d31ca6a4a6c8187819f40e92bf9118","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v7-p32-4311281"},{"id":"277dd9c6-2358-5855-85cb-aca9914c06c6","document_type":"judgment","category":"judicial","subcategory":"general","title":"إجارة -إخاء عقار من غائب -اإلعان يف الصحيفة احمللية قبل سماع الدعوى -البينة بشهادة الشهود املعدلن -تكوين جلنة لفرز ممتلكات الشقة -بيع ما يخشى تلفه وإيداع ثمنه يف بيت املال -حفظ ما ميكن حفظه يف بيت املال -احلكم بفتح العن ومتكن املدعى من االنتفاع بها -الغائب على حجته متى حضر -رفع احلكم حملكمة الاستئناف لتعذر تبليغ املدعى عليه باحلكم .","document_number":"33445093","case_number":"33394062","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة جدة بأنه تقدم لها املدعي","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/11/2","year":"1434","subject":"إجارة -إخاء عقار من غائب -اإلعان يف الصحيفة احمللية قبل سماع الدعوى -البينة بشهادة الشهود املعدلن -تكوين جلنة لفرز ممتلكات الشقة -بيع ما يخشى تلفه وإيداع ثمنه يف بيت املال -حفظ ما ميكن حفظه يف بيت املال -احلكم بفتح العن ومتكن املدعى من االنتفاع بها -الغائب على حجته متى حضر -رفع احلكم حملكمة الاستئناف لتعذر تبليغ املدعى عليه باحلكم .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫تاريخه‪1433/11/2 :‬هـ‬\n                      ‫ُ‬                 ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪33445093 :‬‬\n                         ‫َر ْق ُم الدعوى‪33394062 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                    ‫‪ 349752‬تاريخه‪1434/1/12:‬هـ‬\n\n\n\n     ‫إجــارة ‪ -‬إخــاء عقــار مــن غائــب ‪ -‬اإلعــان يف الصحيفــة احملليــة قبــل‬\n     ‫ســماع الدعــوى ‪ -‬البينــة بشــهادة الشــهود املعدلــن ‪ -‬تكويــن جلنــة لفــرز‬\n     ‫ممتلــكات الشــقة ‪ -‬بيــع مــا يخشــى تلفــه وإيــداع ثمنــه يف بيــت املــال‬\n     ‫‪-‬حفــظ مــا ميكــن حفظــه يف بيــت املــال ‪ -‬احلكــم بفتــح العــن ومتكــن‬\n     ‫املدعــى مــن االنتفــاع بهــا‪ -‬الغائــب علــى حجتــه متــى حضــر ‪ -‬رفــع‬\n           ‫احلكــم حملكمــة االســتئناف لتعــذر تبليــغ املدعــى عليــه باحلكــم ‪.‬‬\n\n\n\n\n                         ‫‪ .1‬قوله صلى اهلل عليه وسلم (ال ضرر وال ضرار)‪.‬‬\n           ‫‪ .2‬املادة ‪ 5/176‬من نظام املرافعات الشرعية والئحتها التنفيذية‪.‬‬\n\n\n\n\n     ‫ادعــى املدعــي ضــد املدعــى عليــه الغائــب عــن مجلــس احلكــم بأنــه قــد‬\n     ‫قــام بتأجيــر املدعــى عليــه الشــقة رقــم ‪...‬بالطابــق اخلامــس يف عمارتــه‬\n     ‫الواقعــة يف حــي ‪ ...‬يف مدينــة جــدة بأجــرة ســنوية قدرهــا عشــرون ألــف‬\n     ‫ريــال وقــد توقــف املدعــى عليــه عــن دفــع اإليجارات املســتحقة منــذ تاريخ‬\n     ‫‪1432/10/15‬ه ـ وقــد تغيــب عــن األنظــار منــذ ذلــك احلــن وال يعلــم عنــه‬\n     ‫شــيئ ًا وقــد تضــرر مــن بقــاء الشــقة معطلــة منافعهــا ويطلــب احلكــم بفتــح‬\n     ‫الشــقة املذكــورة أعــاه ومتكينــه مــن االنتفــاع بهــا هكــذا ادعــى ‪ -‬لــم‬\n‫‪53‬‬\n\f‫يحضــر املدعــى عليــه ولــم يــرد مــا يفيــد تبلغــه فجــرى ســماع الدعــوى‬\n‫غيابيـ ًا بعــد اإلعــان يف الصحيفــة احملليــة مبوعــد اجللســة‪ ،‬قــدم املدعــي‬\n‫بينتــه صــك العقــار وعقــد اإليجــار كمــا أحضــر شــاهدين ُعــدال شــرع ًا‬\n‫شــهدا طبــق دعــواه‪ ،‬ومبــا أن املدعــي قــد أبــرز مــا يثبــت متلكــه للعقــار‬\n‫ومــا يثبــت قيامــه بتأجيــر املدعــى عليــه الشــقة محــل الدعــوى وملــا قــام‬\n‫بــه املدعــي مــن اإلعــان عــن املدعــى عليــه ومــا أحضــره مــن بينــة تثبــت‬\n‫صحــة دعــواه ومبــا أن تــرك الشــقة مغلقــة طيلــة هــذه الفتــرة وتغيــب‬\n‫مســتأجرها وعــدم دفعــه لألجــرة فيــه ضــرر علــى مالــك العقــار وحيــث‬\n‫إن الضــرر مرفــوع يف الشــريعة لقــول النبــي صلــى اهلل عليــه وســلم ( ال‬\n‫ضــرر وال ضــرار ) وملــا ظهــر مــن اإلجــراءات الــواردة أعــاه ممــا يتعــذر‬\n‫معــه تبليــغ املدعــى عليــه وبنــاء علــى املــادة السادســة والســبعني بعــد املائــة‬\n‫مــن نظــام املرافعــات الشــرعية والئحتهــا التنفيذيــة اخلامســة‪ ،‬ملــا تقــدم‬\n‫ُحكــم بفتــح الشــقة رقــم ‪ ...‬الواقعــة يف حــي ‪ ...‬مبدينــة جــدة بحضــور‬\n‫منــدوب مــن الشــرطة ومنــدوب مــن بيــت املــال وفــرز مــا يف الشــقة مــن‬\n‫ممتلــكات وبيــع مــا يخشــى تلفــه وحفــظ قيمتــه يف بيــت املــال وحفــظ مــا‬\n‫يتمكــن حفظــه يف بيــت املــال وإعــداد محضــر يف ذلــك ومتكــن املدعــي‬\n‫مــن االســتفادة مــن الشــقة‪ ،‬قنــع املدعــي باحلكــم‪ ،‬رفــع إلــى محكمــة‬\n‫االســتئناف وذلــك لتعــذر تبليــغ املدعــى‪ ،‬صــدق احلكــم مــن الدائــرة‬\n     ‫احلقوقيــة الســابعة مبحكمــة االســتئناف مبنطقــة مكــة املكرمــة‪.‬‬\n\n\n\n\n                                                                                           ‫‪54‬‬\n\f     ‫احلمــد هلل وحــده وبعــد ففــي هــذا اليوم الثالثاء املوافــق ‪1433/11/02‬هـ‬\n     ‫افتتحــت اجللســة الســاعة ‪ 08 : 30‬وفيهــا حضــر املدعــي أصالــة ‪، ...‬‬\n     ‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ...‬ولــم يحضــر املدعــى‬\n     ‫عليــه ‪ ...‬وال مــن ميثلــه بوكالــة شــرعية ولــم يردنــا مــا يفيــد تبلغــه مبوعــد‬\n     ‫هــذه اجللســة مــن عــدم ذلــك وبســؤال املدعــي عــن دعــواه أجــاب قائــا‬\n     ‫إننــي أمتلــك العقــار الواقــع يف حــي ‪ ...‬يف مدينــة جــدة واملكــون مــن‬\n     ‫عمــارة ســكنية بهــا شــقق ســكنية كذلــك وقــد قمــت بتأجيــر املدعــى‬\n     ‫عليــه ‪ ...‬الشــقة رقــم ‪ ...‬بالطابــق ‪ ...‬بقيمــة ســنوية قدرهــا عشــرون ألــف‬\n     ‫ريــال وقــد توقــف املدعــى عليــه عــن دفــع اإليجــارات املســتحقة منــذ‬\n     ‫تاريــخ ‪1432/10/15‬ه ـ وقــد تغيــب عــن األنظــار منــذ ذلــك احلــن ال نعلــم‬\n     ‫عنــه شــيئا وقــد تضــررت مــن بقــاء الشــقة معطلــة منافعهــا أطلــب احلكــم‬\n     ‫بفتــح الشــقة املذكــورة أعــاه ومتكينــي مــن االنتفــاع بهــا هــذه دعــواي‬\n     ‫وقــد وردنــا خطــاب شــرطة محافظــة جــدة ذي الرقــم ‪ 6/6244‬وتاريــخ‬\n     ‫‪1433/05/29‬ه ـ واملقيــد يف هــذه احملكمة برقــم ‪ 331046791‬وتاريخ‬\n     ‫‪1433/06/03‬ه ـ واملتضمــن اإلفــادة التاليــة ‪ ( :‬نفيدكــم أنــه بالبحــث‬\n     ‫والتحــري عــن املســتأجر املذكــور لــم يتــم العثــور عليــه وذلــك حســب‬\n     ‫مــا يتضــح لفضيلتكــم مــن األوراق املرفقــة ) أ‪.‬ه ـ ‪ ،‬وبســؤال املدعــي‬\n     ‫عمــا يثبــت متلكــه للعقــار أبــرز مــن يــده صــورة مــن الصــك الصــادر مــن‬\n     ‫كتابــة عــدل جــدة األولــى ذي الرقــم ‪ 9315‬وتاريــخ ‪1425/11/08‬ه ـ‬\n     ‫والــذي يظهــر منــه امتــاك املدعــي للعقــار رقــم ‪ 567‬واملبــن حدودهــا‬\n     ‫وأطوالهــا يف صــورة الصــك املرفقــة كمــا أبــرز املدعــي مــن يــده عقــد‬\n\n‫‪55‬‬\n\f‫اإليجــار واملطبــوع علــى أوراق مؤسســة ‪ ...‬للتجــارة واملقــاوالت والــذي‬\n‫يظهــر منــه قيــام املدعــي بتأجيــر املدعــى عليــه ‪ ...‬الشــقة رقــم ‪ 43‬باملبلــغ‬\n‫املذكــور أعــاه كمــا يظهــر منــه أن تاريــخ العقــد هــو ‪1431/7/15‬ه ـ‬\n‫كمــا قــد قــرر املدعــي قائــا إننــي قمــت باإلعــان باجلريــدة اليوميــة‬\n‫عــن املدعــى عليــه فأبــرز مــن يــده ورقــة مــن جريــدة البــاد العــدد رقــم‬\n‫‪ 20190‬وتاريــخ ‪ 26‬جمــادى اآلخــرة لعــام ‪1433‬ه ـ ونــص اإلعــان ( تعلــن‬\n‫احملكمــة العامــة مبحافظــة جــدة بأنــه تقــدم لهــا املدعــي ‪ ، ...‬ســعودي‬\n‫اجلنســية ســجله املدنــي برقــم ‪ ...‬بدعــوى ضــد املدعــى عليــه ‪ ، ...‬ســعودي‬\n‫اجلنســية ســجله املدنــي برقــم ‪ ...‬يعمــل مديــر عــام مبكتــب ‪ ...‬لتأجيــر‬\n‫الســيارات بشــأن فتــح شــقته يف العمــارة الكائنــة يف حــي ‪ ...‬خلــف ‪...‬‬\n‫بجــدة وحــدد موعــد جلســة يف يــوم الثالثــاء املوافــق ‪1433/11/02‬ه ـ‬\n‫الســاعة ‪ 08 : 30‬صباحــا فمــن يعلــم عــن املدعــى عليــه املذكــور شــيئا‬\n‫عليــه مراجعــة احملكمــة العامــة مبحافظــة جــدة املكتــب القضائــي‬\n‫الســادس عشــر ( ‪ ) 16‬بالــدور اخلامــس واهلل املوفــق ) أ‪.‬ه ـ ‪ ،‬وبســؤال‬\n‫املدعــى عليــه وهــل لديــه مزيــد مــن البينــات علــى مــا جــاء يف دعــواه‬\n‫فأحضــر للشــهادة وأدائهــا م‪ ...‬باكســتاني اجلنســية مبوجــب رخصــة‬\n‫اإلقامــة رقــم ‪ ...‬ويظهــر أن تاريــخ ميــاده ‪1953/06/19‬م وبســؤاله عــن‬\n‫معلوماتــه املدنيــة أجــاب قائــا إننــي أســكن يف حــي ‪ ...‬مبدينــة جــدة‬\n‫ومتــزوج ولــي أوالد وبســؤاله عمــا لديــه أجــاب قائــا أشــهد بــاهلل العظيــم‬\n‫بــأن املدعــى عليــه ‪ ...‬قــد تــرك الشــقة رقــم ‪ 43‬العائــدة للمدعــي بعمارتــه‬\n‫الواقعــة يف حــي ‪ ...‬مبدينــة جــدة منــذ أكثــر مــن عــام هــذا مــا أشــهد بــه‬\n‫كمــا أحضــر للشــهادة وأدائهــا ‪ ، ...‬مصــري اجلنســية مبوجــب رخصــة‬\n‫اإلقامــة رقــم ‪ ...‬ويظهــر منهــا أن تاريــخ ميــاده ‪1977/02/15‬م وبســؤاله‬\n\n\n                                                                                       ‫‪56‬‬\n\f     ‫عــن معلوماتــه املدنيــة أجــاب قائــا إننــي أســكن يف حــي ‪ ...‬مبدينــة‬\n     ‫جــدة ومتــزوج ولــي أوالد وبســؤاله عمــا لديــه أجــاب قائــا أشــهد بــاهلل‬\n     ‫العظيــم بــأن املدعــى عليــه ‪ ...‬قــد تــرك الشــقة رقــم ‪ 43‬العائــدة للمدعــي‬\n     ‫بعمارتــه الواقعــة يف حــي الصفــا مبدينــة جــدة منــذ أكثــر مــن عــام هــذا‬\n     ‫مــا أشــهد بــه كمــا أحضــر املدعــي للشــهادة وأدائهــا ‪ ، ...‬باكســتاني‬\n     ‫اجلنســية مبوجــب رخصــة اإلقامــة رقــم ‪ ...‬و‪ ، ...‬ســعودي اجلنســية ســجله‬\n     ‫املدنــي برقــم ‪ ...‬ولــدى استشــهادهما شــهد كل واحــد منهمــا مبفــرده‬\n     ‫قائــا أشــهد أن الشــاهدين ‪ ......‬و‪ ...‬ومقبــوال الشــهادة فبنــاءا علــى‬\n     ‫مــا تقــدم مــن الدعــوى وحيــث إن املدعــي يدعــي غيــاب املدعــى عليــه‬\n     ‫وتركــه لشــقته مقفلــة وطلبــه متكينــه مــن االنتفــاع منهــا وتضــرره مــن‬\n     ‫ذلــك وحيــث إن املدعــي قــد أبــرز مــا يثبــت متلكــه للعقــار ومــا يثبــت‬\n     ‫قيامــه بتأجيــر املدعــى عليــه الشــقة محــل الدعــوى وملــا ورد مــن إفــادة‬\n     ‫شــرطة محافظــة جــدة واملتضمنــة عــدم العثــور علــى املدعــى عليــه وملــا‬\n     ‫قــام بــه املدعــي مــن اإلعــان عــن املدعــى عليــه ومــا أحضــره مــن بينــة‬\n     ‫تثبــت صحــة دعــواه مــن تغيــب املدعــى عليــه وتركــه الشــقة مغلقــة‬\n     ‫وحيــث إن تــرك الشــقة مغلقــة طيلــة هــذه الفتــرة وتغيــب مســتأجرها‬\n     ‫وعــدم دفعــه لألجــرة فيــه ضــرر علــى مالــك العقــار وحيــث إن الضــرر‬\n     ‫مرفــوع يف الشــريعة لقــول النبــي صلــى اهلل عليــه وســلم ( ال ضــرر وال‬\n     ‫ضــرار ) وملــا ظهــر مــن اإلجــراءات الــواردة أعــاه ممــا يتعــذر معــه تبليــغ‬\n     ‫املدعــى عليــه وبنــاءا علــى املــادة السادســة والســبعون بعــد املائــة مــن نظام‬\n     ‫املرافعــات الشــرعية والئحتهــا التنفيذيــة اخلامســة والتــي تنــص علــى أنــه‬\n     ‫( إذا تعــذر تســليم نســخة صــك احلكــم الغيابــي إلــى احملكــوم عليــه أو‬\n     ‫وكيلــه رفــع احلكــم إلــى محكمــة التمييــز بــدون الئحــة اعتراضيــة وال‬\n\n\n‫‪57‬‬\n\f‫مينــع ذلــك مــن التمــاس إعــادة النظــر وفــق أحكامــه املقــررة يف هــذا‬\n‫النظــام ) جلميــع مــا تقــدم فقــد حكمــت بفتــح الشــقة رقــم ‪ 43‬الواقعــة يف‬\n‫حــي الصفــا مبدينــة جــدة اململوكــة بالصــك املشــار إلــى رقمــه وتاريخــه‬\n‫أعــاه بحضــور منــدوب مــن الشــرطة ومنــدوب مــن بيــت املــال وفــرز مــا‬\n‫يف الشــقة مــن ممتلــكات وبيــع مــا يخشــى مــن تلفــه وحفــظ قيمتــه يف‬\n‫بيــت املــال وحفــظ مــا يتمكــن حفظــه يف بيــت املــال وإعــداد محضــر‬\n‫يف ذلــك ومتكــن املدعــي مــن االســتفادة مــن الشــقة وبعــرض احلكــم‬\n‫علــى املدعــي قــرر القناعــة بــه وأمــرت برفــع كامــل أوراق املعاملــة إلــى‬\n‫محكمــة االســتئناف وذلــك لتعــذر تبليــغ املدعــى عليــه وأقفلــت اجللســة‬\n‫الســاعة ‪ 09 : 00‬وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                              ‫وصحبــه وســلم حــرر يف ‪1433/10/24‬ه ـ ‪،،.‬‬\n‫احلمــد هلل وحــده‪ ،‬والصــاة والســام علــى مــن ال نبــي بعــده‪ ،‬وبعــد‪:‬‬\n‫فقــد جــرى منــا نحــن قضــا َة الدائــرة احلقوقيــة الســابعة مبحكمــة‬\n‫االســتئناف يف منطقــة مكــة املكرمــة االطــاع علــى املعاملــة الــواردة‬\n‫مــن فضيلــة رئيــس احملكمــة العامــة مبحافظــة جــدة املســاعد برقــم‬\n‫‪ 33/1046791‬وتاريــخ ‪1434/01/06‬ه ـ املرفــق بهــا الصــك الصــادر من‬\n‫فضيلــة الشــيخ ‪ ...‬القاضــي باحملكمــة العامــة مبحافظــة جــدة املســجل‬\n‫برقــم ‪ 33445093‬وتاريــخ ‪1433/11/02‬ه ـ املتضمــن دعــوى ‪ ...‬ضــد ‪...‬‬\n‫وبدراســة الصــك وص ــورة ضبط ــه تق ــررت املوافق ــة عل ــى احلكــم واهلل‬\n         ‫املوفــق وصل ــى اهلل عل ــى نبينــا محمــد وعل ــى آل ــه وصحب ــه وســلم‪.‬‬\n\n\n\n\n                                                                                       ‫‪58‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"612f1ba9-3f27-52bc-993f-69d3ecdc8564","source_page_start":53,"source_page_end":58,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"7903b335f36a7d154ed58e95bbca2486056a788c18286e35f5ec5d40e384d8a0","normalized_text_hash":"734ba991644a97ae8c855dfc6cac65d0df5d323f3152e9b2a31e31dfe3d64d77","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v7-p53-33445093"},{"id":"e8ceb43b-4df9-584b-b55d-77fcb7ed80db","document_type":"judgment","category":"judicial","subcategory":"general","title":"إجارة -إخاء عقار -حكم على غائب -تعذر إباغ خصم -تنويه بأن الغائب على حجته إذا حضر .","document_number":"33413765","case_number":"3395424","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالدمام","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/9/17","year":"1434","subject":"إجارة -إخاء عقار -حكم على غائب -تعذر إباغ خصم -تنويه بأن الغائب على حجته إذا حضر .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫تاريخه‪1433/9/17 :‬هـ‬\n                      ‫ُ‬                ‫َر ْق ُم َّ‬\n                         ‫الص ِّك‪33413765 :‬‬\n                         ‫َر ْق ُم الدعوى‪3395424 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                 ‫‪ 34228308‬تاريخه‪1434/6/3 :‬هـ‬\n\n\n\n     ‫إجــارة ‪ -‬إخــاء عقــار ‪ -‬حكــم علــى غائــب ‪ -‬تعــذر إبــاغ خصــم ‪ -‬تنويــه‬\n                                                     ‫بــأن الغائــب علــى حجتــه إذا حضــر ‪.‬‬\n\n\n\n\n                                            ‫املادة (‪ )55‬من نظام املرافعات الشرعية ‪.‬‬\n\n\n\n\n     ‫ادعــى املدعــي ضــد الغائــب عــن مجلــس احلكــم املدعــى عليــه والــذي‬\n     ‫تعــذر إبالغــه مبوعــد اجللســة بالطــرق الرســمية ومضمــون الدعــوى‬\n     ‫أن املدعــي أجــر علــى املدعــى عليــه شــقة مــن عمــارة ميلكهــا مبوجــب‬\n     ‫عقــد مبــرم بــن الطرفــن حيــث اســتأجرها املدعــى عليــه ملــدة ســنة‬\n     ‫وتأخــر يف تســليم اإليجــار وطلــب املدعــي إلــزام املدعــى عليــه بإخــاء‬\n     ‫العقــار وتســليم قيمــة اإليجــارات املتأخــرة‪ ،‬احضــر املدعــي بينتــه وهمــا‬\n     ‫شــاهدان شــهدا علــى صحــة دعــواه وعــدل الشــاهدان شــرعاً‪ ،‬صــدر‬\n     ‫احلكــم بإلــزام املدعــى عليــة بتســليم األجــرة املتأخــرة وإخــاء الشــقة‬\n                             ‫حــاالً‪ ،‬صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫‪59‬‬\n\f‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .......‬القاضــي يف احملكمــة العامــة‬\n‫بالدمــام وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بالدمــام برقــم ‪ 3395424‬وتاريــخ ‪1433/02/07‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 33249180‬وتاريــخ ‪1433/02/07‬ه ـ ففــي يــوم‬\n‫االحــد املوافق‪1433/02/21‬ه ـ أفتتحــت اجللســة وفيهــا حضــر‪.......‬‬\n‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ .......‬ولــم يحضــر املدعــى‬\n‫عليــه املدعــو‪ .......‬ولــم تردنــا افــاده مــن محضــري اخلصــوم بتبليغــه‬\n‫والنــه تعــذر ابالغــه حســب احملاضــر املرفقــه والنــه جــرى الكتابــه‬\n‫ملقــام االمــاره البالغــه ولــم تردنــا افــاده حتــى االن لــذا فقــد جــرى‬\n‫ســماع الدعــوى وقــرر املدعــي قائــا ان مــن اجلــاري يف ملكــي وحتــت‬\n‫تصــريف العمــاره الواقعــه يف حــي ‪ ...‬بالدمــام يف القطعــه رقــم ‪ ...‬يف‬\n‫مخطــط ‪ ...‬بالدمــام واململوكــه لــي مبوجــب صــك رقــم ‪4/30/3695‬‬\n‫حدودهــا واطوالهــا كالتالــي شــماال شــارع عــرض ‪20‬م بطــول ثالثــون‬\n‫متــر وجنوبــا ارض ‪ 15/‬بطــول ثالثــون متــر وشــرقا شــارع عــرض ‪ 10‬م‬\n‫بطــول خمســة وعشــرون متــر وغربــا ارض ‪ 14/‬بطــول خمســه وعشــرون‬\n‫متــر حيــث اســتأجر منــي املدعــى عليــه شــقه يف هــذه العمــاره مبوجــب‬\n‫العقــد املبــرم بيننــا واملوقــع عليــه مــن قبــل الطرفــن حيــث اســتاجرها‬\n‫بتاريــخ ‪1428/06/01‬ه ـ باجــره ســنويه و قدرهــا ثمــان وعشــرون الــف‬\n‫ريــال وطريقــة الدفــع كل ســتة اشــهر اربعــة عشــر الــف ريــال وقــد تاخــر‬\n‫املدعــى عليــه يف تســديد االيجــار عــدة مــرات حيــث بلــغ الــذي يف ذمتــه‬\n‫ثمانيــة عشــر الــف واربعمائــة وثمانــون ريــال وقــد طلبــت منــه اخــاء‬\n\n                                                                                   ‫‪60‬‬\n\f     ‫العقــار اكثــر مــن ســنه ولكنــه رفــض ذلــك وامتنــع عــن االخــاء علمــا‬\n     ‫بــان العقــد مدتــه ســنه واحــده اطلــب الزامــه باخــاء العقــار املوصــوف يف‬\n     ‫الدعــوى هــذه دعــواي وبســؤاله عــن البينــه احضــر للشــهاده علــى ذلــك‬\n     ‫كال مــن ‪ .......‬ســعودي اجلنســيه مبوجــب ســجل مدنــي رقــم ‪..............‬‬\n     ‫و‪ ..............‬ســعودي اجلنســيه مبوجــب ســجل مدنــي ‪ .......‬وشــهد كل‬\n     ‫واحــد منهــم بقولــه اشــهد بــاهلل العظيــم ان املدعــى عليــه اســتاجر مــن‬\n     ‫املدعــي الشــقه املذكــوره اعــاه باجــرة ســنويه قدرهــا ثمــان وعشــرون‬\n     ‫الــف ريــال وان املدعــى عليــه تاخــر يف ســداد االيجــارات وان الــذي‬\n     ‫بذمتــه ثمانيــة عشــر الــف واربعمائــه وثمانــون ريــال وان املدعــي طلــب‬\n     ‫منــه اخــاء العقــار ولكنــه رفــض وامتنــع وقــد حاولنــا نحــن معــه عــدة‬\n     ‫مــرات ولكــن دون جــدوى هكــذا شــهدا واحضــر لتعديــل الشــهود‬\n     ‫كال مــن ‪ .......‬ســعودي اجلنســيه مبوجــب ســجل مدنــي رقــم ‪ .......‬و ‪.......‬‬\n     ‫ســعودي اجلنســيه مبوجــب ســجل مدنــي رقــم ‪ .......‬وشــهدا بــاهلل العظيــم‬\n     ‫ان الشــهود عــدول وثقــات وال نعلــم عنهــم اال كل خيــر وليــس بينهــم‬\n     ‫وبــن املدعــى عليــه اي عــداوه هــذا مالدينــا لــذى فقــد جــرى الكتابــة‬\n     ‫منــا لكتابــة العــدل لالستفســار عــن ســريان مفعــول الصــك املشــار عليــه‬\n     ‫وقــد وردتنــا افــادة محضــري اخلصــوم عــدة مــرات والتــي تفيــد تعــذر‬\n     ‫ابالغــه رغــم الوصــول ملنزلــه وطــرق البــاب ولكــن اليــرد كمــا جــرى‬\n     ‫األتصــال بــه عــدة مــرات ولكــن جوالــه مغلــق ولــم يراجــع خــال هــذه‬\n     ‫الفتــرة احملكمــة لرفــع التعميــم عنــه ومــازل التعميــم قائمــا وقــد وردتنــا‬\n     ‫إفــادة كتابــة عــدل الدمــام برقــم ‪ 331476483‬وتاريــخ ‪1433/8/12‬ه ـ‬\n     ‫والتــي تتضمــن ســريان مفعــول الصــك وأنــه عائــد للمدعــي وبنــاء علــى‬\n     ‫املــادة اخلامســة واخلمســن مــن نظــام املرفعــات ولتغيــب املدعــى عليــه‬\n\n\n‫‪61‬‬\n\f‫عــن احلضــور ومحاولــة ابالغــه بشــتى الطــرق ولتعــذر ذلــك وبنــاء البينــه‬\n‫علــى املعدلــه شــرعا ولــكل مــا تقــدم فقــد حكمــت علــى املدعــى عليــه‬\n‫الغائــب عــن مجلــس احلكــم بــأن يســلم املدعــي مبلــغ وقــدره ثمانيــة‬\n‫عشــر الــف واربعمائــة وثمانــون ريــال وأن يخلــي الشــقه املوصوفــه اعــاه‬\n‫حــاال وقــررت بعــث نســخة مــن صــك احلكــم بعــد تســجيله للمدعــي‬\n‫عليــه ليقــدم اعتراضــه خــال املــدة املقــررة نظامـ ًا وهــي ثالثــون يومـ ًا مــن‬\n‫تاريــخ التبليــغ وأنــه إذا مضــت مــدة االعتــراض ولــم يقــدم اعتراضــه بعــد‬\n‫تبليغــه احلكــم فــإن احلكــم يكتســب القطعيــة ويعــد حضوريـ ًا يف حــق‬\n‫املدعــى عليــه حســب املــواد ‪1/55‬و‪4/176‬و‪ 178‬مــن الالئحــة التنفيذيــة‬\n‫لنظــام املرافعــات وأنــه اذا لــم يتبلــغ او تعــذر ابالغــه فــإن احلكــم يرفــع‬\n‫حملكمــة اإلســتئناف حســب النظــام وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى‬\n   ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1433/09/06‬هــ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة دائ ــرة األحــوال‬\n‫الشــخصية الثانيــة يف محكمــة االســتئناف باملنطقــة الشــرقية علــى‬\n‫املعاملــة املقيــدة لــدى احملكمــة برقــم ‪/34/1072562‬ش‪ 2‬وتاريــخ‬\n‫‪1434/5/1‬ه ـ والــواردة مــن فضيلــة رئيــس احملكمــة العامــة مبدينــة‬\n‫الدمــام برقــم ‪ 33249180‬وتاريــخ ‪1434/4/28‬ه ـ املرفــق بهــا الصــك‬\n‫الصــادر مــن فضيلــة القاضــي بهــا الشــيخ ‪ ..............‬املســجل برقــم‬\n‫‪ 33413765‬وتاريــخ ‪1433/9/17‬ه ـ اخلــاص بدعــوى ‪ ..............‬ضــد‬\n‫‪ ..............‬يف قضيــة اخــاء عقــار وقــد تضمــن الصــك حكــم فضيلتــه‬\n‫مبــا هــو مــدون ومفصــل فيــه‪ .‬وبدراســة الصــك وصــورة ضبطــه وأوراق‬\n‫املعاملــة قررنــا املصادقــة علــى حكــم فضيلتــه مــع تنبيهــه إلــى إحلــاق‬\n‫العبــارة يف الصــك (أن احلكــم يف حــق املدعــى عليــه غيابــي وأنــه علــى‬\n\n\n                                                                                        ‫‪62‬‬\n\f     ‫حجتــه) وذلــك قبــل إحالتهــا إلــى جهــة التنفيــذ واهلل املوفــق وصلــى اهلل‬\n          ‫علــى نبينــا محمــد وآلــه وصحبــه وســلم حــرر يف ‪1434/5/29‬ه ـ‬\n\n\n\n\n‫‪63‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"612f1ba9-3f27-52bc-993f-69d3ecdc8564","source_page_start":59,"source_page_end":63,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"3a626d509bd3cf9f661fa3ca1c630d4540e0585635a2489ee1afe33a20a73010","normalized_text_hash":"dc667fb986fd831269992cac5a65287bbd0b1318209fa1aad30cddf8a34d27d4","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v7-p59-33413765"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS legal_documents,
       (SELECT count(*) FROM public.document_files WHERE document_id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"6cdefa82-7d64-5f44-9555-94421f6a9209","document_type":"judgment","category":"judicial","subcategory":"general","title":"إجارة -إجارة عمارة سكن حجاج -مطالبة بإعادة أجرة مدفوعة لتعذر إخراج تصريح إسكان حجاج -إقرار بالعقد واستالم املبلغ وإعادة بعضه وإنكار تعذر إخراج التصريح -إقرار خطي -الدفع بأنه نزع منه بالقوة -عدم البينة على الدفع -إلزام املدعى عليه برد باقي األجرة -رفع احلكم حملكمة الاستئناف لتعذر تبليغ املدعي عليه باحلكم.","document_number":"3443385","case_number":"32350279","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبكة املكرمة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/2/20","year":"1434","subject":"إجارة -إجارة عمارة سكن حجاج -مطالبة بإعادة أجرة مدفوعة لتعذر إخراج تصريح إسكان حجاج -إقرار بالعقد واستالم املبلغ وإعادة بعضه وإنكار تعذر إخراج التصريح -إقرار خطي -الدفع بأنه نزع منه بالقوة -عدم البينة على الدفع -إلزام املدعى عليه برد باقي األجرة -رفع احلكم حملكمة الاستئناف لتعذر تبليغ املدعي عليه باحلكم.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/2/20 :‬هـ  ‬\n                        ‫ُ‬                ‫َر ْق ُم َّ‬\n                            ‫الص ِّك‪3443385 :‬‬\n                          ‫َر ْق ُم الدعوى‪32350279 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                  ‫‪ 34201660‬تاريخه‪1434/4/30 :‬هـ‬\n\n\n\n      ‫إجــارة ‪ -‬إجــارة عمــارة ســكن حجــاج ‪ -‬مطالبــة بإعــادة أجــرة مدفوعــة‬\n      ‫لتعــذر إخــراج تصريــح إســكان حجــاج ‪ -‬إقــرار بالعقــد واســتالم املبلــغ‬\n      ‫وإعــادة بعضــه وإنــكار تعــذر إخــراج التصريــح ‪ -‬إقــرار خطــي ‪ -‬الدفــع‬\n      ‫بأنــه نــزع منــه بالقــوة ‪ -‬عــدم البينــة علــى الدفــع ‪ -‬إلــزام املدعــى عليــه‬\n      ‫بــرد باقــي األجــرة‪ -‬رفــع احلكــم حملكمــة االســتئناف لتعــذر تبليــغ‬\n                                                             ‫املدعــي عليــه باحلكــم‪.‬‬\n\n\n\n\n      ‫مــا أســتند إليــه القاضــي مــن املبــادئ العامــة وقواعــد العدالــة الــواردة‬\n                                                                ‫يف تســبيب حكمــه ‪.‬‬\n\n\n\n\n      ‫تقــدم املدعــي بدعــوى ضــد املدعــى عليه بأنه اســتأجر عمارة لالســتفادة‬\n      ‫منهــا يف موســم احلــج بأجــرة معلومــة محــددة وســلم بعضــه وبقــي البعــض‬\n      ‫إال أنــه ظهــر بأنــه ال ميكــن االســتفادة منهــا للتأجيــر علــى احلجــاج لوجــود‬\n      ‫مخالفــة بنــاء يف الــدور العلــوي مــن العمارة مما يتعــذر معه خروج تصريح‬\n      ‫إلســكان احلجــاج لــذا فقــد طلــب مــن املدعــى عليــه إعــادة اجلــزء املســلم‬\n      ‫مــن األجــرة فأعــاد بعضــه ووعــد بتســليم الباقــي إال أنــه امتنــع لــذا فقــد‬\n      ‫طلــب إلزامــه بــرد باقــي األجــرة املســلمة‪ ،‬أقــر املدعــى عليــه بالدعــوى‬\n‫‪375‬‬\n\f‫إال أنــه أنكــر وجــود مخالفــة وتعــذر االســتفادة منهــا إلســكان احلجــاج‬\n‫ودفــع بــأن عــدم خــروج تصريــح إســكان احلجــاج كان بتفريــط مــن‬\n‫املدعــي وأمــا رده لبعــض األجــرة فــكان جبــرا خلوفــه مــن تهديــده ويطلب‬\n‫رد طلــب املدعــي‪ ،‬بعرضــه علــى املدعــي قــرر بــأن الصحيــح مــا ورد يف‬\n‫دعــواه وبطلــب البينــة منــه أبــرز ســندات قبــض كمــا أبــرز إقــرار ًا محررا‬\n‫مــن املدعــى عليــه مضمونــه إقــرار املدعــى عليــه بــأن يــرد للمدعــي املبلــغ‬\n‫املدعــى بــه باقــي األجــرة املســلمة‪ ،‬بعــرض اإلقــرار احملــرر علــى املدعــى‬\n‫عليــه دفــع بأنــه نــزع منــه بالقــوة فطلبــت البينــة علــى دفعــه فطلــب مهلــة‬\n‫إال أنــه لــم يحضــر يف اجللســة التــي أجلــت لــه لذلــك‪ ،‬عليــه وألن املدعــى‬\n‫عليــه وكالــة أقــر بصحــة اإلقــرار الصــادر مــن موكلــه واملتضمــن بــأن‬\n‫بذمتــه لصالــح املدعــي أصالــة املبلــغ املدعــى بــه وأن آخــر دفعــة مــن هــذا‬\n‫املبلــغ تســلم يف ‪1431/8/30‬ه ـ ولدفــع املدعــى عليــه وكالــة بــأن هــذا‬\n‫اإلقــرار قــد أخــذ منــه بالقــوة واإلكــراه وطلــب مهلــة لســؤال موكلــه عن‬\n‫البينــة ولتخلفــه عــن اجللســة املقــررة وألن تخلفــه يعــد نكــو ًال عــن اجلــواب‬\n‫وبنــاء علــى املــادة اخلامســة واخلمســن والفقــرة الثانيــة مــن الئحــة املــادة‬\n‫الثالثــة بعــد املائــة مــن نظــام املرافعــات الشــرعية وألن وكالــة املدعــى‬\n‫عليــه تخولــه حــق اإلقــرار لذلــك فقــد حكمــت الدائــرة علــى املدعــى‬\n‫عليــه حضوريـ ًا بــأن يدفــع للمدعــي املبلــغ املدعــى بــه‪ ،‬جــرى بعــث صــورة‬\n‫مــن احلكــم للمدعــى عليــه بواســطة محضــر اخلصــوم فعــادت اإلفــادة‬\n‫بأنــه مت الوصــول إلــى عنوانــه ولــم يعثــر عليــه وبالســؤال عــن كفيــل‬\n‫املدعــى عليــه أفــاد أحــد العاملــن بأنــه خــارج مكــة وباالتصــال علــى‬\n‫الهاتــف لــم يــرد عليــه أحــد ولتعــذر تســليم املدعــى عليــه لشــخصه نســخة‬\n‫مــن إعــام احلكــم وبنــاء علــى املــادة ‪ 5/176‬مــن نظــام املرافعــات فقــد‬\n\n\n                                                                                        ‫‪376‬‬\n\f      ‫تقــرر رفــع كامــل املعاملــة حملكمــة االســتئناف لتدقيــق احلكــم حســب‬\n                            ‫املتبع‪،‬صــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪   ...................‬القاضــي يف احملكمــة‬\n      ‫العامــة مبكــة املكرمــة   وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n      ‫رئيــس احملكمــة العامــة مبكــة املكرمــة برقــم ‪ 32137953‬وتاريــخ‬\n      ‫‪ 1432/04/23‬هــ   املقيــدة باحملكمــة برقــم ‪ 32350279‬وتاريــخ‬\n      ‫‪ 1432/04/08‬هــ  ففــي يــوم  األربعــاء املوافق‪ 1433/05/12‬هـ افتتحت‬\n      ‫اجللســة الســاعة  احلاديــة عشــرة وفيهــا حضــر ‪ .....................‬ســعودي‬\n      ‫ا عــن‬ ‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ....................‬بصفتــه وكيـ ً‬\n      ‫‪ ......................‬مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل الثانيــة‬\n      ‫مبكــة املكرمــة برقــم ‪  37937‬يف ‪1429/7/13‬ه ـ ولــه فيهــا حــق‬\n      ‫املرافعــة واملدافعــة واإلقــرار ومراجعــة احملاكــم  واإلنــكار والتنــازل‬\n      ‫والصلــح ‪ ...‬الــخ وادعــى علــى احلاضــر معــه ‪ ......................‬ســعودي‬\n      ‫ا‬\n      ‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪ .....................‬بصفتــه وكي ـ ً‬\n      ‫عــن ‪ .................‬مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل الثانيــة‬\n      ‫مبكــة املكرمــة برقــم ‪ 13872‬يف ‪1431/4/25‬ه ـ اجللــد ‪ 4498‬ولــه‬\n      ‫فيهــا حــق املرافعــة واملدافعــة وحضــور اجللســات واإلقــرار واإلنــكار‪....‬‬\n      ‫ا يف دعــواه عليــه لقــد مت االتفــاق بــن موكلــي و‪..................‬‬ ‫الــخ قائ ـ ً‬\n      ‫علــى أن يســتأجر موكلــي العمــارة الكائنــة يف حــي ‪....‬مبكة املكرمة‬\n      ‫وذلــك ملوســم حــج عــام ‪1429‬ه ـ مببلــغ وقــدره ثالثمائــة وخمســون ألــف‬\n      ‫ريــال مت تســليم  مبلــغ وقــدره مائــة وتســعون ألــف ريــال وذلــك للمدعــو‬\n\n‫‪377‬‬\n\f  ‫‪ ......‬واململوكــة لـ ــ‪ ......‬وقــد اســتأجرها املدعــو ‪ .......‬لعــدة ســنوات‬\n  ‫ولكــن موكلــي لــم يســتلم العمــارة املذكــورة ولــم ينتفــع بهــا وذلــك‬\n  ‫لوجــود مخالفــة بنــاء يف الــدور العلــوي مــن العمــارة ولــم يتــم اســتخراج‬\n  ‫تصريــح إســكان مــن جلنــة احلــج وقــد طلــب موكلــي مــن املدعــى عليــه‬\n  ‫إعــادة املبلــغ املذكــور والــذي اســتلم املدعــى عليــه جــزء منــه وذلــك‬\n  ‫بتفويــض مــن ‪ ..........‬فأعــاد ملوكلــي مبلــغ وقــدره خمســون ألــف ريــال‬\n  ‫ثــم  اتضــح بعــد ذلــك أن املدعــو ‪ ...........‬ليــس لــه ســوى االســم يف العمــارة‬\n  ‫وصاحــب املنفعــة هــو املدعــى عليــه وقــد التــزم املدعــى عليــه بإعــادة‬\n  ‫املبلــغ املتبقــي وقــدره مائــة وأربعــون ألــف ريــال لذلــك فموكلــي يطلــب‬\n  ‫إلــزام املدعــى عليــه بإعــادة املبلــغ املذكــور يف الدعــوى هــذه دعــواي‬\n  ‫ا مــا ذكــره املدعــي‬    ‫وبعــرض الدعــوى علــى املدعــى عليــه أجــاب قائ ـ ً‬\n  ‫وكالــة يف دعــواه مــن أنــه مت االتفــاق بــن موكلــه وموكلــي علــى أن‬\n  ‫يســتأجر العمــارة الكائنــة يف ‪....‬وذلــك ملوســم حــج عــام ‪1429‬ه ـ وذلــك‬\n  ‫مببلــغ وقــدره ثالثمائــة وخمســون ألــف وذلــك مبوجــب ســندات قبــض‬\n‫واململوكــة لــ‪ ................‬وقــد اســتأجرها املدعــو ‪ ...............‬لعــدة ســنوات  ‬\n  ‫فهــذا صحيــح ولكــن موكلــي شــريك مــع املدعــو ‪ ...............‬يف هــذه‬\n  ‫العمــارة ومــا ذكــره املدعــي وكالــة مــن املبالــغ التــي اســتلمها موكلــي‬\n  ‫فهــذا ال علــم لــي بــه وأمــا مــا ذكــره املدعــى عليــه مــن أن موكلــه لــم‬\n  ‫يســتفد مــن العمــارة فهــذا صحيــح ولكــن موكلــي قــد ســلم العمــارة‬\n  ‫املذكــورة للمدعــي أصالــة ولــم مينعــه مــن االنتفــاع بهــا وقــد تأخــر عــن‬\n  ‫التقــدمي للجنــة إســكان احلــج ولــم يســتطع ذلــك وأمــا مــا ذكــره املدعــي‬\n  ‫وكالــة مــن وجــود مخالفــة علــى العمــارة املذكــورة فهــذا غيــر صحيــح‬\n‫ومــا ذكــره املدعــي وكالــة مــن أن موكلــي أعــاد ملوكلــه مبلــغ وقــدره  ‬\n\n\n                                                                                             ‫‪378‬‬\n\f      ‫خمســون ألــف ريــال فهــذا صحيــح ولكــن ذلــك بعــد التهديــد واإلجبــار‬\n      ‫وقــد مت أخــذ املبلــغ منــه بغيــر وجــه حــق  ومــا طلبــه املدعــي وكالــة مــن‬\n      ‫إعــادة املبلــغ فموكلــي غيــر مســتعد بذلــك هكــذا أجــاب وبعــرض ذلــك‬\n      ‫ا الصحيــح مــا ذكــرت ولــدي البينــة‬         ‫علــى املدعــي وكالــة أجــاب قائ ـ ً‬\n      ‫علــى ذلــك هكــذا قــرر وبطلــب البينــة مــن املدعــي وكالــة أبــرز ســندات‬\n      ‫قبــض ‪ :‬األول برقــم ‪ 45951‬يف ‪1429/9/16‬ه ـ وفيــه مبلــغ  تســعون‬\n      ‫ألــف ريــال وذلــك مقابــل الدفعــة األولــى مــن إيجــار العمــارة الكائنــة ‪....‬‬\n      ‫واملســتلم ‪ ...............‬والثانــي برقــم ‪ 1204‬يف ‪1429/9/14‬ه ـ وفيــه مبلــغ‬\n      ‫عشــرة آالف ريــال  وذلــك عبــارة عــن عربــون إيجــار العمــارة الكائنــة‬\n      ‫‪....‬واملســتلم ‪ ................‬والثالــث برقــم ‪ 45966‬يف ‪1429/11/6‬ه ـ وفيــه‬\n      ‫مبلــغ عشــرة آالف ريــال وذلــك مقابــل عمــل أشــغال يف عمــارة ‪....‬واملســتلم‬\n      ‫‪ ...........‬والرابــع  برقــم ‪ 1225‬يف ‪1429/9/27‬ه ـ وفيــه مبلــغ خمســة‬\n      ‫وثالثــون ألــف ريــال  وذلــك مقابــل إيجــار العمــارة الكائنــة ‪....‬واملســتلم‬\n      ‫ا أطلب مهلة‬    ‫‪ .......‬أه ـ وبعــرض ذلــك علــى املدعــى عليــه وكالــة قــرر قائـ ً‬\n      ‫لعــرض ذلــك علــى موكلــي وســؤاله عــن املبالــغ التــي اســتلمها كمــا‬\n      ‫أبــرز إقــرار صــادر مــن املدعــى عليــه ونصــه كمــا يلــي ‪ :‬أقــر أنــا املدعــو‬\n      ‫‪ .............‬بنغالديشــي اجلنســية مبوجــب إقامــة رقــم ‪ ............‬بأنــه يف ذمتــي‬\n      ‫لصالــح ‪ ...........‬مائــة وأربعــون ألــف ريــال (‪ 140.000‬ريــال ) وذلــك نظيــر‬\n      ‫إعــادة إيجــار العمــارة التــي ســبق أن اســتأجرها املدعــو ‪ ............‬مــن األخ‬\n      ‫‪ .................‬الكائنــة ‪....‬حيــث إننــي أنــا صاحــب الصالحيــة بهــذا املبنــى‬\n      ‫واملدعــو ‪ .........‬لــه االســم وفائــدة بســيطة مــن قبلــي ومســتعد بإرجــاع‬\n      ‫املبلــغ هــذا علــى دفعــات بتاريــخ ‪1430/11/30‬ه ـ مبلــغ وقــدره  عشــرة‬\n      ‫اآلف ريــال وبتاريــخ ‪1430/12/30‬ه ـ عشــرون ألــف ريــال وبتاريــخ‬\n\n\n‫‪379‬‬\n\f   ‫‪1431/8/30‬ه ـ مبلــغ وقــدره (‪ 110.000‬ريــال (  مائــة وعشــرة اآلف‬\n   ‫ريــال ويف حالــة تأخــري عــن دفــع أي دفعــة مــن الدفعــات عــن تاريخهــا‬\n   ‫ا دون‬    ‫احملــدد وملــدة يومــن يصبــح كامــل املبلــغ واجــب الدفــع كام ـ ً‬\n   ‫مماطلــة أو تأخيــر  كمــا أقــر بــأن كامــل املبلــغ املذكــور مســئوليتي‬\n   ‫مســؤولية كاملــة كمــا ذكــرت ســابق ًا ومذيــل اإلقــرار بتوقيــع املقــر‬\n   ‫مبــا فيــه ‪............‬و‪ ..............‬والشــاهد ‪ ...................‬وبعرضــه علــى‬\n   ‫ا إن هــذا اإلقــرار صــادر‬     ‫املدعــى عليــه وكالــة صــادق عليــه وقــرر قائ ـ ً‬\n   ‫مــن موكلــي ولكنــه قــد أخــذ منــه باإلكــراه والقــوة اجلبريــة وقــد وضــع‬\n   ‫موكلــي إبهامــه عليــه وهــو ال يعلــم مضمونــه هكــذا قــرر وبعــرض ذلــك‬\n   ‫ا مــا ذكــره املدعــي وكالــة مــن أنــه مت‬       ‫علــى املدعــي وكالــة قــرر قائـ ً‬\n   ‫أخــذ اإلقــرار بالقــوة اجلبريــة فهــذا غيــر صحيــح هكــذا قــرر وبســؤال‬\n   ‫املدعــى عليــه وكالــة هــل لــدى موكلــك بينــة علــى أنــه مت أخــذ هــذا‬\n   ‫ا أطلــب مهلــة لســؤال موكلــي‬        ‫اإلقــرار باإلكــراه واإلجبــار فأجــاب قائـ ً‬\n   ‫واإلجابــة يف اجللســة القادمــة هكــذا أجــاب وقــرر وبســؤال املدعــي‬\n   ‫ا مت‬   ‫وكالــة متــى مت مطالبــة املدعــى عليــه بإعــادة املبلــغ فأجــاب قائ ـ ً‬\n‫مطالبتــه بإعــادة املبلــغ قبــل احلــج يف ‪1429/11/15‬ه ـ هكــذا أجــاب   ‬\n   ‫ا مــا ذكــره املدعــي‬     ‫وبعــرض ذلــك علــى املدعــى عليــه وكالــة قــرر قائـ ً‬\n   ‫وكالــة غيــر صحيــح فاملدعــي أصالــة لــم يطالــب موكلــي باملبلــغ إال بعد‬\n   ‫نهايــة احلــج هكــذا قــرر وبســؤال املدعــى عليه وكالة هــل لدى موكلك‬\n   ‫ا أطلــب مهلــة‬    ‫بينــة علــى تســليم العمــارة للمدعــي أصالــة فأجــاب قائ ـ ً‬\n   ‫لعــرض ذلــك علــى موكلــي واإلجابــة يف اجللســة القادمــة هكــذا أجــاب‬\n   ‫وقــرر ولطلــب املدعــى عليــه وكالــة فقــد رفعــت اجللســة ويف يــوم  األحــد‬\n   ‫املوافــق‪ 1433/11/21‬ه ـ افتتحــت اجللســة الســاعة  الثانيــة عشــرة ظهــر ًا‬\n\n\n                                                                                            ‫‪380‬‬\n\f        ‫وفيهــا حضــر  املدعــي وكالــة ولــم يحضــر املدعــى عليــه وال مــن ينــوب‬\n        ‫عنــه  وقــد جــرى طلبــه عــن طريــق محضــري اخلصــوم  بخطابنــا رقــم‬\n      ‫‪ 331398291‬يف  ‪1433/7/26‬هــ  فوردنــا منهــم شــرح ًا علــى اخلطــاب  ‬\n        ‫بتبلــغ املوظــف لــدى املؤسســة واســمه  ‪  .........‬ومذيــل احملضــر بتوقيــع‬\n      ‫محضــر اخلصــوم  ‪  .......‬ورئيــس قســم محضــري اخلصوم وبســؤال املدعي  ‬\n        ‫وكالــة هــل لديــك مــا تريــد  إضافتــه  فأجــاب بالنفــي  فبنــاء علــى مــا‬\n        ‫تقــدم  مــن الدعــوى اإلجابــة  ومبــا أن املدعــى عليــه وكالــة  قــد أقــر‬\n        ‫بصحــة  اإلقــرار  الصــادر  مــن موكلــه واملتضمــن  أن بذمتــه  لصالــح‬\n        ‫املدعــي أصالــة  املبلــغ املدعــى بــه   وأن آخــر دفعــة  مــن هــذا املبلــغ  تســلم‬\n        ‫يف ‪1431/8/30‬هــ  ولدفــع  املدعــى عليــه وكالــة بــأن هــذا اإلقــرار  قــد‬\n        ‫أخــذ  منــه بالقــوة   واإلكــراه  وطلــب مهلــة لســؤال  موكلــه عــن البينــة‬\n        ‫ولتخلفــه عــن اجللســة  املاضيــة وهــذه اجللســة  وألن تخلفــه يعــد نكــو ًال‬\n        ‫عــن اجلــواب  وبنــاء علــى املــادة  اخلامســة واخلمســون  والفقــرة الثانيــة‬\n      ‫مــن الئحــة املــادة  الثالثــة  بعــد املائــة   مــن نظــام املرافعــات  الشــرعية  ‬\n        ‫وألن  وكالــة املدعــى عليــه تخولــه  حــق  اإلقــرار  لذلــك فقــد حكمــت‬\n        ‫علــى املدعــى عليــه  حضوري ـ ًا بــأن يدفــع للمدعــي مبلــغ  وقــدره مائــة‬\n        ‫وأربعــون ألــف ريــال وبعــرض احلكــم  علــى املدعــي وكالــة قــرر قناعتــه‬\n        ‫باحلكــم وانتهــت اجللســة الســاعة  الثانيــة عشــرة والنصــف  ‪ ..‬وبــاهلل‬\n        ‫التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر‬\n                                                                         ‫يف  ‪ 1433/11/21‬ه ـ‬\n        ‫احلمــد هلل وحــده وبعــد   لــدي أنــا ‪ ......................‬القاضــي باحملكمــة‬\n        ‫العامــة مبكــة املكرمــة والقائــم بعمــل الشــيخ ‪ .....................‬أنــه يف يــوم‬\n        ‫االثنــن املوافــق ‪1434/4/1‬ه ـ افتتحــت اجللســة وقــد وردنــا خطــاب مدير‬\n\n\n‫‪381‬‬\n\f    ‫احملضريــن باحملكمــة برقــم ‪ 34498523‬يف  ‪1434/2/27‬هــ  بشــأن‬\n    ‫إبــاغ املدعــى عليــه الغائــب عــن مجلــس احلكــم ‪   ...............‬واملتضمــن‬\n    ‫بأنــه مت الوصــول إلــى عنــوان املذكــور أعــاه ولــم جنــده وبالســؤال عــن‬\n    ‫كفيــل املدعــى عليــه أفــاد أحــد العاملــن إنــه خــارج مكــة وباالتصــال‬\n    ‫علــى الهاتــف لــم يــرد علينــا أحــد أهــ  ومذيــل احملضــر بتوقيــع احملضــر‬\n    ‫‪ .......‬ورئيــس قســم احملضريــن   ‪ ....................‬وحيــث تعــذر تســليم‬\n    ‫املدعــى عليــه لشــخصه نســخة مــن إعــام احلكــم وبنــاء  علــى املــادة‬\n    ‫‪ 5/176‬مــن نظــام املرافعــات فقــد أمــرت بضبــط ذلــك وإحلاقــه بصكــه‬\n    ‫وســجله ورفــع كامــل املعاملــة حملكمــة االســتئناف لتدقيــق احلكــم‬\n    ‫حســب املتبــع وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                    ‫وصحبــه وســلم ‪ .‬حــرر يف  ‪ 1434/04/01‬ه ـ‬\n    ‫احلمــد هلل وحــده وبعــد ويف يــوم  األحــد     املوافــق  ‪ 1434/5/26‬ه ـ‬\n    ‫افتتحــت اجللســة وقــد وردتنــا املعاملــة اخلاصــة بدعــوى ‪ ..................‬ضــد‬\n    ‫املدعــى عليــه ‪    .......................‬مــن الدائــرة احلقوقيــة الســابعة مبحكمــة‬\n    ‫االســتئناف مبكــة املكرمــة  واملتضمــن احلمــد هلل وحــده وبعــد فقــد‬\n‫اطلعنــا علــى هــذا الصــك رقــم   ‪       3443385‬يف ‪1434/2/20‬ه ـ    ‬\n    ‫الصــادر مــن فضيلــة الشــيخ ‪ ........................... /‬القاضــي باحملكمــة‬\n    ‫العامــة مبكــة املكرمــة وأصدرنــا القــرار رقــم ‪     34201660‬يف‬\n    ‫‪1434/4/30‬هــ  املتضمــن املوافقــة علــى احلكــم أهــ  ‪ .‬عضــو ‪ ....‬ختمــه‬\n‫وتوقيعــه  عضــو ‪  ....‬ختمــه وتوقيعــه رئيــس الدائــرة  ‪ .....‬ختمــه وتوقيعــه  ‬\n‫عليــه فقــد أمــرت بضبــط ذلــك وإحلاقــه بصكــه وســجله حتــى ال يخفـى   ‬\n    ‫وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                 ‫وســلم ‪ .‬حــرر يف  ‪ 1434/5/26‬ه ـ‬\n\n\n                                                                                              ‫‪382‬‬\n\f        ‫احلمــد هلل وحــده‪ ،‬والصــاة والســام علــى مــن ال نبــي بعــده‪ ،‬وبعــد‪:‬‬\n        ‫‪ -‬فقــد جــرى منــا نحــن قضــا َة الدائــرة احلقوقيــة الســابعة مبحكمــة‬\n        ‫االســتئناف يف منطقــة مكــة املكرمــة االطال ُع علــى املعاملة الواردة من‬\n      ‫فضيلــة رئيــس احملكمــة العامــة مبكــة املكرمــة برقــم‪  321090281‬‬\n        ‫وتاريــخ ‪1434/  04 / 22‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلــة‬\n        ‫الشــيخ‪ ................... /‬القاضــي باحملكمــة العامــة مبكــة املكرمــة‬\n        ‫املســجل برقــم   ‪ 3443385‬وتاريــخ    ‪20/ 02 / 1434‬ه ـ املتضمــن‬\n      ‫دعــوى‪ ....................... /‬ضــد‪ .......................... /‬بنجالديشــي اجلنســية‪  ،‬‬\n        ‫وبدراســة الصــك وص ــورة ضبط ــه تق ــررت املوافق ــة عل ــى احلكــم‪ .‬واهلل‬\n             ‫املوفــق وصل ــى اهلل عل ــى نبينــا محمــد وعل ــى آل ــه وصحب ــه وســلم ‪.‬‬\n\n\n\n\n‫‪383‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"2e380a2f-49d8-5199-a84b-d3b37251547c","source_page_start":375,"source_page_end":383,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"6b7b54a87b30bcaa4f29e9bee4d5be7cfd91137f21f8827928ec3df101c9aee1","normalized_text_hash":"2e11a995b52e27dc6daa93092815c929ef0ebda44044e57cb9743451a1e5a5e3","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v6-p375-3443385"},{"id":"4a2d1d2b-2947-5ab3-8e82-4b543d43745a","document_type":"judgment","category":"judicial","subcategory":"general","title":"إجارة -محل وقف -سداد أجرة مستحقة -نظر الدعوى غيابي ا يف حق املدعى عليه -وجوب الوفاء بالعقود -اليمن تشرع يف جانب أقوى املتداعين -احلكم بدفع مبلغ األجرة على غائب تعذر تبليغه -الغائب على حجته متى حضر -رفع احلكم الغيابي حملكمة الاستئناف لتعذر تبليغ املدعي عليه.","document_number":"34186236","case_number":"33305127","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة جدة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/13","year":"1434","subject":"إجارة -محل وقف -سداد أجرة مستحقة -نظر الدعوى غيابي ا يف حق املدعى عليه -وجوب الوفاء بالعقود -اليمن تشرع يف جانب أقوى املتداعين -احلكم بدفع مبلغ األجرة على غائب تعذر تبليغه -الغائب على حجته متى حضر -رفع احلكم الغيابي حملكمة الاستئناف لتعذر تبليغ املدعي عليه.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"    ‫تاريخه‪1434/4/13 :‬هـ‬\n                     ‫ُ‬                 ‫َر ْق ُم َّ‬\n                         ‫الص ِّك‪34186236 :‬‬\n                        ‫َر ْق ُم الدعوى‪33305127 :‬‬\n        ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                ‫‪ 34237961‬تاريخه‪1434/6/12 :‬هـ‬\n\n\n\n    ‫إجــارة ‪ -‬محــل وقــف ‪ -‬ســداد أجــرة مســتحقة ‪ -‬نظــر الدعــوى غيابي ـ ًا‬\n    ‫يف حــق املدعــى عليــه ‪ -‬وجــوب الوفــاء بالعقــود ‪ -‬اليمــن تشــرع يف‬\n    ‫جانــب أقــوى املتداعيــن ‪ -‬احلكــم بدفــع مبلــغ األجــرة علــى غائــب‬\n    ‫تعــذر تبليغــه ‪ -‬الغائــب علــى حجتــه متــى حضــر ‪ -‬رفــع احلكــم الغيابــي‬\n                            ‫حملكمــة االســتئناف لتعــذر تبليــغ املدعــي عليــه‪.‬‬\n\n\n\n\n                         ‫‪ .1‬قوله تعالى {يأيها الذين آمنوا أوفوا بالعقود}‪.‬‬\n    ‫‪ .2‬قولــه صلــى اهلل عليــه وســلم (املســلمون علــى شــروطهم) رواه‬\n                                                        ‫الترمــذي وأبــو داوود‪.‬‬\n    ‫‪ .3‬قولــه صلــى اهلل عليــه وســلم (البينــة علــى املدعــي واليمــن علــى مــن‬\n                                                             ‫أنكــر) رواه الترمــذي‪.‬‬\n                        ‫‪ .4‬املادة ‪ 55‬واملادة ‪ 176‬من نظام املرافعات الشرعية‪.‬‬\n\n\n\n\n    ‫ادع ــى املدعــي ض ــد املدع ــى علـ ــيه الغائـ ــب مبطالبتــه بأجــرة محــل‬\n    ‫وقـ ــف‪ ،‬حيــث اســتأجر املدعــى عليــه مــن مــوكل املدعــي ناظــر الوقــف‬\n    ‫محــل يف مجمــع محــات واقعــه يف حــي ‪ ...‬يف جــدة وهــي وقــف وقــد‬\n    ‫أخلــى احملــل عــن طريــق وكيلــه واملبلــغ املتبقــي مــن األجــرة قــدره مائــه‬\n‫‪5‬‬\n\f‫وخمســة وعشــرون ألــف ريــال ‪ ،‬تعــذر تبليغــه حيــث مت البحــث عنــه‬\n‫طريــق الشــرطة ولــم يتــم العثــور عليــه ولــم يتوصــل إلــى أي معلومــة تفيــد‬\n‫مبــكان تواجــده ‪ ،‬حضــر املدعــي أصالــة بصفتــه ناظــر الوقــف وأبــرز‬\n‫أصــل صــك النظــارة وأصــل عقــد اإليجــار ‪ ،‬أحضــر شــاهدين شــهدا‬\n‫باســتئجار املدعــى عليــه احملــل وأنــه أقفــل احملــل منــذ عامــن وعــدم‬\n‫رؤيتــه بعــد إقفــال احملــل وأن وكيــل املدعــي حضــر قبــل عــام وبــاع‬\n‫كامــل بضاعــة احملــل ‪ ،‬مت تعديلهمــا شــرعا ‪ ،‬ثــم جــرى عــرض اليمــن‬\n‫علــى املدعــي علــى صحــة دعــواه وعــدم اســتالمه األجــرة املدعــى بهــا‬\n‫مــن املدعــى عليــه‪ ،‬حلــف املدعــي علــى ذلــك‪ ،‬بنــاء علــى البينــة املعدلــة‬\n‫شــرع ًا وعقــد اإليجــار ومبــا أن األصــل عــدم دفــع األجــرة ومبــا أن اليمــن‬\n‫تشــرع يف جانــب أقــوى املتداعيــن وبنــاء علــى ميــن املدعــي علــى صحــة‬\n‫الدعــوى وعــدم دفــع األجــرة ‪ ،‬صــدر احلكــم بإلــزام املدعــى عليــه بدفــع‬\n‫مبلــغ وقــدره خمســة وعشــرون ألــف ريــال للمدعــي أصالــة بصفتــه ناظــر‬\n‫الوقــف ‪ ،‬إفهــام املدعــي بــأن الغائــب علــى حجتــه متــى حضــر‪ ،‬رفــع‬\n‫احلكــم إلــى محكمــة االســتئناف لتدقيقــه كونــه حكــم علــى غائــب‬\n‫تعــذر تبليغــه ‪ ،‬صــدق احلكــم مــن الدائــرة احلقوقيــة اخلامســة مبحكمــة‬\n                                       ‫االســتئناف مبنطقــة مكــة املكرمــة‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪....‬القاضــي يف احملكمــة العامــة‬\n‫مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة العامــة مبحافظــة جدة‪/‬املســاعد برقــم ‪ 33305127‬وتاريــخ‬\n‫‪1433/05/02‬ه ـ املقيــدة باحملكمــة برقــم ‪ 33687015‬وتاريــخ‬\n\n                                                                                     ‫‪6‬‬\n\f    ‫‪1433/04/12‬ه ـ ففــي يــوم الثالثــاء املوافق‪1433/06/17‬ه ـ افتتحــت‬\n    ‫اجللســة الســاعة ‪ 11 : 30‬وفيهــا حضــر ‪.... ....‬ســعودي اجلنســية مبوجــب‬\n    ‫الســجل املدنــي رقــم ‪....‬بصفتــه وكيــا عــن ‪....‬ســعودي اجلنســية مبوجــب‬\n    ‫الســجل املدنــي رقــم ‪....‬بالوكالــة الصــادرة مــن كتابــة عــدل الثانيــة‬\n    ‫شــمال جــدة برقــم ‪ 23862‬وتاريــخ ‪1432/3/16‬ه ـ جلــد ‪ ، 10430‬ولــم‬\n    ‫يحضــر املدعــى عليــه ‪....‬وال مــن ميثلــه ‪ ،‬ولــم يردنــا مــا يفيــد تبليغــه ‪،‬‬\n    ‫وقــرر املدعــي وكالــة قائــا ‪ :‬أننــي ال أعــرف للمدعــى عليــه أي عنــوان‬\n    ‫‪ ،‬وأطلــب التعميــم عنــه عــن طريــق البحــث والتحــري ‪ .‬ثــم رفعــت اجللســة‬\n    ‫لذلــك ‪ .‬ويف يــوم الســبت املوافــق ‪1433/08/24‬ه ـ افتتحــت اجللســة‬\n    ‫الســاعة ‪ 10 : 30‬وفيهــا حضــر املدعــي ولــم يحضــر املدعــى عليــه ‪ ....‬وال‬\n    ‫مــن ميثلــه ‪ ،‬وقــد وردنــا خطــاب مديــر شــعبة التحريــات والبحــث اجلنائــي‬\n    ‫رقــم ‪/4/20/15825‬ع‪ 21‬وتاريــخ ‪1433/7/14‬هـ املتضمن أنه بالرجوع‬\n    ‫للحاســب اآللــي طرفنــا اتضــح بــأن للمدعــى عليــه عــدة عناويــن األول يف‬\n    ‫جــدة حــي ‪ ...‬شــارع ‪....‬هاتــف ‪....‬جــوال ‪ ،....‬وعنــوان آخــر ‪ .....‬أه ـ ثــم‬\n    ‫رفعــت اجللســة لطلــب املدعــى عليــه عــن طريــق العنــوان املبــن عــن طريــق‬\n    ‫شــعبة التحريــات والبحــث اجلنائــي ‪ .‬ويف يــوم األحــد املوافــق‬\n    ‫‪1434/04/07‬هـ افتتحت اجللســة الســاعة ‪ 11 : 30‬وفيها حضر املدعي‬\n    ‫وكالــة ‪ ،‬ولــم يحضــر املدعــى عليــه ‪....‬وال مــن ميثلــه ‪ ،‬وقــد وردنــا خطاب‬\n    ‫مديــر شــرطة محافظــة جــدة برقــم ‪ 10/1/2/2235‬وتاريــخ‬\n    ‫‪1433/4/11‬ه ـ واملتضمــن (أنــه بالبحــث عــن املذكــور لــم يتــم العثــور‬\n    ‫عليــه ولــم يتــم التوصــل إلــى أي معلومــة تفيــد مبــكان تواجــده) أه ـ‬\n    ‫وعليــه فقــد قــررت النظــر يف الدعــوى غيابيــا يف حــق املدعــى عليــه ‪،‬‬\n    ‫وادعــى املدعــي وكالــة قائــا ‪ :‬لقــد اســتأجر املدعــى عليــه عقــارا هــو‬\n\n\n‫‪7‬‬\n\f‫عبــارة عــن محــل رقــم ‪15‬يف مجمــع محــات واقعــة يف حــي ‪....‬مبحافظــة‬\n‫جــدة ‪ ،‬وهــي وقــف مــن أوقــاف ‪ ...‬الشــهير بوقــف ‪ ...‬بالصــك الصــادر مــن‬\n‫هــذه احملكمــة برقــم ‪ 13/557/11‬وتاريــخ ‪1425/5/23‬ه ـ ‪ ،‬والناظــر‬\n‫علــى هــذا الوقــف هــو موكلــي مبوجــب صــك النظــارة الصــادر مــن‬\n‫محكمــة شــرق املــكال برقــم القيــد ‪ 40‬يف ‪2010/4/22‬م واملصــادق‬\n‫مــن ســفارة اململكــة العربيــة الســعودية يف صنعــاء برقــم ‪ 173983‬يف‬\n‫‪1421/5/4‬ه ـ ومــن وزارة اخلارجيــة برقــم ‪ 18‬يف ‪1431/6/26‬ه ـ ومــن‬\n‫فــرع وزارة العــدل بجــدة رقــم ‪ 5605‬يف ‪1431/6/26‬ه ـ ‪ ،‬وقــد اســتأجره‬\n‫املدعــى عليــه مــن موكلــي بأجــرة ســنوية قدرهــا خمســة وخمســون ألــف‬\n‫ريــال تســلم بدايــة شــهر محــرم لــكل عــام هجــري ‪ ،‬اعتبــارا مــن تاريــخ‬\n‫‪1426/5/1‬ه ـ وينتهــي يف ‪1426/12/29‬ه ـ ‪ ،‬ثــم يبدأ يف ‪1427/1/1‬هـ‬\n‫وحتــى ‪1427/12/29‬ه ـ ويتجــدد املــدة تلقائيــا مــا لــم يخطــر أحــد‬\n‫الطرفــن اآلخــر بعــدم رغبتــه يف التجديــد قبــل انتهــاء مــدة العقــد‬\n‫بشــهرين علــى األقــل ‪ ،‬مبوجــب عقــد اإليجــار املــؤرخ يف ‪1426/5/26‬ه ـ‬\n‫واحملــرر علــى أوراق وقــف ‪ ، ....‬ثــم مت تخفيــض األجــرة الســنوية لتكــون‬\n‫خمســون ألــف ريــال ‪ ،‬وقــد دفــع مــن أجــرة العقــار مــن عــام ‪1430‬ه ـ‬\n‫مبلغــا قــدره خمســة وعشــرون ألــف ريــال وهــي متثــل نصــف أجــرة ذلــك‬\n‫العــام ‪ ،‬ومنــذ النصــف الثانــي مــن عــام ‪1430‬ه ـ وحتــى اآلن لــم يدفــع‬\n‫شــيئا ‪ ،‬وقــد اســتلم موكلــي احملــل يف ‪1433/1/30‬ه ـ عــن طريــق أحــد‬\n‫وكالء املدعــى عليــه واســمه ‪ ،....‬وقــد ترتــب بذمــة املدعــى عليــه للوقف‬\n‫مــن أجــرة العقــار محــل الدعــوى مبلغــا قــدره مائــة وخمســة وعشــرون‬\n‫ألــف ريــال ‪ ،‬وأطلــب إلــزام املدعــى عليــه بدفــع ذلــك املبلــغ ‪ .‬هــذه دعــواي‬\n‫‪ .‬ثــم أبــرز املدعــي وكالــة صــورة مــن صــك النظــارة وصــورة مــن عقــد‬\n\n\n                                                                                       ‫‪8‬‬\n\f    ‫اإليجــار وصــورة مــن صــك احلكــم الصــادر مــن هــذه احملكمــة ‪ ،‬ومت‬\n    ‫إرفاقهــا باملعاملــة ‪ ،‬وبســؤال املدعــي وكالــة عــن موكلــه ألداء اليمــن‬\n    ‫علــى صحــة الدعــوى وعــدم اســتالمه مــن مبلــغ الدعــوى مــن أجــرة العقــار‬\n    ‫محــل الدعــوى شــيئا قــال ‪ :‬أطلــب اإلمهــال إلحضــاره يف اجللســة القادمــة‬\n    ‫‪ .‬ثــم رفعــت اجللســة لذلــك ويف يــوم األربعــاء املوافــق ‪1434/04/10‬ه ـ‬\n    ‫افتتحــت اجللســة الســاعة ‪ 11 : 15‬وفيهــا حضــر املدعــي أصالــة ‪....‬‬\n    ‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪....‬بصفتــه الناظــر علــى‬\n    ‫الوقــف محــل الدعــوى مبوجــب صــك النظــارة الصــادر مــن محكمــة‬\n    ‫شــرق املــكال برقــم القيــد ‪ 40‬يف ‪2010/4/22‬م واملصــادق مــن ســفارة‬\n    ‫اململكــة العربيــة الســعودية يف صنعــاء برقــم ‪ 173983‬يف ‪1421/5/4‬هـ‬\n    ‫ومــن وزارة اخلارجيــة برقــم ‪ 18‬يف ‪1431/6/26‬ه ـ ومــن فــرع وزارة العدل‬\n    ‫بجــدة رقــم ‪ 5605‬يف ‪1431/6/26‬ه ـ ‪ ،‬ولــم يحضــر املدعــى عليــه ‪....‬وال‬\n    ‫مــن ميثلــه ‪ ،‬وأبــرز املدعــي أصــل صــك النظــارة ‪ ،‬وقــد ســبق إرفــاق صــورة‬\n    ‫منــه باملعاملــة ‪ ،‬كمــا أبــرز املدعــي أصــل عقــد اإليجــار املــؤرخ يف‬\n    ‫‪1426/5/26‬ه ـ واحملــرر علــى أوراق وقــف ‪ ، .....‬ومت تزويــد املعاملــة‬\n    ‫بنســخة منــه ‪ ،‬وبســؤاله زيــادة بينــة علــى دعــواه أحضــر للشــهادة وأدائهــا‬\n    ‫كال مــن ‪....‬مينــي اجلنســية مبوجــب اإلقامــة رقــم ‪....‬وهــو مــن مواليــد‬\n    ‫‪1962‬م ‪ ،‬ويعمــل يف شــركة ‪ ،....‬ويســكن يف حــي ‪ ،....‬وليــس بينــه‬\n    ‫وبــن طــريف الدعــوى قرابــة ‪.... ،‬مينــي اجلنســية مبوجــب اإلقامــة رقــم ‪....‬‬\n    ‫وهــو مــن مواليــد ‪1978‬م ‪ ،‬ويعمــل يف مؤسســة بــا ‪ ،....‬ويســكن يف حــي‬\n    ‫‪ ،....‬وليــس بينــه وبــن طــريف الدعــوى قرابــة ‪ ،‬وشــهد األول قائــا ‪:‬‬\n    ‫أشــهد هلل بأننــي أعمــل يف محــل مجــاور حملــل مســتأجر مــن قبــل املدعــى‬\n    ‫عليــه ‪.... ....‬يف مجمــع محــات واقعــة يف حــي ‪....‬واملعــروف باســم‪،....‬‬\n\n\n‫‪9‬‬\n\f‫واملدعــى عليــه مســتأجر لــه منــذ أكثــر مــن خمســة أعــوام ‪ ،‬وقــد أقفــل‬\n‫املدعــى عليــه احملــل منــذ حوالــي عامــن ‪ ،‬ولــم نــره بعــد إقفــال احملــل ‪،‬‬\n‫وقــد حضــر وكيــل للمدعــى عليــه قبــل حوالــي عــام ‪ ،‬وقــام ببيــع كامــل‬\n‫البضاعــة املوجــود يف احملــل بأربعــة آالف ريــال ‪ ،‬وهــي تســاوي أكثــر ‪.‬‬\n‫هكــذا شــهد ‪ .‬وشــهد الثانــي قائــا ‪ :‬أشــهد هلل بأننــي أعمــل يف محــل‬\n‫مجــاور حملــل مســتأجر مــن قبــل املدعــى عليــه ‪....‬يف مجمــع محــات‬\n‫واقعــة يف حــي ‪....‬واملعــروف باســم ‪ ،....‬واملدعــى عليــه مســتأجر لــه منــذ‬\n‫أكثــر مــن ثمانيــة أعــوام ‪ ،‬وقــد أقفــل املدعــى عليــه احملــل منــذ حوالــي‬\n‫عامــن ‪ ،‬ولــم نــره بعــد إقفــال احملــل ‪ ،‬وقــد حضــر وكيــل للمدعــى عليــه‬\n‫قبــل حوالــي عــام ‪ ،‬وقــام ببيــع كامــل البضاعــة املوجــود يف احملــل بأربعة‬\n‫آالف ريــال ‪ ،‬وهــي تســاوي أكثــر ‪ .‬هكــذا شــهد ‪ .‬وعــدال مــن قبــل ‪....‬‬\n‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪....‬و‪....‬ســعودي اجلنســية‬\n‫مبوجــب الســجل املدنــي رقــم ‪....‬وشــهد كل واحــد منهمــا مبفــرده بثقــة‬\n‫وعدالــة الشــاهدين ‪ ،‬وبعــرض اليمــن علــى املدعــي أصالــة علــى صحــة‬\n‫الدعــوى وعــدم اســتالمه مــن مبلــغ الدعــوى شــيئا ‪ ،‬اســتعد لذلــك ‪ ،‬ثــم‬\n‫حلــف قائــا ‪ :‬واهلل العظيــم الــذي ال إلــه إال هــو أن املدعــى عليــه ‪....‬‬\n‫اســتأجر عقــارا هــو عبــارة عــن محــل رقــم ‪15‬يف مجمــع محــات واقعــة‬\n‫يف حــي ‪....‬مبحافظــة جــدة ‪ ،‬وهــي وقــف مــن أوقــاف ‪.........‬الشــهير بوقف‬\n‫‪...‬بالصــك الصــادر مــن هــذه احملكمــة برقــم ‪ 13/557/11‬وتاريــخ‬\n‫‪1425/5/23‬ه ـ ‪ ،‬والناظــر علــى هــذا الوقــف هــو أنــا مبوجــب صــك‬\n‫النظــارة الصــادر مــن محكمــة شــرق املــكال برقــم القيــد ‪ 40‬يف‬\n‫‪2010/4/22‬م واملصــادق مــن ســفارة اململكــة العربيــة الســعودية يف‬\n‫صنعــاء برقــم ‪ 173983‬يف ‪1421/5/4‬ه ـ ومــن وزارة اخلارجيــة برقــم ‪18‬‬\n\n\n                                                                                     ‫‪10‬‬\n\f     ‫يف ‪1431/6/26‬ه ـ ومــن فــرع وزارة العــدل بجــدة رقــم ‪ 5605‬يف‬\n     ‫‪1431/6/26‬ه ـ ‪ ،‬وقــد اســتأجره املدعــى عليــه منــي بأجــرة ســنوية‬\n     ‫قدرهــا خمســة وخمســون ألــف ريــال تســلم بدايــة شــهر محــرم لــكل عــام‬\n     ‫هجــري ‪ ،‬اعتبــارا مــن تاريــخ ‪1426/5/1‬هـ وينتهــي يف ‪1426/12/29‬هـ‬\n     ‫‪ ،‬ثــم يبــدأ يف ‪1427/1/1‬ه ـ وحتــى ‪1427/12/29‬ه ـ ويتجــدد املــدة‬\n     ‫تلقائيــا مــا لــم يخطــر أحــد الطرفــن اآلخــر بعــدم رغبتــه يف التجديــد‬\n     ‫قبــل انتهــاء مــدة العقــد بشــهرين علــى األقــل ‪ ،‬مبوجــب عقــد اإليجــار‬\n     ‫املــؤرخ يف ‪1426/5/26‬ه ـ واحملــرر علــى أوراق وقــف ‪ ،...‬ثــم مت تخيــض‬\n     ‫األجــرة الســنوية لتكــون خمســون ألــف ريــال ‪ ،‬وقــد دفــع مــن أجــرة‬\n     ‫العقــار مــن عــام ‪1430‬ه ـ مبلغــا قــدره خمســة وعشــرون ألــف ريــال وهــي‬\n     ‫متثــل نصــف أجــرة ذلــك العــام ‪ ،‬ومنــذ النصــف الثانــي مــن عــام ‪1430‬ه ـ‬\n     ‫وحتــى اآلن لــم يدفــع شــيئا ‪ ،‬وقــد اســتلمت احملــل يف ‪1433/1/30‬ه ـ‬\n     ‫عــن طريــق أحــد وكالء املدعــى عليــه واســمه ‪ ،....‬وقــد ترتــب بذمــة‬\n     ‫املدعــى عليــه للوقــف مــن أجــرة العقــار محــل الدعــوى مبلغــا قــدره مائــة‬\n     ‫وخمســة وعشــرون ألــف ريــال ‪ ،‬ولــم اســتلم مــن مبلــغ الدعــوى شــيئا حتــى‬\n     ‫اليــوم ‪ .‬هكــذا حلــف ‪ .‬ثــم رفعــت اجللســة لضيــق الوقــت ورغبــة احلضــور‬\n     ‫االنصــراف ويف يــوم الســبت املوافــق ‪1434/04/13‬ه ـ افتتحــت اجللســة‬\n     ‫الســاعة ‪ 12 : 30‬وفيهــا حضــر املدعــي أصالــة ‪....‬ســعودي اجلنســية‬\n     ‫مبوجــب الســجل املدنــي رقــم ‪....‬بصفتــه الناظــر علــى الوقــف محــل‬\n     ‫الدعــوى ‪ ،‬ولــم يحضــر املدعــى عليــه ‪....‬وال مــن ميثلــه ‪ ،‬وبعــد التأمــل ‪،‬‬\n     ‫وبنــاء علــى مــا تقــدم مــن الدعــوى والبينــة املتمثلــة يف صــك النظــارة‬\n     ‫الصادر من محكمة شــرق املكال برقم القيد ‪ 40‬يف ‪2010/4/22‬م‪،‬‬\n     ‫وصــك الصــادر مــن هــذه احملكمــة برقــم ‪ 13/557/11‬وتاريــخ‬\n\n\n‫‪11‬‬\n\f‫‪1425/5/23‬ه ـ ‪ ،‬وشــهادة كال مــن ‪....‬و‪ ....‬واملعدلــة شــرعا ‪ ،‬وبنــاء‬\n‫علــى عقــد اإليجــار املــؤرخ يف ‪1426/5/26‬ه ـ ‪ ،‬وبناء علــى إقرار املدعي‬\n‫وكالة واملدعي أصالة باستالم العني محل الدعوى يف ‪1433/1/30‬هـ‬\n‫عــن طريــق أحــد وكالء املدعــى عليــه واســمه ‪ ،....‬وبنــاء علــى ميــن‬\n‫املدعــي أصالــة علــى صحــة الدعــوى وعــدم اســتالم املدعــي مــن مبلــغ‬\n‫الدعــوى شــيئا ‪ ،‬ومبــا أن األصــل عــدم دفــع األجــرة ‪ ،‬وبنــاء علــى أن‬\n‫اليمــن تشــرع يف جانــب أقــوى املتداعيــان كمــا قــرر ذلــك أهــل العلــم ‪،‬‬\n‫ولقولــه تعالــى (يــا أيهــا الذيــن آمنــوا أوفوا بالعقود) ‪ ،‬وحلديث (املســلمون‬\n‫علــى شــروطهم) رواه الترمــذي وأبــو داوود ‪ ،‬وحلديــث (البينــة علــى‬\n‫املدعــي واليمــن علــى املدعــى عليــه) رواه الترمــذي ‪ ،‬قــال أبــو عيســى ‪:‬‬\n‫العمــل عنــد أهــل العلــم مــن أصحــاب النبــي صلــى اهلل عليــه وســلم‬\n‫وغيرهــم أن البينــة علــى املدعــي واليمــن علــى املدعــى عليــه ‪ ،‬وبنــاء‬\n‫علــى املــادة ‪ 55‬و ‪ 176‬مــن نظــام املرافعــات الشــرعية ‪ ،‬لذلــك كلــه ‪،‬‬\n‫فقــد حكمــت علــى املدعــى عليــه ‪ ....‬بدفــع مبلــغ قــدره مائــة وخمســة‬\n‫وعشــرون ألــف ريــال تســلم للمدعــي ‪ ........‬بصفتــه الناظــر علــى الوقــف‬\n‫محــل الدعــوى ‪ ،‬وأفهمــت املدعــي بــأن الغائــب علــى حجتــه متــى حضــر ‪.‬‬\n‫وبــه حكمــت ‪ .‬وبــه قنــع املدعــي ‪ ،‬وقــررت بعــث املعاملــة حملكمــة‬\n‫االســتئناف لتدقيــق احلكــم كــون احلكــم علــى غائــب تعــذر تبليغــه ‪.‬‬\n‫وأقفلــت اجللســة الســاعة ‪ . 12 : 40‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى‬\n         ‫نبينا محمد وعلى آله وصحبه وسلم ‪ .‬حرر يف ‪1434/04/13‬هـ‬\n‫احلمــد هلل وحــده ‪ ،‬والصــاة والســام علــى رســول اهلل ‪ ،‬وبعــد ‪ :‬ـ نحــن‬\n‫قضــا َة االســتئناف بالدائــرة احلقوقيــة اخلامســة يف محكمــة االســتئناف‬\n‫مبنطقــة مكــة املكرمــة جــرى م ّنــا االطــا ُع علــى هــذا احلكــم الصــادر‬\n\n\n                                                                                    ‫‪12‬‬\n\f     ‫مــن فضيلــة الشــيخ ‪....‬القاضــي باحملكمــة العامــة بجــدة املســجل‬\n     ‫بعــدد ‪ 34186236‬وتاريــخ ‪1434/4/13‬ه ـ املتضمــن دعــوى ‪....‬ضــد‬\n     ‫‪....‬احملكــوم في ــه مبــا دون باطــن الصــك ‪ ،‬وبدراســة احلكــم وص ــورة‬\n     ‫ضبط ــه تق ــررت املوافق ــة عل ــى احلكــم والغائــب علــى حجتــه اذا حضــر ‪.‬‬\n     ‫وباهلل التوفيق وصل ــى اهلل عل ــى نبينا محمد وعل ــى آل ــه وصحب ــه وسلم‪.‬‬\n\n\n\n\n‫‪13‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"612f1ba9-3f27-52bc-993f-69d3ecdc8564","source_page_start":5,"source_page_end":13,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"840db73ddbc1a5141004c95ad3477e1e7f78e920af2825c208f6ddc34599d8a8","normalized_text_hash":"91b347974e6ce7e609d0568329e54df742f40b99bb0299b4d40ac848d3168475","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v7-p5-34186236"},{"id":"3c09ccb0-3d19-506a-b720-90292a7a0d00","document_type":"judgment","category":"judicial","subcategory":"general","title":"إجارة -شيول مسروق -حكم سابق بالتسلم -مطالبة اجره مدة بقاء شيول لدى مشريه -اخلراج بالضمان -العن يف ضمان املدعى عليه -احلكم برد دعوى املدعي.","document_number":"34325602","case_number":"33333050","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض ف","circuit":"الدائرة برد دعوى املدعي وكالة وأخلت سبيل املدعى عليه أصالة","issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/9/24","year":"1434","subject":"إجارة -شيول مسروق -حكم سابق بالتسلم -مطالبة اجره مدة بقاء شيول لدى مشريه -اخلراج بالضمان -العن يف ضمان املدعى عليه -احلكم برد دعوى املدعي.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫تاريخه‪1434/9/24 :‬هـ‬\n                      ‫ُ‬                ‫َر ْق ُم َّ‬\n                         ‫الص ِّك‪34325602 :‬‬\n                        ‫َر ْق ُم الدعوى‪33333050 :‬‬\n        ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n              ‫‪ 34385546‬تاريخه‪1434/12/23 :‬هـ‬\n\n\n\n     ‫إجــارة ‪ -‬شــيول مســروق ‪-‬حكــم ســابق بالتســلم ‪ -‬مطالبــة اجــره مــدة‬\n     ‫بقــاء شــيول لــدى مشــريه ‪ -‬اخلــراج بالضمــان ‪ -‬العــن يف ضمان املدعى‬\n                                       ‫عليــه ‪ -‬احلكــم بــرد دعــوى املدعــي‪.‬‬\n\n\n\n\n     ‫غالمــا فأقــام‬\n                   ‫ً‬     ‫أن رجــا ابتــاع‬‫‪ -1‬مــا روي عــن عائشــة رضــي اهلل عنهــا َّ‬\n     ‫فخاصمــه إلــى النبـ ِّـي‬\n                           ‫َ‬       ‫عيبــا‬\n                                      ‫هلل أن يقيـ َـم ثــم وجــد بــه ً‬   ‫عنــده مــا شــاء ا ُ‬\n     ‫ـتغل غالمــي‬                                                                    ‫ص َّلــى ا ُ‬\n                 ‫هلل علي ـ ِه وس ـ َّل َم فقــال الرجـ ُـل يــا رســولَ اهلل قــد اسـ َّ‬\n     ‫فقــال النبــي عليــه الصــاة والســام (اخلــراج بالضمــان) ‪ ،‬أخرجــه‬\n                                        ‫الترمــذي وأبــو داود يف ســننهما وغيرهمــا‪.‬‬\n     ‫‪ -2‬قــال اإلمــام الســيوطي تعليقــا علــى قاعــدة (اخلــراج بالضمــان) يف‬\n     ‫كتابــه األشــباه والنظائــر‪ :‬قــال أبوعبيــد ‪ :‬اخلــراج يف هــذا احلديــث‬\n     ‫غلــة العبــد يشــتريه الرجــل فيســتغله زمانــا ‪ ،‬ثــم يعثــر منــه علــى عيــب‬\n     ‫دلســه البائــع ‪ ،‬فيــرده ‪ ،‬ويأخــذ جميــع الثمــن ‪ .‬ويفــوز بغلتــه كلهــا؛‬\n                ‫ألنــه كان يف ضمانــه ‪ ،‬ولــو هلــك هلــك مــن مالــه ‪ ،‬انتهــى ‪.‬‬\n     ‫‪ -3‬وكــذا قــال الفقهــاء ‪ :‬معنــاه مــا خــرج مــن الشــيء ‪ :‬مــن غلــة ‪،‬‬\n     ‫ومنفعــة ‪ ،‬وعــن ‪ ،‬فهــو للمشــتري عــوض مــا كان عليــه مــن ضمــان‬\n     ‫امللــك ‪،‬فإنــه لــو تلــف املبيــع كان مــن ضمانــه ‪ ،‬فالغلــة لــه ‪ ،‬ليكــون‬\n                                                    ‫الغنــم يف مقابلــة الغــرم‪ .‬انتهــى‪.‬‬\n\n‫‪25‬‬\n\f‫ادعــى املدعــي بدعــوى ضــد املدعــى عليــه بأنــه صــدر لــه حكــم يقضــي‬\n‫بــأن الشــيول الــذي بحــوزة املدعــى عليــه ملكــه لــذا فيطلــب تقديــر أجرة‬\n‫فتــرة بقائــه يف يــد املدعــى عليــه وإلزامــه بدفعــه لــه ‪ ،‬أقــر املدعــى عليــه‬\n‫بأنــه صــدر عليــه حكــم يلزمــه بتســليم الشــيول الــذي بحوزتــه للمدعــي‬\n‫إال أنــه دفــع بأنــه لــم يســرقه منــه بــل تعــرض لنصــب واحتيــال حيــث قــام‬\n‫بشــرائه من شــخص ظهر فيما بعد بأن املســتند الذي اعتمد عليه مزور‬\n‫لــذا فيطلــب صــرف النظــر عــن دعــواه ‪ ،‬جــرى االطــاع علــى احلكــم‬\n‫الســابق امللــزم للمدعــى عليــه بتســليم العــن للمدعــي بعدمــا ظهــر تزويــر‬\n‫الوثيقــة ‪ -‬ألن املدعــى عليــه وكالــة قــد أقــر بصحــة مــا ذكــره املدعــى‬\n‫وكالــة مــن دخــول املعــدة املدعــى بهــا يف حيــازة موكلــه بطريــق مشــروع‬\n‫«بالشــراء ممــن ادعــى ملكيتــه لهــا» ‪ ،‬وأنــه تعــرض للنصــب واالحتيــال‪،‬‬\n‫غالمــا فأقــام‬‫ً‬      ‫أن رجــا ابتــاع‬\n                                    ‫وملــا روي عــن عائشــة رضــي اهلل عنهــا أن َّ‬\n‫فخاصمــه إلــى النبـ ِّـي ص َّلــى‬    ‫عيبــا‬                           ‫ُ‬\n                              ‫َ‬          ‫عنــده مــا شــاء اهلل أن يقيـ َـم ثــم وجــد بــه ً‬\n‫اهلل علي ِــه وس ـل ََّم فقــال الرجــلُ يــا رســولَ اهلل قــد اســتغلَّ غالمــي فقــال‬ ‫ُ‬\n‫النبــي عليــه الصــاة والســام (اخلــراج بالضمــان) ‪ ،‬أخرجــه الترمــذي‬\n‫وأبــو داود يف ســننهما وغيرهمــا‪ ،‬قــال اإلمــام الســيوطي تعليقــا علــى‬\n‫قاعــدة (اخلــراج بالضمــان) يف كتابــه األشــباه والنظائــر‪« :‬قــال أبوعبيد‪:‬‬\n‫اخلــراج يف هــذا احلديــث غلــة العبــد يشــتريه الرجــل فيســتغله زمانــا‪ ،‬ثــم‬\n‫يعثــر منــه علــى عيــب دلســه البائــع ‪ ،‬فيــرده‪ ،‬ويأخــذ جميع الثمــن ‪ .‬ويفوز‬\n‫بغلتــه كلهــا ‪ ،‬ألنــه كان يف ضمانــه‪ ،‬ولــو هلــك هلــك مــن ماله‪ ،‬انتهى‪،‬‬\n‫وكــذا قــال الفقهــاء ‪ :‬معنــاه مــا خــرج مــن الشــيء‪ :‬مــن غلــة‪ ،‬ومنفعــة‪،‬‬\n\n\n                                                                                                ‫‪26‬‬\n\f     ‫وعــن ‪ ،‬فهــو للمشــتري عــوض مــا كان عليــه مــن ضمــان امللــك ‪،‬فإنــه‬\n     ‫لــو تلــف املبيــع كان مــن ضمانــه ‪ ،‬فالغلــة لــه ‪ ،‬ليكــون الغنــم يف مقابلــة‬\n     ‫الغــرم» انتهــى ‪ ،‬وألن املعــدة طيلــة بقائهــا يف يــد املدعــى عليــه أصالــة يف‬\n     ‫ضمانــه وليســت يف ضمــان مالكهــا ‪ ،‬وقــد نهــى النبــي عليــه الصــاة‬\n     ‫والســام عــن ربــح مــا لــم يضمــن ‪ ،‬ولــكل مــا تقــدم فقــد حكمــت‬\n     ‫الدائــرة بــرد دعــوى املدعــي وكالــة وأخلــت ســبيل املدعــى عليــه أصالــة‬\n     ‫منهــا ‪ ،‬بعــرض احلكــم علــى املدعــي وكالــة قــرر اعتراضــه عليــه فأفهم‬\n                        ‫بالتعليمــات ‪ ،‬صــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n     ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد فلــدي‬\n     ‫أنــا ‪ ...........................‬القاضــي يف احملكمــة العامــة بالريــاض ففــي‬\n     ‫يــوم الثالثــاء املوافــق ‪ 1434/09/22‬ه ـ افتتحــت اجللســة الســاعة‬\n     ‫الواحــدة والنصــف ‪ ،‬حضــر ‪ ............................‬حامــل الســجل املدنــي‬\n     ‫رقــم ‪ ..................‬مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل الثانيــة‬\n     ‫بالدمــام برقــم ‪ 34205‬يف ‪1432/7/6‬ه ـ عــن ‪ ......................‬حامــل‬\n     ‫الســجل املدنــي رقــم ‪ ...................‬والتــي تخولــه حــق املطالبــة واملرافعــة‬\n     ‫واملخاصمــة وإقامــة الدعــاوى انتهــى مضمونهــا‪ ،‬وادعــى علــى احلاضــر‬\n     ‫معــه ‪ ........................‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n     ‫‪ .....................‬بصفتــه وكيــا عــن ‪ ...........................‬ســعودي اجلنســية‬\n     ‫مبوجــب الســجل املدنــي رقــم ‪ .................‬وذلــك بالوكالــة الصــادرة‬\n     ‫مــن كتابــة العــدل الثانيــة بشــرق الريــاض برقــم ‪ 341277286‬وتاريــخ‬\n     ‫‪1434/9/21‬ه ـ قائــا يف دعــواه عليــه ‪ :‬إنــه ملوكلــي شــيول حجــم ‪2966‬‬\n\n‫‪27‬‬\n\f‫نــوع ‪ ....‬ويحمــل رقــم الهيــكل ‪ ...‬صنــع عــام ‪1976‬م ‪ ،‬وقد فقده موكلي‬\n‫واتضــح أنــه مســروق ووجــده بحــوزة املدعــى عليــه أصالة وتقــدم موكلي‬\n‫بدعــوى انتهــت باحلكــم بإلــزام املدعــى عليــه أصالــة بتســليم الشــيول‬\n‫ملوكلــي وذلــك بالصــك الصــادر مــن هــذه احملكمــة برقــم ‪32326862‬‬\n‫يف ‪1432/11/20‬ه ـ ‪ ،‬ونظــرا ألن الشــيول كان بحــوزة املدعــى عليــه‬\n‫مــن تاريــخ ‪1432/6/25‬ه ـ إلــى تاريــخ تســليمه لنــا يف ‪1433/5/4‬ه ـ‬\n‫ونظــرا ألن أجــرة الشــيول اليوميــة ثمامنائــة ريــال لــذا فأطلــب إلــزام‬\n‫املدعــى عليــه أصالــة بأجــرة الشــيول مــدة بقائــه لديــه والبالــغ قدرهــا‬\n‫مائتــان وأربعــون ألــف ريــال هــذه دعــواي ‪ ،‬وبعــرض مــا جــاء يف الدعــوى‬\n‫علــى املدعــى عليــه وكالــة أجــاب قائــا ‪ :‬مــا جــاء يف دعــوى املدعــي‬\n‫وكالــة كلــه صحيــح ‪ ،‬ولكــن موكلــي غــرر بــه حيــث أنــه اشــترى‬\n‫الشــيول مــن شــخص يدعــى ‪ ...........‬مببلــغ قــدره مائــة وثالثــون ألــف ريــال‬\n‫‪ ،‬ولــدي مبايعــة موقعــة بذلــك ‪ ،‬وقــد قــدم لــي ‪ ........‬مــا يثبــت شــراءه‬\n‫للشــيول مــن مالكــه املدعــي أصالــة ‪ ،‬واتضــح فيمــا بعــد أن املســتند‬\n‫الــذي قدمــه لنــا ‪...‬مــزور وغيــر صحيــح ‪ ،‬ومثبــت ذلــك بالصــك املشــار‬\n‫إليــه يف الدعــوى ‪ ،‬وقــد تقــدم موكلــي بدعــوى ضــد ‪ ..........‬ال زالــت‬\n‫قيــد النظــر ‪ ،‬وبنــاء عليــه فــإن موكلــي مغــرر بــه ووقــع ضحيــة نصــب‬\n‫واحتيــال لــذا فــإن موكلــي غيــر مســتعد بدفــع األجــرة املدعــى بهــا‬\n‫هكــذا أجــاب ‪ ،‬وبعــرض مــا جــاء يف جوابــه علــى املدعــي وكالــة أجــاب‬\n‫قائــا مــا ذكــره املدعــي وكالــة مــن أنــه اشــترى الشــيول بنــاء علــى‬\n‫مبايعــة مــزورة ‪ ،‬وأنــه قــد وقــع ضحيــة نصــب واحتيــال صحيــح ‪ ،‬والبائــع‬\n‫املســمى ‪ ..............‬ال يعــرف لــه مــكان وال هويــة ولــم جنــد عنــه معلومــات‬\n‫‪ ،‬ولكــن موكلــي يطلــب بإلزامــه بأجــرة الفتــرة التــي بقي فيها الشــيول‬\n\n\n                                                                                       ‫‪28‬‬\n\f     ‫حتــت تصرفــه هكــذا أجــاب ‪ ،‬فأفهمــت املدعــي وكالــة بــأن وكالتــه‬\n     ‫ال تخولــه اإلقــرار عــن موكلــه فأجــاب قائــا أطلــب إمهالــي إلبــاغ‬\n     ‫موكلــي باحلضــور أو تزويــدي بوكالــة تخولنــي اإلقــرار هكــذا قــرر‬\n     ‫ثــم جــرى االطــاع علــى الصــك املشــار إليــه يف الدعــوى فوجدتــه تضمــن‬\n     ‫تبــن تزويــر املســتند املتضمــن املبايعــة مــن املدعــي أصالــة للمدعــو ‪،...‬‬\n     ‫وتضمــن احلكــم علــى املدعــى عليــه ‪ ..............‬بتســليم الشــيول املدعــى‬\n     ‫بــه للمدعــي ‪ ............‬ا‪.‬ه ـ ‪ ،‬ثــم رفعــت اجللســة إلمهــال املدعــي وكالــة‬\n     ‫إلــى يــوم اخلميــس املوافــق ‪1434/9/24‬ه ـ الســاعة الواحــدة ‪ .‬ويف املوعــد‬\n     ‫احملــدد حضــر املدعــي وكالــة وقــدم وكالتــه عــن موكلــه الصــادرة من‬\n     ‫كاتــب العــدل باحلرجــة برقــم ‪ 33‬يف ‪1434/9/23‬ه ـ اجللد ‪ 116‬واملخول‬\n     ‫لــه فيهــا باإلقــرار واإلنــكار وقبــول األحــكام واالعتــراض عليهــا فيمــا‬\n     ‫يخــص الشــويل اخلــاص بــه انتهــى مضمونهــا ‪ ،‬كمــا حضــر املدعــى عليه‬\n     ‫وكالــة ‪ ،‬فجــرى عــرض مــا ســبق ضبطــه عليهمــا فصادقــا عليــه ‪ ،‬فبناء‬\n     ‫علــى مــا تقــدم مــن الدعــوى واإلجابــة ومــا قــرره الطرفــان ‪ ،‬ومبــا أن‬\n     ‫املدعــى عليــه وكالــة قــد أقــر بصحــة مــا ذكــره املدعــى عليــه وكالــة‬\n     ‫مــن أن دخــول املعــدة املدعــى بهــا يف حيازة موكله كان بطريق مشــروع‬\n     ‫بالشــراء ممــن ادعــى ملكيتــه لهــا ‪ ،‬وأنــه تعــرض للنصــب واالحتيــال‪،‬‬\n     ‫غالمــا فأقــام‬‫ً‬      ‫أن رجـ ًـا ابتــاع‬\n                                           ‫وملــا روي عــن عائشــة رضــي اهلل عنهــا أن َّ‬\n     ‫فخاصمــه إلــى النبـ ِّـي ص َّلــى‬      ‫عيبــا‬                           ‫ُ‬\n                                   ‫َ‬            ‫عنــده مــا شــاء اهلل أن يقيـ َـم ثــم وجــد بــه ً‬\n     ‫اهلل علي ِــه وس ـل ََّم فقــال الرجــلُ يــا رســولَ اهلل قــد اســتغلَّ غالمــي فقــال‬   ‫ُ‬\n     ‫النبــي عليــه الصــاة والســام (اخلــراج بالضمــان) ‪ ،‬أخرجــه الترمــذي‬\n     ‫وأبــو داود يف ســننهما وغيرهمــا‪ ،‬قــال اإلمــام الســيوطي تعليقــا علــى‬\n     ‫قاعــدة (اخلــراج بالضمــان) يف كتابــه األشــباء والنظائــر‪ « :‬قــال أبــو‬\n\n\n‫‪29‬‬\n\f‫عبيــد‪ :‬اخلــراج يف هــذا احلديــث غلــة العبــد يشــتريه الرجــل فيســتغله‬\n‫زمانــا‪ ،‬ثــم يعثــر منــه علــى عيــب دلســه البائــع ‪ ،‬فيــرده ‪ ،‬ويأخــذ جميــع‬\n‫الثمــن ‪ .‬ويفــوز بغلتــه كلهــا؛ ألنــه كان يف ضمانــه ‪ ،‬ولــو هلــك هلــك‬\n‫مــن مالــه ‪ ،‬انتهــى ‪ ،‬وكــذا قــال الفقهــاء ‪ :‬معنــاه مــا خــرج مــن الشــيء‬\n‫‪ :‬مــن غلــة ‪ ،‬ومنفعــة ‪ ،‬وعــن ‪ ،‬فهــو للمشــتري عــوض مــا كان عليــه‬\n‫مــن ضمــان امللــك ‪ ،‬فإنــه لــو تلــف املبيــع كان مــن ضمانــه ‪ ،‬فالغلــة لــه‬\n‫‪ ،‬ليكــون الغنــم يف مقابلــة الغــرم» انتهــى ‪ ،‬وألن املعــدة طيلــة بقائهــا يف‬\n‫يــد املدعــى عليــه أصالــة وهــي يف ضمانــه وليســت يف ضمــان مالكهــا ‪،‬‬\n‫وقــد نهــى النبــي عليــه الصــاة والســام عــن ربــح مــا لــم يضمــن ‪ ،‬ولــكل‬\n‫مــا تقــدم فقــد حكمــت بــرد دعــوى املدعــي وكالــة وأخليــت ســبيل‬\n‫املدعــى عليــه أصالــة منهــا ‪ ،‬وبعــرض احلكــم علــى املدعــى وكالــة قــرر‬\n‫اعتراضــه عليــه مســتعدا بتقــدمي الئحــة اعتراضيــة ‪ ،‬فأفهــم بأنــه ســيتم‬\n‫تســليمه نســخة مــن صــك احلكــم حــاال ‪ ،‬ولــه تقــدمي اعتراضــه عليــه‬\n‫خــال ثالثــن يومــا مــن تاريــخ هــذا اليــوم ‪ ،‬وإذا لــم يتقــدم باعتراضــه‬\n‫خاللهــا ســقط حقــه يف االعتــراض واكتســب احلكــم القطعيــة ففهــم‬\n‫ذلــك ‪ ،‬وختمــت اجللســة الســاعة الواحــدة والنصــف ‪ ،‬وبــاهلل التوفيــق‪،‬‬\n‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n                                                                ‫‪1434/9/24‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد‪ ..‬فقــد اطلعنــا نحــن قضــاة الدائــرة اجلزائيــة‬\n‫األولــى مبحكمــة االســتئناف بالريــاض علــى املعاملــة الــواردة مــن‬\n‫فضيلــة رئيــس احملكمــة العامــة بالريــاض برقــم ‪ 33905024‬وتاريــخ‬\n‫‪1434/11/13‬ه ـ واملرفــق بهــا الصــك الصــادر مــن فضيلــة القاضــي بالم‬\n‫حكمــة‪ ............................/‬برقــم ‪ 34325602‬وتاريــخ ‪1434/9/24‬ه ـ‬\n\n\n                                                                                    ‫‪30‬‬\n\f     ‫واخلــاص بدعــوى‪ ، ............ /‬ضــد‪ ،................. /‬وموضوعهــا أجــرة‬\n     ‫شــيول‪ ،‬وانتهــت الدراســة والتدقيــق باملصادقــة علــى احلكــم لعــدم‬\n     ‫موجــب املالحظــة ‪ ،‬واهلل املوفــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                                             ‫آلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n‫‪31‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"612f1ba9-3f27-52bc-993f-69d3ecdc8564","source_page_start":25,"source_page_end":31,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"1fa74e8a1a861dde619b832d1d99a65f805baec647867061058d83cd42dd3e9e","normalized_text_hash":"06a238eba7a1f630a4d3eb0b6cf6e32c042009ded87ee7bc294643113ed2165e","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v7-p25-34325602"},{"id":"fb8d65f6-4331-59c3-b371-6c0e11161699","document_type":"judgment","category":"judicial","subcategory":"general","title":"إجارة -أيجار منتهي بالتملك -مطالبة بتسليم سيارة بديلة ورفع اسم من القائمة السوداء وتعويض عن ضرر -دفع املدعى عليها بفسخ العقد واملطالبة بأجرة -رد دعوى املدعي وإلزامه بدفع أجرة فترة بقاء السيارة بيده ورفع اسمه من القائمة بعدها.","document_number":"4311281","case_number":"33360874","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة جدة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/9/2","year":"1434","subject":"إجارة -أيجار منتهي بالتملك -مطالبة بتسليم سيارة بديلة ورفع اسم من القائمة السوداء وتعويض عن ضرر -دفع املدعى عليها بفسخ العقد واملطالبة بأجرة -رد دعوى املدعي وإلزامه بدفع أجرة فترة بقاء السيارة بيده ورفع اسمه من القائمة بعدها.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"  ‫تاريخه‪1434/9/2 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                     ‫الص ِّك‪4311281 :‬‬\n                   ‫َر ْق ُم الدعوى‪33360874 :‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n            ‫‪ 35105065‬تاريخه‪1435/1/4 :‬هـ‬\n\n\n\n‫إجــارة ‪ -‬أيجــار منتهــي بالتملــك ‪ -‬مطالبــة بتســليم ســيارة بديلة ورفع‬\n‫اســم مــن القائمــة الســوداء وتعويــض عــن ضــرر ‪ -‬دفــع املدعــى عليهــا‬\n‫بفســخ العقــد واملطالبــة بأجــرة ‪ -‬رد دعــوى املدعــي وإلزامــه بدفــع أجــرة‬\n              ‫فتــرة بقــاء الســيارة بيــده ورفــع اســمه مــن القائمــة بعدهــا‪.‬‬\n\n\n\n\n                 ‫‪ .1‬قول اهلل تعالى‪ « :‬يا أيها الذين آمنوا أوفوا بالعقود »‪.‬‬\n‫‪ .2‬قول النبي صلى اهلل عليه وســلم‪« :‬املســلمون على شــروطهم»أخرجه‬\n                                                              ‫الترمذي وأبو داوود‪.‬‬\n‫‪ .3‬قــول النبــي صلــى اهلل عليــه وســلم‪ « :‬البينــة علــى املدعــي واليمــن‬\n‫علــى املدعــى عليــه» أخرجــه الترمــذي وقــال العمــل عنــد أهــل العلــم‬\n‫مــن أصحــاب النبــي صلــى اهلل عليــه وســلم وغيرهــم أن البينــة علــى‬\n                                          ‫املدعــي واليمــن علــى املدعــى عليــه‪.‬‬\n‫‪ .4‬قــال البهوتــي يف الــروض املربــع ‪« :‬وهــي أي اإلجــارة عقــد الزم مــن‬\n‫الطرفــن ألنهــا نــوع مــن البيــع فليــس ألحدهمــا فســخها لغيــر عيــب أو‬\n‫نحــوه ‪ ،‬فــإن آجــره شــيئا ومنعــه أي منــع املؤجــر املســتأجر الشــيء املؤجــر‬\n‫كل املــدة أو بعضهــا بــأن ســلمه العــن ‪ ،‬ثــم حولــه قبــل تقضــي املــدة فــا‬\n‫شــيء لــه مــن األجــرة ألنــه لــم يســلم لــه مــا تناولــه عقــد اإلجــارة ‪ ،‬فلــم‬\n‫يســتحق شــيئا ‪ ،‬وإن بــدأ اآلخــر أي املســتأجر فتحــول قبــل انقضائها أي‬\n\n                                                                                         ‫‪32‬‬\n\f     ‫انقضــاء مــدة اإلجــارة فعليــه جميــع األجــرة ألنهــا عقــد الزم ‪ ،‬فترتــب‬\n     ‫مقتضاهــا ‪ ،‬وهــو ملــك املؤجــر األجــر واملســتأجر املنافــع ‪ ...‬وإن وجــد‬\n     ‫املســتأجر العــن معيبــة أو حــدث بهــا عنــده عيــب ‪ -‬وهــو مــا يظهــر بــه‬\n     ‫تفــاوت األجــر‪ -‬فلــه الفســخ إن لــم يــزل بــا ضــرر يلحقــه وعليــه أجــرة‬\n     ‫مــا مضــى الســتيفائه املنفعــة فيــه ولــه اإلمضــاء مجانــا واخليــار علــى‬\n                                                                        ‫التراخــي»‪.‬‬\n\n\n\n\n     ‫أقــام املدعــى علــى الشــركة املدعــى عليهــا دعــوى يطالبهــا بتســليمه‬\n     ‫ســيارة بدليــه للســيارة التــي اشــتراها منهــا وتعرضــت حلــادث وقــام‬\n     ‫بتســليمها إلــى الشــركة وتعويضــه عــن اخلســائر التــي حلقــت بــه علــى‬\n     ‫حســب مــا تقــدره احملكمــة ودفعــت الشــركة بــأن العقــد املبــرم بينهمــا‬\n     ‫هــو عقــد إيجــار مــع وعــدة بهبــة وليــس عقــد بيــع وطلبــت إلــزام املدعــى‬\n     ‫بســداد باقــي املســتحق عليــه مــن قيمــة اإليجــار غيــر املدفــوع والشــرط‬\n     ‫اجلزائــي وبعــد النظــر قــررت احملكــة إلــزام املدعــى بســداد مبلــغ وقــدره‬\n     ‫ألفــان وخمســمائة واثنــان وســتون ريــا ًال وثمانــون هللــة قيمــة أجــرة‬\n     ‫مســتحقة وكذلــك مبلــغ ســتة عشــر ألف ـ ًا وثمامنائــة وأربعــة وعشــرون‬\n     ‫ألــف ريــال قيمــة شــرط جزائــي وألزمــت املدعــى عليهــا بعــد ســداد املبلــغ‬\n     ‫برفــع اســمه مــن شــركة ‪ ...‬وردت ماعــدا ذلــك مــن طلبــات وقــد اعتــرض‬\n     ‫املدعــى عليهــا علــى احلكــم‪ ،‬جــرى التصديــق مــن محكمــة االســتئناف‬\n\n\n\n\n‫‪33‬‬\n\f‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ........................‬القاضــي يف احملكمــة‬\n‫العامــة مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n‫رئيــس احملكمــة العامــة مبحافظــة جدة‪/‬املســاعد برقــم ‪33360874‬‬\n‫وتاريــخ ‪1433/05/25‬ه ـ املقيــدة باحملكمــة برقــم ‪33988853‬‬\n‫وتاريــخ ‪1433/05/25‬ه ـ ففــي يــوم الســبت املوافق‪1433/08/10‬ه ـ‬\n‫افتتحــت اجللســة الســاعة ‪ 02 : 30‬وفيهــا حضــر املدعــي ‪........................‬‬\n‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ......................‬وادعــى‬\n‫علــى احلاضــر معــه ‪ ......................‬ســعودي اجلنســية مبوجــب الســجل‬\n‫املدنــي رقــم ‪ ....................‬بصفتــه وكيــا عــن ‪ ........................‬ســعودي‬\n‫مبوجــب ســجل مدنــي رقــم ‪ ......................‬بوكالتــه عــن‪.....................‬‬\n‫اصالــة عــن نفســه وبصفتــه مديــر وشــريك يف شــركة ‪ ............‬مبوجــب‬\n‫قــرار الشــركاء املوثــق مــن كاتــب العــدل املكلــف بالغرفــه التجاريــة‬\n‫الصناعيــة بجــده برقــم ‪ 115‬صحيفــه رقــم ‪ 120‬مجلــد ‪ / 18‬ش ‪ /‬م‬\n‫يف ‪ 1429 / 02 / 06‬ه ـ واملوثــق عقــد تاسيســها لــدى كاتــب عــدل‬\n‫الغرفــه التجاريــة برقــم ‪ 181‬صحيفــه رقــم ‪ 183‬مجلــد ‪ / 10‬ش ‪ /‬م يف‬\n‫‪ 1428/ 02/03‬ه ـ والســجل التجــاري رقــم ‪ ............‬يف ‪1428/07/08‬هـ‬\n‫بالوكالــه رقــم ‪ 53832‬يف ‪ 1430 / 06 / 02‬جلــد ‪ 8471‬الصــادره مــن‬\n‫هــذه االداره وبصفتــه صاحــب مؤسســة ‪ ......................‬مبوجــب ســجل‬\n‫جتــاري رقــم ‪ 4030065137‬يف ‪1409/9/11‬ه ـ بالوكالــه رقــم ‪52749‬‬\n‫يف ‪ 1430 / 05 / 29‬ه ـ اجللــد ‪ 8460‬صــادره مــن هــذه االداره وبصفتــه‬\n‫صاحــب مؤسســة ‪ ...‬لنقــل احلجــاج فــرع ‪ ............................‬ســجل جتــاري‬\n\n                                                                                           ‫‪34‬‬\n\f     ‫رقــم ‪ ......................‬يف ‪ 1419 / 10 / 10‬ه ـ بالوكالــه رقــم ‪52735‬‬\n     ‫يف ‪1430 / 05 / 29‬ه ت اجللــد ‪ 8460‬الصــادره مــن هــذه االداره ‪،‬‬\n     ‫قائــا ‪ :‬لقــد قمــت بشــراء ســيارة مــن نــوع ‪ .......‬موديــل ‪2012‬م بنظــام‬\n     ‫التأجيــر املنتهــي بالتمليــك مببلــغ وقــدره مائــة وأربعــون الــف ريــال‬\n     ‫بأقســاط شــهري مببلــغ الفــان ومائــة ريــال ‪ ،‬وقــد وقــع حــادث ســير يف‬\n     ‫‪1432/10/11‬ه ـ ومت إدانــة الطــرف األخــر بنســبة ‪ ، %100‬وقــد ســلمت‬\n     ‫الســيارة للمدعــى عليهــا يف ‪1432/10/25‬ه ـ وحيــث أن العقــد ينــص‬\n     ‫علــى إعطائــي ســيارة بديلــة ولــم يتــم ذلــك ‪ ،‬وباعــت املدعــى عليهــا‬\n     ‫ســيارتي دون الرجــوع لــي ‪ ،‬وطالبتنــي املدعــى عليهــا بفــرق ســعر البيــع‬\n     ‫وقــدره خمســون ألــف ريــال ‪ ،‬وقــد تكبــدت مــن اخلســائر جــراء هــذا‬\n     ‫التصــرف‪ ،‬وحرمانــي مــن االســتفادة ســيارة بديلــة نتيجــة ذلــك احلــادث‪،‬‬\n     ‫وإدراج اســمي يف القائمــة الســوداء لــدى شــركة (‪ )...‬وتعطيــل جميــع‬\n     ‫مصاحلــي املاليــة ‪،‬ومنــذ ‪1432/10/25‬ه ـ وحتــى اليــوم وأنــا محــرم‬\n     ‫مــن التنقــل بســيارتي اخلاصــة ‪ ،‬واعتمــدت يف ذلــك علــى النقــل العــام‪،‬‬\n     ‫أطلــب إلــزام املدعــى عليهــا بإعطائــي ســيارة بديلــة ‪ ،‬وتعويضــي عــن‬\n     ‫خســائري بحســب مــا يــراه فضيلتكــم ‪ .‬هــذه دعــواي ‪ .‬وبســؤال املدعــي‬\n     ‫عــن العقــد املبــرم بــن الطرفــن وتقريــر احلــادث قــال ‪ :‬ليــس لــدي‬\n     ‫نســخة مــن العقــد ‪ ،‬واملدعــى عليهــا ممتنعــة مــن تســليمي نســخة منــه‬\n     ‫‪ ،‬وكل مــا يخــص احلــادث ســلمته للمدعــى عليهــا ‪ .‬وبعــرض ذلــك علــى‬\n     ‫املدعــى عليــه وكالــة قــال ‪ :‬أطلــب اإلمهــال للــرد ‪ .‬ثــم رفعــت اجللســة‬\n     ‫لذلــك ‪ .‬ويف يــوم االثنــن املوافــق ‪1433/09/18‬ه ـ افتتحــت اجللســة‬\n     ‫الســاعة ‪ 10 : 30‬وفيهــا حضــر املدعــي وحضــر ‪ .........‬ســعودي اجلنســية‬\n     ‫مبوجــب الســجل املدنــي رقــم ………………‪ ..‬بصفتــه وكيــا عــن‬\n\n\n‫‪35‬‬\n\f‫…………………‪ .‬سـع ــودي اجلنســية مبوج ــب السـج ــل املدنــي رق ــم‬\n‫‪ ....................‬بصفتــه وكيــا عــن ‪ ...........................‬بالوكالــة رقــم‬\n‫‪ 52749‬يف ‪1430 /5/ 29‬ه ـ جلــد ‪ 8460‬صــادرة مــن كتابــة عــدل‬\n‫الثانيــة شــمال محافظــة جــدة بصفتــه صاحــب مؤسســة ‪..................‬‬\n‫ســجل جتــاري رقــم ‪ ..............‬يف ‪1409/9/11‬ه ـ وبصفتــه وكيــا‬\n‫عــن ‪ .........................‬بالوكالــة رقــم ‪ 52735‬يف ‪1430/5/29‬ه ـ جلــد‬\n‫‪ 8460‬صــادرة مــن كتابــة عــدل الثانيــة شــمال محافظــة جــدة بصفتــه‬\n‫صاحــب مؤسســة‪ ................‬لنقــل احلجــاج فــرع مؤسســة ‪.........................‬‬\n‫ســجل جتــاري رقــم ‪.........................00‬يف ‪1419 / 10/10‬ه ـ وبصفتــه‬\n‫وكيــا عــن ‪ ...........................‬بالوكالــة رقــم ‪ 53832‬يف ‪1430 /6 /2‬‬\n‫ه ـ جلــد ‪ 8471‬صــادرة مــن كتابــة عــدل الثانيــة شــمال محافظــة جــدة‬\n‫بصفتــه مديــر وشــريك يف شــركة ‪ .....................‬ســجل جتــاري رقــم‬\n‫‪ ....................‬وتاريــخ ‪1428 /7/8‬ه ـ ‪ ،‬مبوجــب الوكالــة الصــادرة‬\n‫مــن كتابــة العــدل الثانيــة شــمال محافظــة جــدة برقــم ‪ 4590‬وتاريــخ‬\n‫‪1431/1/16‬ه ـ جلــد ‪ ، 9192‬وبســؤال املدعــى عليــه وكالــة عمــا طلــب‬\n‫الوكيــل الســابق اإلمهــال مــن أجلــه قــدم مذكــرة هــذا نصهــا ‪ :‬بــدأ‬\n‫املدعــي دعــواه بدايــة خاطئــة عندمــا قــال أنــه اشــترى مــن املدعــى عليهــا‬\n‫ســيارة بايجــار منتهــي بالتمليــك ‪ .‬واحلقيقــة أنــه لــم يشــتر وإمنــا اســتأجر‬\n‫الســيارة مبوجــب عقــد تأجيــر مــع الوعــد بالهبــة ‪ .‬فهــو لــم يتملــك الســيارة‬\n‫وهــو مجــرد مســتأجر ‪ .‬وأرفــق صــورة العقــد احملــرر بــن الطرفــن بتاريخ‬\n‫‪2011/4/17‬م ‪(.‬صــورة عقــد تأجيــر مــع الوعــد بالهبــة (وقــد تســلم‬\n‫املدعــي الســيارة املؤجــرة بتاريــخ ‪2011/4/20‬م وظــل ينتفــع بهــا حتــى‬\n‫ســحبت املدعــى عليهــا الســيارة وفســخت العقــد بعــد اســتعمال مدتــه‬\n\n\n                                                                                         ‫‪36‬‬\n\f     ‫(‪ )6‬أشــهر‪ ،‬وســبب الفســخ أن املدعــي أثنــاء حيازتــه للســيارة توقــف عــن‬\n     ‫دفــع أقســاط األجــرة املتفــق عليهــا يف العقــد ‪ .‬ولــم يســدد ســوى أربعــة‬\n     ‫أقســاط وجــزء مــن القســط اخلامــس مبجمــوع ‪ 14.710‬ريــال وتوقــف‬\n     ‫عــن الدفــع بتاريــخ ‪2011/9/1‬م ‪ .‬وتطبيقـ ًا لنــص املــادة ‪ 1/15‬مــن العقــد‬\n     ‫التــي تعــدد اإلخــاالت التــي جتيــز للمؤجــر فســخ العقــد ومنهــا عــدم‬\n     ‫ســداد أقســاط األجــرة الشــهرية يف مواعيدهــا ‪ ،‬قامــت املدعــى عليهــا‬\n     ‫بســحب الســيارة وفســخ العقــد بتاريــخ ‪2011/12/29‬م وبذلــك يكــون‬\n     ‫العقــد قــد انتهــى بالفســخ وفقـ ًا حلكــم املــادة ‪ 16‬مــن العقــد ‪ .‬وال معنــى‬\n     ‫ملــا جــاء بالئحــة الدعــوى مــن أن العقــد ينــص علــى اعطــاء ســيارة بديلــة‬\n     ‫‪ ،‬كمــا أنــه ال معنــى ملــا جــاء بالالئحــة مــن أن الشــركة ضربــت بذلــك‬\n     ‫عــرض احلائــط وباعــت ســيارة املدعــي دون الرجــوع إليــه ‪ ،‬فاملدعــي لــم‬\n     ‫يتملك الســيارة ولم يكن إال مســتأجر ًا لها ‪ .‬وال ســند من شــرع أو نظام‬\n     ‫أو عقــد ملــا يطلبــه املدعــي يف الئحــة دعــواه مــن اعطائــه ســيارة بديلــة‬\n     ‫وتعويــض اخلســائر املترتبــة علــى ذلــك ‪ .‬لهــذا األســباب تطلــب موكلتــي‬\n     ‫صــرف النظــر عــن دعــوى املدعــي ‪ .‬ووفقـ ًا ملــا تنــص عليــه املــادة ‪ 14‬مــن‬\n     ‫العقــد ‪ ،‬تطلــب الشــركة املدعيــة احلكــم بإلــزام املدعــي بــأن يدفــع‬\n     ‫لهــا املبالــغ اآلتيــة ‪ :‬أجــرة الســنة األولــى ‪ 50.472‬ريــال (مــادة ‪-3/14‬‬\n     ‫أ مــن العقــد) قيمــة (‪ )8‬أقســاط شــهرية ‪ 8‬؟ ‪ 16.824 = 2.103‬ريــال‬\n     ‫(مــادة ‪-3/14‬ج ـ مــن العقــد) املجمــوع ‪ 67.296‬ريــال ‪،‬يخصــم مــا ســبق‬\n     ‫ســداده مــن أقســاط ‪ 14.710‬ريــال ‪ ،‬صــايف املســتحق يف ذمــة املدعــي‬\n     ‫‪52.586‬ريــال ‪ ،‬ويثبــت العقــد املرفــق صورتــه أن املدعــي تســلم نســخة‬\n     ‫عنــد التوقيــع فليــس صحيح ـ ًا أن املدعــى عليهــا ممتنعــة عــن تســليمه‬\n     ‫صــورة العقــد ‪ .‬وتطلــب الشــركة املدعــى عليهــا احلكــم بإلــزام املدعــى‬\n\n\n‫‪37‬‬\n\f‫بــأن يدفــع لهــا مبلــغ ‪52.586‬ريــال املســتحق يف ذمتــه وفق ـ ًا ألحــكام‬\n‫العقــد وصــرف النظــر عــن دعــوى املدعــي لعــدم صحتهــا ‪ .‬وبعــرض ذلــك‬\n‫علــى املدعــي قــال ‪ :‬أطلــب اإلمهــال للــرد ‪ .‬ثــم رفعــت اجللســة لذلــك ‪ .‬ويف‬\n‫يــوم االثنــن املوافــق ‪1433/10/16‬ه ـ افتتحــت اجللســة الســاعة ‪02 : 00‬‬\n‫وفيهــا حضــر الطرفــان ‪ ،‬وقــدم املدعــي مذكــرة مكونــة مــن ورقتــن‬\n‫وعــدد ثمــان مرفقــات ‪ ،‬وتتضمــن أن الســيارة املســتأجرة محــل الدعــوى‬\n‫مأمــن عليهــا تأمينــا شــامال واحلــادث وقــع يف ‪1432/11/10‬ه ـ بنســبة‬\n‫خطــأ ‪ %100‬علــى الطــرف اآلخــر ‪ ،‬وتســلمت املدعــى عليهــا الســيارة‬\n‫يف ‪1432/11/24‬ه ـ بقصــد إصالحهــا علــى التأمــن ‪ ،‬وقامــت املدعــى‬\n‫عليهــا ببيــع الســيارة يف ‪1433/2/4‬ه ـ بعــد فســخ العقــد مــن طرفهــم ‪،‬‬\n‫مت إدراج اســم املدعــي يف القائمــة الســوداء لــدى شــركة ســمه ‪ ،‬وأنــه لــم‬\n‫يتأخــر يف ســداد األجــرة قبــل احلــادث‪ ،‬وأن آخــر أجرة دفعهــا قبل احلادث‬\n‫بشــهر ‪ ،‬ويطلــب تعويضــه عــن الضــرر املــادي واملعنــوي الــذي وقــع عليــه‬\n‫جــراء بيــع الســيارة وإدراج اســمه يف شــركة ســمه ‪ ،‬وبعرضهــا علــى‬\n‫املدعــى عليــه وكالــة قــال ‪ :‬أطلــب اإلمهــال للــرد يف اجللســة القادمــة ‪ .‬ثــم‬\n‫رفعــت اجللســة لذلــك ‪ .‬ويف يوم األربعــاء املوافق‪1433/11/10‬هـ افتتحت‬\n‫اجللســة الســاعة ‪ 10 : 00‬وفيهــا حضــر الطرفــان ‪ ،‬وقــدم املدعــى عليــه‬\n                                                 ‫وكالــة مذكــرة هــذا نصهــا ‪:‬‬\n‫‪ .1‬ال عالقــة للحــادث الــذي وقــع للســيارة ونســبة اخلطــأ بفســخ العقــد‬\n‫وســحب الســيارة ‪ ،‬فقــد ادخلــت الســيارة الورشــة بعــد احلــادث ومت‬\n‫اصالحهــا وانتهــى االصــاح علــى حســاب التأمــن واتصلــت الورشــة‬\n‫باملدعــي وأشــعرته بــأن الســيارة معــدة الســتالمها وطلبــت حضــوره‬\n                                        ‫الســتالمها ولكنــه رفــض االســتالم ‪.‬‬\n\n\n                                                                                       ‫‪38‬‬\n\f     ‫‪ .2‬كان آخــر قســط ســدده املســتأجر هــو القســط رقــم (‪ )4‬اســتحقاق‬\n     ‫‪2011/8/1‬م ومبلــغ ‪101‬ريــال جــزء مــن القســط رقــم (‪ )5‬اســتحقاق‬\n                  ‫‪2011/9/1‬م ‪ ،‬وكان هــذا الســداد بتاريــخ ‪2011/9/26‬م‬\n     ‫‪ .3‬وتوقــف املدعــي عــن ســداد األقســاط بعــد ذلــك ‪ ،‬وعندمــا وقــع‬\n     ‫احلــادث للســيارة وادخلهــا الصيانــة ومت اصالحهــا وأشــعرته الصيانــة‬\n     ‫ورفــض اســتالمها ‪ ،‬قامــت شــركة أقســاط عــن طريــق مندوبهــا‬\n     ‫‪ .................‬باالتصــال بــه حلثــه علــى ســداد األقســاط واســتالم الســيارة‬\n     ‫ولكنــه رفــض اســتالم الســيارة أو ســداد األقســاط وكانــت اجابتــه‬\n     ‫«ســيارتكم يف الورشــة وال أريدهــا ‪ -‬ســيارتكم عندكــم» وأرفــق‬\n     ‫مــع هــذا صــورة مــن بطاقــة املتابعــة وصــورة مــن مذكــرة نائــب مديــر‬\n     ‫التحصيــل املقدمــة إلــى نائــب املديــر العــام للشــركة )مســتند رقــم ‪-1‬‬\n     ‫صــورة بطاقــة متابعــة) (مســتند رقــم ‪ -2‬صــورة مذكــرة نائــب مديــر‬\n                                                                          ‫التحصيــل)‪.‬‬\n     ‫ا‬ ‫‪ .4‬وملــا كان التأخيــر يف دفــع األقســاط قــد بلــغ خمســة شــهور ‪ ،‬فضـ ً‬\n     ‫عــن افصــاح املدعــي بأنــه ال يريــد اســتالم الســيارة فقــد اســتعملت‬\n     ‫املدعــى عليهــا حقهــا يف فســخ العقــد وفق ـ ًا ملــا تقضــي بــه املــادة ‪2/14‬‬\n     ‫مــن العقــد ‪ ،‬مــن حــق الشــركة يف فســخ العقــد إذا تأخــر املســتأجر عــن‬\n     ‫ســداد أي قســط ايجــاري مســتحق مــن أقســاط االيجــار ملــدة ‪ 60‬يوم ـ ًا‬\n     ‫مــن تاريــخ االســتحقاق ‪ ،‬واملســتأجر لــم يكــن فقــط متأخــر ًا يف ســداد‬\n       ‫األقســاط ولكنــه أفصــح عــن أنــه اليريــد الســيارة ورفــض اســتالمها‪.‬‬\n     ‫‪ .5‬مــا ذهــب إليــه املدعــي مــن «أن العقــد هــو بيعتــن يف بيعــه وهــو يعــارض‬\n     ‫قواعــد الشــرع ومــا ذكــره مــن أن ســماحة مفتــي اململكــة وفضيلــة‬\n     ‫الشــيخ‪ /‬ابــن منيــع قــد افتيــا بذلــك» ‪ ،‬ال يخلــو مــن جــرأة علــى أحــكام‬\n\n\n‫‪39‬‬\n\f‫وقواعــد فقهيــة ينبغــي أن تتــرك ملــن تؤهلــه امكانياتــه للخــوض فيهــا ‪.‬‬\n‫وقــد أرفــق املدعــي مبذكرتــه صــورة بيــان مــن اللجنــة الدائمــة للبحــوث‬\n‫العلميــة واالفتــاء بشــأن االيجــار املنتهــي بالتمليــك ‪ ،‬كمــا أرفــق صــورة‬\n‫فتــوى صــادرة عــن مركــز الفتــوى بالقــرار رقــم ‪ )4/12( 110‬بشــان‬\n‫موضــوع االيجــار املنتهــي بالتمليــك وهــي التــي ميــزت بــن صــور جائــزة‬\n‫وصــور ممنوعــة لاليجــار املنتهــي بالتمليــك ‪ .‬ولــو أنصــف املدعــي وحــاول‬\n‫تفهــم الفتــوى ألدرك أن العقــد الــذي يطعــن ببطالنــه يدخــل يف الصــورة‬\n‫اجلائــزة ‪ .‬وليــس أدل علــى ذلــك مــن أن منــوذج العقــد الــذي يطعــن ببطالنــه‬\n‫معتمــد مــن قبــل الهيئــة الشــرعية املكونــة مــن كل مــن العلمــاء االجــاء‬\n        ‫‪:‬فضيلــة الشــيخ عبــد اهلل بــن منيــع فضيلــة الشــيخ يوســف الفــراج‬\n‫مــن ذلــك يتبــن أنــه ال أســاس لدعــوى املدعــي وال أحقيــة لــه يف شــيء‬\n‫ممــا يطلبــه ‪ .‬فاملدعــى عليهــا فســخت العقــد وفق ـ ًا ألحكامــه لتأخــر‬\n‫املدعــي يف ســداد األقســاط وافصاحــه عــن أنــه ال يريــد الســيارة ‪ ،‬وبعــد‬\n‫الفســخ واســترداد املدعــى عليهــا حيــازة الســيارة فمــن حقهــا أن تبيعهــا‬\n‫وتتصــرف فيهــا تصــرف املالــك يف ملكــه ‪ ،‬واملدعــي لــم يكــن مالــك ًا‬\n                                                                             ‫للســيارة ‪.‬‬\n‫ليــس ذلــك فقــط ‪ ،‬بــل أن املدعــى عليهــا تطلــب احلكــم بإلــزام املدعــي‬\n                 ‫باملبالــغ اآلتيــة وفقـ ًا ملــا تنــص عليــه املــادة ‪ 14‬مــن العقــد ‪:‬‬\n‫أجــرة الســنة األولــى ‪ 50.472‬ريــال (مــادة ‪ -3/14‬أ مــن العقــد) قيمــة‬\n‫(‪ )8‬أقســاط شــهرية ‪ 16.824 = 2.103 - 8‬ريــال (مــادة ‪-3/14‬ج ـ مــن‬\n‫العقــد ) املجمــوع ‪ 7,296‬ريــال يخصــم مــا ســبق ســداده مــن أقســاط‬\n‫‪8,513‬ريــال صــايف املســتحق يف ذمــة املدعــي‪ 58.783‬ريــال وقــد ورد‬\n‫خطــأ يف مذكرتنــا رقــم ‪ 11235‬وتاريــخ ‪1433/9/18‬ه ـ أن مــا ســبق‬\n\n\n                                                                                             ‫‪40‬‬\n\f     ‫ســداده ‪14.710‬ريــال والصحيــح ‪ 8.513‬ريــال كمــا هــو مذكــور أعاله‬\n     ‫‪ .‬وتطلــب الشــركة املدعــى عليهــا صــرف النظــر عــن دعــوى املدعــي‬\n     ‫لعــدم صحتهــا ‪ ،‬واحلكــم لهــا مببلــغ ‪ 58.783‬ريــال املســتحق يف ذمتــه‬\n     ‫وفق ـ ًا ألحــكام العقــد ‪ .‬وبعرضــه علــى املدعــي قــال ‪ :‬أطلــب اإلمهــال‬\n     ‫للــرد ‪ .‬ثــم رفعــت اجللســة لذلــك ‪ .‬ويف يوم الســبت املوافق‪1434/07/22‬هـ‬\n     ‫افتتحــت اجللســة الســاعة ‪10 : 00‬وفيهــا حضــر املدعــي ‪...................‬‬\n     ‫وحضــر ‪ ...................‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n     ‫‪ ....................‬بصفتــه وكيــا عــن ‪ ....................‬ســعودي اجلنســية‬\n     ‫ا عــن‬   ‫مبوجــب الســجل املدنــي رقــم ‪ ...................‬وبصفتــه وكي ـ ً‬\n     ‫‪ ...................‬بشــخصه وبصفتــه صاحــب مؤسســة ‪ ........................‬ســجل‬\n     ‫جتــاري رقــم ‪ 4030065137‬يف ‪1409/9/11‬ه ـ بالوكالــة رقــم ‪52749‬‬\n     ‫يف ‪1430/5/29‬ه ـ جلــد ‪ 8460‬الصــادرة عــن كتابــة عــدل جدة الثانية‪،‬‬\n     ‫وبصفتــه صاحــب مؤسســة ‪ ...‬لنقــل احلجــاج فــرع مؤسســة ‪.....................‬‬\n     ‫ســجل جتــاري رقــم ‪ ....................‬يف ‪1419/10/10‬ه ـ بالوكالــة رقــم‬\n     ‫‪ 52735‬يف ‪1430/5/29‬ه ـ جلــد ‪ 8460‬الصــادرة عــن كتابــة عــدل جدة‬\n     ‫الثانيــة ‪ ،‬وبصفــة موكلــي مديــر وشــريك يف شــركة ‪............................‬‬\n     ‫‪.....‬مبوجــب قــرار الشــركاء املوثــق مــن كاتــب العــدل املكلــف بالعمــل‬\n     ‫لــدى الغرفــة التجاريــة الصناعيــة مبحافظــة جــدة برقــم ‪ 181‬صحيفــة‬\n     ‫رقــم ‪ 183‬مجلــد ‪/10‬ش‪/‬م يف ‪1428/2/3‬ه ـ والســجل التجــاري رقــم‬\n     ‫‪ 4030171226‬يف ‪1428/7/8‬ه ـ بالوكالــة رقــم ‪ 34182524‬وتاريــخ‬\n     ‫‪1434/4/8‬ه ـ الصــادرة مــن كاتــب العــدل املكلــف بالغرفــة التجاريــة‬\n     ‫الصناعيــة مبحافظــة جــدة ‪،‬وبســؤال املدعــي عمــا طلــب اإلمهــال‬\n     ‫مــن أجلــه قــدم مذكــرة هــذا نصهــا ‪ :‬تأسيســا علــى مــا ســبق ذكــره‬\n\n\n‫‪41‬‬\n\f‫مبذكرتــي احملــررة يف ‪1433/10/16‬ه ـ وبنــاءا علــى مــا ورد مبذكــرة‬\n‫اجلهــة املدعــى عليهــا املقدمــة بجلســة ‪1433/11/10‬ه ــاقدم لفضيلتكم‬\n                                                                           ‫مــا يلــي‪:‬‬\n‫‪ .1‬ذكــر ممثــل اجلهــة املدعــى عليهــا بأننــي قــد رفضــت اســتالم ســيارتي‬\n         ‫بعــد اصالحهــا وهــذا قــول مرســل ال صحــة لــه وبــا دليــل او ســند‪.‬‬\n‫‪ .2‬ذكــروا اننــي متأخــر يف دفــع االســقاط ممــا اســتدعى اتخــاذ ذلــك‬\n‫ذريعــة املصــادرة والبيــع وهــذا ليــس بصحيــح مطلقــا فعنــد ادخــال‬\n‫ســيارتي ورشــة اجلهــة املدعــى عليهــا لــم يكــن علــى أي قســط متأخــر بــل‬\n‫مســتحق علــى قســط فقــط وليــس هنــاك تأخيــر كمــا ذكــر وممكــن‬\n                                                                ‫الرجــوع لتواريــخ‪.‬‬\n‫‪ .3‬اللجــوء الــى مصــادرة الســيارة وبالتالــي بيعهــا دون اتبــاع اجــراءات‬\n‫نظاميــة بتوجيــه انــذارات وبالرفــع للجهــات احلكوميــة املختصــة او‬\n‫توجيــه انــذارات محــررة لــي بالتاريــخ ومســببه فــان فعــل ذلــك تســلطا‬\n         ‫وتطبيــق للنظــام تعســفيا وباســتخدام وســائل اجلبــر واإلكــراه‪.‬‬\n‫‪ .4‬يــا صاحــب الفضيلــة كيــف تصــادر ســيارتي وأطالــب بتســديد مبلــغ‬\n‫‪ 58783‬ريــال ثمانيــة وخمســون الــف وســبعمائة وثالثــة وثمانــون ريــال ‪.‬‬\n‫أليــس ذلــك يــدل علــى الغــل وأكل االمــوال بالباطــل‪ .‬أليــس ذلــك خــارج‬\n    ‫عــن نطــاق املعقــول وأي إجــراءات وتخطــيء املنطــق وقواعــد التعامــل‬\n‫‪ .5‬بالعــودة ياصاحــب الفضيلــة ملــا ذكــره املدعــى عليــه بأنــه يطالــب‬\n‫مببالــغ تفاوتــت واختلفــت ثــاث مــرات بعــدة ارقــام مختلفــة ممــا يــدل‬\n                  ‫ذلــك علــى انــه يريــد الكيــد وفيــه فجــور يف اخلصومــه‪.‬‬\n‫عليــه اطلــب‪ :‬أو ًال ‪ :‬تعويضــي عــن ســيارتي التــي مت التصــرف فيهــا‬\n‫دون اجــراءات رســمية نظاميــة مبقــدار الضــرر الواقــع علــي مــن تاريــخ‬\n\n\n                                                                                         ‫‪42‬‬\n\f     ‫الســحب مــن الورشــة حتــى تاريــخ الفصــل بالدعــوى بحكــم مكتســب‬\n                             ‫القطعيــة مبقــدار ايجــار املثــل االضطــراري لذلــك‬\n     ‫ثانيــا ‪ :‬اعطائــي ســيارة بديلــه مبوديــل حديــث واحتســاب الدفعــات‬\n     ‫املقدمــة لــي ومواصلــة الدفــع والســداد حســب انظمــة البيــع املنتهــي‬\n                                                                              ‫بالتملــك ‪.‬‬\n     ‫ثالث ـ ًا ‪ :‬صــرف النظــر عــن دعواهــم يف دفــع املبلــغ الــذي يطالبــون بــه‬\n     ‫مطالبــه بــدون وجــه حــق وليــس لهــا اســاس إذ ال يجــوز املطالبــة بشــيء‬\n     ‫بــدون مقابــل ‪ .‬وبعــرض ذلــك علــى املدعــى عليــه وكالــة قــال ‪ :‬اطلــب‬\n     ‫اإلمهــال للــرد ‪ .‬ثــم رفعــت اجللســة لذلــك ‪ .‬ويف يــوم االثنــن املوافــق‬\n     ‫‪1434/08/08‬ه ـ افتتحــت اجللســة الســاعة ‪ 02 : 00‬حضــر املدعــي‬\n     ‫‪..................‬وحضــر املدعــى عليــه وكالــة ‪ ، ........................‬وبســؤال‬\n     ‫املدعــى عليــه وكالــة عمــا طلــب اإلمهــال مــن اجلــة قــدم مذكــرة‬\n                                                                  ‫جوابيــة هــذا نصهــا ‪:‬‬\n     ‫‪-1‬جــاء مبذكــرة املدعــي أن ماذكــر عــن رفضــه اســتالم الســيارة بعــد‬\n     ‫اصالحهــا هــو قــول مرســل ال صحــة لــه وبــا دليــل أو ســند‪ ،‬ويتجاهــل‬\n     ‫اننــا قــد ارفقنــا مبذكرتنــا مســتندين يثبتــان هــذه الواقعــة ‪ ،‬ه ــما صورة‬\n     ‫بطاقــة املتابعــة وصــورة مذكــرة نائــب مديــر التحصيــل ‪ ،‬وأضيــف هنــا‬\n     ‫ملزيــد مــن ادلــة االثبــات صــورة رســالة الكترونيــة مؤرخــة ‪2012/1/23‬‬\n     ‫مــن مركــز الصيانــة الــى مديــر التحصيــل بشــركة اقســاط تقــول‬\n     ‫بحصــر النــص « ان الســيارة جاهــزة مــن تاريــخ ‪ 2011/12/29‬ومت‬\n     ‫االتصــال علــى العميــل وإبالغــه أن الســيارة جاهــزة للتســليم وإلــى اآلن‬\n     ‫لــم يأتــي العميــل» فــا معنــى ملــا يقولــه املدعــى مــن أن رفضــه اســتالم‬\n                                    ‫الســيارة بعــد اصالحهــا ال صحــة لــه وال دليــل‪.‬‬\n\n\n‫‪43‬‬\n\f‫‪-2‬ان موضــوع دفــع األقســاط يف موعدهــا او تأخيرهــا ال يصلــح‬\n‫للجــدل فهــذه أرقــام وتواريــخ وليــس أصــدق مــن االرقــام يف الداللــة علــى‬\n‫الواقــع‪ ،‬وكل مــا جــاء مبذكرتنــا رقــم ‪ 11410‬وتاريــخ ‪1433/11/10‬‬\n‫عــن مدفوعــات املدعــي مــن االقســاط وتواريخهــا صحيــح ‪ ،‬ويتجاهــل‬\n‫املدعــي ان فســخ العقــد وســحب الســيارة مــن الورشــة وبيعهــا لــم يتــم‬\n‫عنــد ادخــال الســيارة الــى الورشــة يف ‪ ، 2011/10/22‬ولكــن بعــد أن‬\n‫انتهــى اصالحهــا يف ‪ 2011/12/29‬وبعــد أنطلــب مــن املدعــي اســتالمها‬\n‫وبعــد أن رفــض اســتالمها وبعــد أن رفــض ســداد االقســاط ‪،‬واجابتــه‬\n‫بــأن «ســيارتكم يف الورشــة وال اريدهــا ؟ ســيارتكم عندكــم « ولــم‬\n‫تبــع الســيارة إال بتاريــخ ‪ 2012/1/29‬وكانــت االقســاط املتأخــرة‬\n                                                               ‫خمســة أقســاط‪.‬‬\n‫‪ -3‬ال معنــى ملــا جــاء مبذكــرة املدعــي مــن أن مصــادرة الســيارة وبيعهــا‬\n‫مت دون اتبــاع اجــراءات نظاميــة وتوجيــه انــذارات والرفــع للجهــات‬\n‫احلكوميــة املختصــة ‪ ،‬النــه يتجاهــل أن العالقــة بــن الطرفني يحكمها‬\n‫وينظمهــا العقــد احملــرر بينهمــا ‪ ،‬وهــو عقــد ايجــار ملتخــرج بــه الســيارة‬\n‫عــن ملــك شــركة أقســاط حتــى يتكلــم املدعــي عــن مصادرتهــا ‪،‬‬\n‫كمــا يتجاهــل املدعــي أن العقــد ينــص يف مادتــه ‪-3/14‬أ علــى التــزام‬\n‫املســتأجر بســداد إيجــارات الســنة االولــى والســنوات املســتحقة عليــه‬\n‫بعدهــا حتــى تاريــخ التســليم الفعلــي للســيارة ‪ ،‬كمــا ينــص يف مادتــه‬\n‫‪-3/14‬ج ـ علــى التزامــه بــأن يســدد ثمانيــة أقســاط إيجاريــة ‪ ،‬وهــذا هــو‬\n    ‫مــا تطلــب الشــركة املدعــى عليهــا احلكــم بإلــزام املدعــي بســداده‪.‬‬\n‫‪ -4‬ان تصحيــح املدعــى عليهــا خلطــأ وقــع يف مبلــغ تطالــب بــه ال يــدل‬\n‫‪-‬كمــا ذهــب املدعــي ‪ -‬علــى أنهــا « تريــد الكيــد « وليــس فيــه « فجــور‬\n\n\n                                                                                    ‫‪44‬‬\n\f     ‫يف اخلصومــة» وهــي االوصــاف التــي لــم يجــد املدعــي حرجـ ًا يف نســبتها‬\n            ‫إلينــا ‪ ،‬وهــو مــا نضــرب الصفــح عنــه ‪ ،‬فغيرنــا مــن يوصــف بذلــك‪.‬‬\n     ‫وأخيــر ًا فــان طلــب املدعــي تعويضــه واعطائــه ســيارة بديلــة ال يســتند الــى‬\n     ‫أي اســاس شــرعيأ ونظامــي أو عقــدي ‪ ،‬فاملدعــى عليهــا فســخت العقــد‬\n     ‫وفقـ ًا ألحكامــه والســيارة لــم تكــن مملوكــة للمدعــي ‪ ،‬كمــا أن مــا‬\n     ‫تطلــب املدعــى عليهــا الــزام املدعــي بدفعــه لهــا هــو تطبيــق ألحــكام‬\n                                                                                 ‫العقــد‪.‬‬\n     ‫وتطلــب الشــركة املدعــى عليهــا صــرف النظــر عــن دعــوى املدعــي لعــدم‬\n     ‫صحتهــا واحلكــم لهــا مببلــغ ‪ 58.783‬ريــال املســتحق يف ذمتــه وفق ـ ًا‬\n     ‫ألحــكام العقــد ‪ .‬وبعــرض ذلــك علــى املدعــي قــال ‪ :‬أكتفــي مبــا قدمــت‬\n     ‫‪ .‬وبعــرض ذلــك علــى املدعــى عليــه وكالــة قــال‪ :‬أكتفــي مبــا قدمــت ‪.‬‬\n     ‫وبعــد التأمــل واالطــاع علــى أوراق املعاملــة قــررت طلــب ‪...............‬‬\n     ‫املوظــف بقســم املتابعــة لــدى املدعــى عليهــا فوعــد املدعــى عليــه وكالــة‬\n     ‫بإحضــاره يف اجللســة القادمــة إن كان ال يــزال علــى رأس العمــل ‪ .‬ثــم‬\n     ‫رفعــت اجللســة لذلــك ‪ .‬ويف يــوم األربعــاء املوافــق ‪1434/8/24‬ه ـ افتتحت‬\n     ‫اجللســة الســاعة ‪ 08 : 00‬وفيهــا حضــر املدعــي ‪ .....................‬وحضــر‬\n     ‫املدعــى عليــه وكالــة ‪ ، .............................‬وبســؤال املدعــى عليهوكالة‬\n     ‫عمــا طلــب الوكيــل الســابق بخصــوص حضــور موظــف قســم املتابعــة ‪...‬‬\n     ‫قــال ‪ :‬إن ‪ .....................‬قــد تــرك العمــل مبوجــب إفــادة موكلتــي‬\n     ‫بخطابهــا املــؤرخ يف ‪1434/8/21‬ه ـ ‪،‬وقــد أحضــرت معــي هــذا اليــوم‬\n     ‫مديــر قســم املتابعــة ‪ ..............‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n     ‫رقــم ‪ .................‬ليحــل محلــه ‪ .‬فحضــر ‪..............................‬ســعودي‬\n     ‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ، ....................‬وقــرر قائــا ‪:‬‬\n\n\n‫‪45‬‬\n\f‫بصفتــي مديــر قســم املتابعــة يف شــركة ‪ .................. .............‬فقــد متــت‬\n‫مخاطبــة املدعــي الســتالم الســيارة بعــد إصالحهــا مــن قبــل الورشــة بعــد‬\n‫أن وقــع عليهــا حــادث ســير ‪ ،‬إال أنــه رفــض االســتالم بنــاء علــى إفــادة‬\n‫املوظــف لدينــا ســابقا ‪ . ................‬وبعرضــه علــى املدعــي قــال ‪ :‬بــل‬\n‫الصحيــح أننــي لــم أمتنــع عــن اســتالم الســيارة ‪ ،‬وقــد راجعــت الورشــة‬\n‫مرتــن ‪ ،‬األولــى بعــد شــهر وعشــرة أيــام ‪ ،‬والثانيــة بعــد ثالثــة أســابيع‬\n‫مــن املراجعــة األولــى ‪ ،‬وأفادونــي بــأن الســيارة لــم تنتهــي بعــد ‪ .‬وبعــرض‬\n‫ذلــك علــى املدعــى عليــه وكالــة قــال ‪ :‬لقــد أدخلــت الســيارة للورشــة يف‬\n‫‪2011/10/22‬م وانتهــى إصالحهــا يف ‪2011/12/29‬م ‪ ،‬وبعــد ذلــك مت‬\n‫االتصــال علــى املدعــي الســتالم الســيارة ولكنــه رفــض ‪ ،‬وعليــه فتــم‬\n‫اســتخدام حق موكلتي فيفســخ عقد اإليجار ومت التصرف يف الســيارة‬\n‫بالبيــع وهــي ملــك ملوكلتــي يف ‪2012/1/29‬م ‪،‬والــذي يثبــت رفــض‬\n‫املدعــي الســتالم الســيارة هــو كــرت املتابعــة واملعــد مــن قبــل قســم‬\n‫املتابعــة والتحصيــل مبعرفــة املوظــف ‪ ، ................‬وكذلــك إفــادة‬\n‫املســؤول يف الورشــة ‪ ...............‬لقســم املتابعــة برســالة بالبريــد‬\n‫االلكترونــي موجهــة ل‪ ........................‬بــأن املدعــي يرفــض اســتالم‬\n‫الســيارة ‪ .‬وبعــرض ذلــك علــى املدعــي قــال ‪ :‬ليــس لــدي إضافــة ‪ .‬وبســؤال‬\n‫الطرفــن هــل لديكمــا مــا تضيفانــه قــاال ‪ :‬ال ‪ .‬لــذا فقــد قــررت قفــل‬\n‫بــاب املرافعــة بنــاء علــى املــادة ‪ 66‬مــن نظــام املرافعــات الشــرعية ‪ .‬ثــم‬\n‫رفعــت اجللســة للتأمــل ‪ .‬ويف يــوم االثنــن املوافــق ‪1434/08/29‬ه ـ‬\n‫افتتحــت اجللســة الســاعة ‪ 08 : 15‬وفيهــا حضــر املدعــي ‪....................‬‬\n‫وحضــر املدعــى عليــه وكالــة ‪، ....................‬وبعــد التأمــل ‪ ،‬قــررت‬\n‫ســؤال املدعــي عــن األقســاط اإليجاريــة التــي قــام بدفعهــا للشــركة‬\n\n\n                                                                                         ‫‪46‬‬\n\f     ‫املدعــى عليهــا قــال ‪ :‬ال أذكرهــا بالتحديــد ‪ ،‬وال أحتفــظ بشــيء يفيــد‬\n     ‫ذلــك ‪ .‬فطلبــت مــن املدعــى عليــه وكالــة إحضــار كشــف حســاب‬\n     ‫للعميــل يفيــد مبــا مت دفعــه مــن أقســاط إيجاريــة ‪،‬وإحضــار احملصــل أو‬\n     ‫احملاســب املســؤول عــن ذلــك يف اجللســة القادمــة وبرفقــه خطــاب مــن‬\n     ‫الشــركة موكلتــه يفيــد بأنــه يعمــل لديهــا بالصفــة املذكــورة أعــاه‪،‬‬\n     ‫فوعــد بذلــك يف اجللســة القادمــة ‪ .‬ثــم رفعــت اجللســة لذلــك ‪ .‬ويف يــوم‬\n     ‫األربعــاء املوافــق ‪1434/09/02‬ه ــافتتحت اجللســة الســاعة ‪10 : 30‬‬\n     ‫وفيهــا حضــر املدعــي ‪ ،...............‬وحضــر املدعــى عليــه وكالــة‬\n     ‫‪ ، .......................‬وبســؤال املدعــى عليــه وكالــة عمــا طلــب اإلمهــال مــن‬\n     ‫أجلــه أبــرز خطابــا مــن الشــركة املدعــى عليهــا وعلــى مطبوعــات‬\n     ‫شــركة ‪ ..........................‬مــؤرخ يف ‪1434/8/29‬ه ـ بخصــوص كشــف‬\n     ‫حســاب املدعــي يف عقــد الســيارة محــل الدعــوى واملتضمــن أن املدعــي‬\n     ‫ســدد أربعــة أقســاط علــى النحــو التالــي ‪ :‬األول مبلغــا قــدره ألفــان وثالثــة‬\n     ‫عشــر ريــاال بالســند رقــم ‪ 216159‬وتاريــخ ‪2011/4/23‬م ‪،‬والثانــي‬\n     ‫مبلغــا قــدره ألفــان ومائــة وعشــرة ريــاالت بالســند رقــم ‪ 76792‬وتاريــخ‬\n     ‫‪2011/6/30‬م ‪ ،‬والثالــث مبلغــا قــدره ألفــان ومائــة ريــال بالســند رقــم‬\n     ‫‪ 76793‬وتاريــخ ‪2011/8/27‬م ‪ ،‬والرابــع مبلغــا قــدره ألفــان ومئتــا ريــال‬\n     ‫بالســند رقــم ‪ 76794‬وتاريــخ ‪2011/8/1‬م ‪( ،‬ليصبــح إجمالــي مــا قــام‬\n     ‫بدفعــه العميــل مبلــغ وقــدره ‪ 8513‬ثمانيــة آالف وخمســمائة وثالثــة عشــر‬\n     ‫ريــال ال غيــر) ‪ ،‬ومت إرفاقــه باملعاملــة ‪ ،‬كمــا أحضــر املدعــى عليــه‬\n     ‫وكالــة ‪ .......‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ .......‬ويعمــل‬\n     ‫بوظيفــة محصــل لــدى الشــركة املدعــى عليهــا مبوجــب خطابهــا املــؤرخ‬\n     ‫يف ‪1434/8/30‬ه ـ املوافــق ‪2013/7/9‬م واملتضمــن أيضــا أن احملصــل‬\n\n\n‫‪47‬‬\n\f‫احلاضــر (علــى علــم باملبالــغ املســددة مــن قبــل الســيد ‪ ..............‬وكذلــك‬\n‫املبالــغ املســتحقة عليــه‪ ،‬وقــد فوضنــاه باحلضــور لــإدالء بإفادتــه فيمــا‬\n‫يخــص ذلــك) ‪،‬وبعــرض ذلــك علــى املدعــي قــال ‪ :‬مــا ورد يف كشــف‬\n‫احلســاب صحيــح ‪ ،‬ولــم أدفــع ســوى مــا ورد فيــه‪ .‬وبســؤال املدعــى عليــه‬\n‫وكالــة هــل هنــاك ضمانــات قدمــت مــن املدعــي لهــذا العقــد وهــل مت‬\n‫حتويــل راتــب املدعــي لبنــك حددتــه موكلتــك وهــل أخــذ علــى املدعــي‬\n‫كفيــل غــارم قــال ‪ :‬ال يوجــد مــن ذلــك شــيء ‪ .‬وبعرضــه علــى املدعــي‬\n‫قــال‪ :‬هــذا صحيــح ‪ .‬وبســؤال الطرفــن هــل لديكمــا مــا تضيفانــه قــاال‪:‬‬\n‫ال ‪ .‬فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة ‪،‬وبنــاء علــى العقــد‬\n‫املبــرم بــن الطرفــن محــل الدعــوى املــؤرخ يف ‪2011/4/17‬م ‪ ،‬وبنــاء‬\n‫علــى أن العقــد املبــرم بــن الطرفــن محــل الدعــوى هــو عقــد تأجيــر‬\n‫ســيارة مــع الوعــد بالهبــة‪ ،‬وبنــاء علــى املــادة الثالثــة مــن العقــد والتــي‬\n‫تنــص علــى أن مــدة اإلجــارة واحدا وســتني شــهرا تبــدأ يف ‪2011/5/1‬م‪،‬‬\n‫وبنــاء علــى إقــرار الطرفــن بوقــوع حــادث علــى الســيارة محــل الدعــوى‬\n‫والعقــد يف ‪2011/10/8‬م ‪ ،‬وإدخالهــا الورشــة يف ‪2011/10/22‬م ‪،‬‬\n‫ومبــا أن املدعــى عليــه أقــر بــأن الســيارة انتهــى إصالحهــا يف‬\n‫‪2011/12/29‬م ‪ ،‬ودفــع بــأن املدعــي رفــض اســتالمها ‪ ،‬وعليــه قامــت‬\n‫موكلتــه بفســخ العقــد ‪ ،‬وقــد باعــت الســيارة يف ‪2012/1/29‬م ‪ ،‬وبنــاء‬\n‫علــى إقــرار املدعــي مبــا مت دفعــه مــن أقســاط وقدرهــا ثمانيــة آالف‬\n‫وخمســمائة وثالثــة عشــر ريــاال والــوارد ذكرهــا فيكشــف حســاب‬\n‫املدعــي لــدى الشــركة املدعــى عليهــا ‪ ،‬وبنــاء علــى املــادة ‪ 2/14‬مــن‬\n‫العقــد والتــي تنــص علــى (إذا تأخــر الطــرف الثانــي عــن ســداد أي قســط‬\n‫إيجــاري مســتحق مــن أقســاط اإليجــار ‪ ،‬ملــدة ‪ 60‬يومــا مــن تاريــخ‬\n\n\n                                                                                       ‫‪48‬‬\n\f     ‫االســتحقاق فللطــرف األول أن يســتوفيها مــن الضمانــات املقدمــة مــن‬\n     ‫الطــرف الثانــي أو أن يقــوم باخلصــم مــن راتبــه احملــول لــدى البنــك احملدد‬\n     ‫مــن قبــل الطــرف األول أو يطالــب الطــرف الثانــي أو كفيلــه بتســديدها‬\n     ‫مباشــرة ‪،‬فــإن لــم يتمكــن مــن ذلــك ‪ ،‬أو لــم تكــن هــذه الضمانــات‬\n     ‫كافيــة فللطــرف األول أن يفســخ العقــد يف املــدة املتبقيــة منــه) ‪ ،‬ومبــا‬\n     ‫أن طــريف الدعــوى أقــرا بعــدم وجــود ضمانــات أو حتويــل راتــب لبنــك‬\n     ‫معــن أو كفيــل غــارم ‪ ،‬وبنــاء علــى املــادة ‪/3/14‬ج مــن العقــد محــل‬\n     ‫الدعــوى والتــي تنــص علــى (يف حــال فســخ العقــد أثنــاء الســنة األولــى‬\n     ‫يلتــزم الطــرف الثانــي ‪ -‬العميــل ‪ -‬بــأن يســدد إلــى الطــرف األول ثمانيــة‬\n     ‫أقســاط إيجاريــة أو املتبقــي مــن قيمــة العقــد الســنوي أيهمــا أقــل) ‪،‬‬\n     ‫واألقســاط الثمانيــة تســاوي مبلغــا قــدره ســتة عشــر ألــف او ثمامنائــة‬\n     ‫وأربعــة وعشــرون ريــاال ‪ ،‬وبنــاء علــى مــا قضــت بــه املــادة الرابعــة مــن‬\n     ‫العقدمــن أحــكام ‪ ،‬ومنهــا أن أجــرة الســنة األولــى مبلغــا قــدره خمســون‬\n     ‫ألفــا وأربعمائــة واثنــان وســبعون ريــاال ‪ ،‬وأن قيمــة كل قســط مبلغــا‬\n     ‫قــدره ألفــان ومائــة وثالثــة ريــاالت‪ ،‬فاألقســاط الثمانيــة أقــل مــن املتبقــي‬\n     ‫أجرة السنة األولى ‪ ،‬وبناء على أن املبلغ الواجب دفعه من ‪2011/5/1‬م‬\n     ‫وحتى ‪2011/10/1‬م هو عشــرة آالف وخمســمائة وخمســة عشــر رياال‪،‬‬\n     ‫واملدفــوع مــن املدعــي لنلــك الفتــرة ومــا بعدهــا مبلغــا قــدره ثمانيــة آالف‬\n     ‫وخمســمائة وثالثــة عشــر ريــاال ‪ ،‬وبنــاء علــى أن العقــد عقــد إجــارة ‪،‬‬\n     ‫وعقــد اإلجــارة عقــد علــى املنافــع ‪ ،‬فــإن تعــذر علــى املســتأجر االنتفــاع‬\n     ‫بالعــن املؤجــرة فــا يســتحق املؤجــر األجــرة يف فتــرة تعــذر االنتفــاع مــا‬\n     ‫لــم يكــن ذلــك بســبب تعــد املســتأجر أو تفريطــه ‪ ،‬ألنــه لــم يتســلم مــا‬\n     ‫تناولــه عقــد اإلجــارة ‪ ،‬فلــم يســتحق املؤجــر شــيئا ‪ ،‬كمــا قــرر ذلــك أهل‬\n\n\n‫‪49‬‬\n\f‫العلــم ‪ ،‬ومــن ذلــك مــا قــرره صاحــب الــروض املربــع ‪ ،‬ونصــه (وهــي أي‬\n‫اإلجــارة عقــد الزم مــن الطرفــن ألنهــا نــوع مــن البيــع فليــس ألحدهمــا‬\n‫فســخها لغيــر عيــب أو نحــوه ‪ ،‬فــإن آجــره شــيئا ومنعــه أي منــع املؤجــر‬\n‫املســتأجر الشــيء املؤجــر كل املــدة أو بعضهــا بــأن ســلمه العــن ‪ ،‬ثــم‬\n‫حولــه قبــل تقضــي املــدة فــا شــيء لــه مــن األجــرة ألنــه لــم يســلم لــه مــا‬\n‫تناولــه عقــد اإلجــارة ‪ ،‬فلــم يســتحق شــيئا ‪ ،‬وإن بــدأ اآلخر أي املســتأجر‬\n‫فتحــول قبــل انقضائهــا أي انقضــاء مــدة اإلجــارة فعليــه جميــع األجــرة‬\n‫ألنهــا عقــد الزم ‪ ،‬فترتــب مقتضاهــا ‪ ،‬وهــو ملــك املؤجــر األجــر‬\n‫واملســتأجر املنافــع ‪ ...‬وإن وجــد املســتأجر العــن معيبــة أو حــدث بهــا‬\n‫عنــده عيــب وهــو مــا يظهــر بــه تفــاوت األجــر فلــه الفســخ إن لــم يــزل بــا‬\n‫ضــرر يلحقــه وعليــه أجــرة مــا مضــى الســتيفائه املنفعــة فيــه ولــه اإلمضاء‬\n‫مجانــا واخليــار علــى التراخــي) وحيــث أجــازت هيئــة كبــار العلمــاء‬\n‫الشــرط اجلزائــي يف العقــود ‪ ،‬ولقولــه تعالــى (يــا أيهــا الذيــن آمنــوا أوفــوا‬\n‫بالعقــود) ‪ ،‬وحلديــث (املســلمون علــى شــروطهم) رواه الترمــذي وأبــو‬\n‫داوود ‪ ، ،‬وحلديــث (البينــة علــى املدعــي واليمــن علــى املدعــى عليــه)‬\n‫رواه الترمــذي ‪ ،‬قــال أبــو عيســى ‪ :‬العمــل عنــد أهــل العلــم مــن أصحــاب‬\n‫النبــي صلــى اهلل عليــه وســلم وغيرهــم أن البينــة علــى املدعــي واليمــن‬\n‫علــى املدعــى عليــه ‪ ،‬لذلــك كله ‪،‬فقد رددت دعوى املدعي ‪..................‬‬\n‫يف مواجهــة املدعــى عليهــا شــركة ‪ ....................‬لعــدم ثبــوت صحتهــا ‪،‬‬\n‫وحكمــت علــى املدعــي بدفــع مبلــغ قــدره ألفــان وخمســمائة واثنــان‬\n‫وســتون ريــاال وثمانــون هللــة للمدعــى عليهــا مقابــل أجــرة الســيارة محــل‬\n‫الدعــوى مــن ‪2011/5/1‬م وحتــى تاريــخ احلــادث يف ‪2011/10/8‬م بعــد‬\n‫خصــم مــا مت دفعــه مــن قبــل املدعــي ‪ ،‬وحكمــت علــى املدعــي بدفــع‬\n\n\n                                                                                         ‫‪50‬‬\n\f     ‫مبلــغ قــدره ســتة عشــر ألفــا و ثمامنائــة وأربعــة وعشــرون ريــاال للمدعــى‬\n     ‫عليهــا مقابــل الشــرط اجلزائــي الــوارد يف املــادة ‪/3/14‬ج ‪ ،‬ليكــون‬\n     ‫مجمــوع مــا يدفعــه املدعــي للمدعــى عليهــا مبلغــا قــدره تســعة عشــرألفا‬\n     ‫وثالثمائــة وســتة وثمانــون ريــاال وثمانــون هللــة ‪ ،‬وألزمــت املدعــى عليهــا‬\n     ‫بعــد ســداد املدعــي للمبلــغ محــل احلكــم رفــع اســمه مــن قائمــة ‪، ...‬‬\n     ‫ورددت مــا عــدا ذلــك مــن طلبــات لعــدم ثبــوت موجبهــا ‪ .‬وبــه حكمــت ‪.‬‬\n     ‫وبــه قنــع املدعــي ‪ ،‬وقــرر املدعــى عليــه وكالــة االعتــراض ‪ ،‬وجــرى‬\n     ‫تســليمه نســخة مــن احلكــم وإفهامــه بــأن لــه احلــق يف االعتــراض عليــه‬\n     ‫خــال ثالثــن يومــا ‪ ،‬وإال ســقط حقــه يف االعتــراض ‪ ،‬واكتســب‬\n     ‫احلكــم القطعيــة ‪ .‬وأقفلــت اجللســة الســاعة ‪ . 11 : 10‬وبــاهلل التوفيــق ‪،‬‬\n     ‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n                                                                       ‫‪1434/09/02‬هـ‬\n     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا‪ ...........‬القاضــي يف احملكمــة العامــة‬\n     ‫مبحافظــة جــدة ففــي يــوم األربعــاء املوافــق‪ 1435/02/01‬ه ـ افتتحــت‬\n     ‫اجللســة الســاعة ‪ 1 :15‬وفيهــا قــد عــادت املعاملــة مــن محكمــة‬\n     ‫االســتئناف بخطــاب رئيســها رقــم ‪ 33988853‬وتاريــخ ‪1435/1/22‬ه ـ‬\n     ‫وبالقــرار رقــم ‪ 35105065‬وتاريــخ ‪1435/1/4‬ه ـ ومضمونــه مــا يلــي‪:‬‬\n     ‫(وبدراســة احلكــم وصــورة ضبطــه والئحتــه االعتراضيــة قررنــا املوافقــة‬\n     ‫علــى احلكــم)‪ .‬وحت ــى ال يخف ــى ج ــرى إثباتــه وأقفل ــت اجل ـلـسـ ــة الســاعة‬\n     ‫‪ 1 : 25‬وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آله وصحبه‬\n                                                      ‫وســلم ‪ .‬حــرر يف ‪1435/2/1‬ه ـ‬\n     ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد‪ :‬فقــد‬\n     ‫جرى منا نحن قضاة الدائرة اجلزائية اخلامســة مبحكمة االســتئناف يف‬\n\n\n‫‪51‬‬\n\f‫منطقــة مكــة املكرمــة اإلطــاع علــى املعاملــة الواردة مــن فضيلة رئيس‬\n‫احملكمــة العامــة بجــدة برقــم (‪ )33988853‬وتاريــخ ‪1434/12/17‬ه‬\n‫املرفــق بهــا الصــك الصــادر م ــن فضيلــة الشــيخ‪ .......................‬القاضــي‬\n‫باحملكمــة العامــة بجــدة برقــم (‪ )34311281‬وت ـ ــاريخ ‪1434/9/2‬ه ـ‬\n‫الـمتضم ــن دعــوى املدعــي‪ ..............‬ســعودي اجلنســية ضــد شــركة‬\n‫‪ ....................‬يف إتــاف ممتلــكات‪ ،‬احملكــوم فيــه مبــا دون بباطــن‬\n‫الصــك‪ ،‬وبدراســة الصــك وصــورة ضبطــه والئحتــه االعتراضيــة قررنــا‬\n‫املوافقــة علــى احلكــم ‪ ،‬واهلل املوفــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                                                  ‫وعلــى آل ـ ـ ــه وصحبــه وســلم ‪...‬‬\n\n\n\n\n                                                                                         ‫‪52‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"612f1ba9-3f27-52bc-993f-69d3ecdc8564","source_page_start":32,"source_page_end":52,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"15dd58ce4e2877e3276ccb7a2230a0a6e68bc8df6edf9491961df17bf6e974f3","normalized_text_hash":"4b8101362ccc4fea3db647f700b41cf151d31ca6a4a6c8187819f40e92bf9118","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v7-p32-4311281"},{"id":"277dd9c6-2358-5855-85cb-aca9914c06c6","document_type":"judgment","category":"judicial","subcategory":"general","title":"إجارة -إخاء عقار من غائب -اإلعان يف الصحيفة احمللية قبل سماع الدعوى -البينة بشهادة الشهود املعدلن -تكوين جلنة لفرز ممتلكات الشقة -بيع ما يخشى تلفه وإيداع ثمنه يف بيت املال -حفظ ما ميكن حفظه يف بيت املال -احلكم بفتح العن ومتكن املدعى من االنتفاع بها -الغائب على حجته متى حضر -رفع احلكم حملكمة الاستئناف لتعذر تبليغ املدعى عليه باحلكم .","document_number":"33445093","case_number":"33394062","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة جدة بأنه تقدم لها املدعي","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/11/2","year":"1434","subject":"إجارة -إخاء عقار من غائب -اإلعان يف الصحيفة احمللية قبل سماع الدعوى -البينة بشهادة الشهود املعدلن -تكوين جلنة لفرز ممتلكات الشقة -بيع ما يخشى تلفه وإيداع ثمنه يف بيت املال -حفظ ما ميكن حفظه يف بيت املال -احلكم بفتح العن ومتكن املدعى من االنتفاع بها -الغائب على حجته متى حضر -رفع احلكم حملكمة الاستئناف لتعذر تبليغ املدعى عليه باحلكم .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫تاريخه‪1433/11/2 :‬هـ‬\n                      ‫ُ‬                 ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪33445093 :‬‬\n                         ‫َر ْق ُم الدعوى‪33394062 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                    ‫‪ 349752‬تاريخه‪1434/1/12:‬هـ‬\n\n\n\n     ‫إجــارة ‪ -‬إخــاء عقــار مــن غائــب ‪ -‬اإلعــان يف الصحيفــة احملليــة قبــل‬\n     ‫ســماع الدعــوى ‪ -‬البينــة بشــهادة الشــهود املعدلــن ‪ -‬تكويــن جلنــة لفــرز‬\n     ‫ممتلــكات الشــقة ‪ -‬بيــع مــا يخشــى تلفــه وإيــداع ثمنــه يف بيــت املــال‬\n     ‫‪-‬حفــظ مــا ميكــن حفظــه يف بيــت املــال ‪ -‬احلكــم بفتــح العــن ومتكــن‬\n     ‫املدعــى مــن االنتفــاع بهــا‪ -‬الغائــب علــى حجتــه متــى حضــر ‪ -‬رفــع‬\n           ‫احلكــم حملكمــة االســتئناف لتعــذر تبليــغ املدعــى عليــه باحلكــم ‪.‬‬\n\n\n\n\n                         ‫‪ .1‬قوله صلى اهلل عليه وسلم (ال ضرر وال ضرار)‪.‬‬\n           ‫‪ .2‬املادة ‪ 5/176‬من نظام املرافعات الشرعية والئحتها التنفيذية‪.‬‬\n\n\n\n\n     ‫ادعــى املدعــي ضــد املدعــى عليــه الغائــب عــن مجلــس احلكــم بأنــه قــد‬\n     ‫قــام بتأجيــر املدعــى عليــه الشــقة رقــم ‪...‬بالطابــق اخلامــس يف عمارتــه‬\n     ‫الواقعــة يف حــي ‪ ...‬يف مدينــة جــدة بأجــرة ســنوية قدرهــا عشــرون ألــف‬\n     ‫ريــال وقــد توقــف املدعــى عليــه عــن دفــع اإليجارات املســتحقة منــذ تاريخ‬\n     ‫‪1432/10/15‬ه ـ وقــد تغيــب عــن األنظــار منــذ ذلــك احلــن وال يعلــم عنــه‬\n     ‫شــيئ ًا وقــد تضــرر مــن بقــاء الشــقة معطلــة منافعهــا ويطلــب احلكــم بفتــح‬\n     ‫الشــقة املذكــورة أعــاه ومتكينــه مــن االنتفــاع بهــا هكــذا ادعــى ‪ -‬لــم‬\n‫‪53‬‬\n\f‫يحضــر املدعــى عليــه ولــم يــرد مــا يفيــد تبلغــه فجــرى ســماع الدعــوى‬\n‫غيابيـ ًا بعــد اإلعــان يف الصحيفــة احملليــة مبوعــد اجللســة‪ ،‬قــدم املدعــي‬\n‫بينتــه صــك العقــار وعقــد اإليجــار كمــا أحضــر شــاهدين ُعــدال شــرع ًا‬\n‫شــهدا طبــق دعــواه‪ ،‬ومبــا أن املدعــي قــد أبــرز مــا يثبــت متلكــه للعقــار‬\n‫ومــا يثبــت قيامــه بتأجيــر املدعــى عليــه الشــقة محــل الدعــوى وملــا قــام‬\n‫بــه املدعــي مــن اإلعــان عــن املدعــى عليــه ومــا أحضــره مــن بينــة تثبــت‬\n‫صحــة دعــواه ومبــا أن تــرك الشــقة مغلقــة طيلــة هــذه الفتــرة وتغيــب‬\n‫مســتأجرها وعــدم دفعــه لألجــرة فيــه ضــرر علــى مالــك العقــار وحيــث‬\n‫إن الضــرر مرفــوع يف الشــريعة لقــول النبــي صلــى اهلل عليــه وســلم ( ال‬\n‫ضــرر وال ضــرار ) وملــا ظهــر مــن اإلجــراءات الــواردة أعــاه ممــا يتعــذر‬\n‫معــه تبليــغ املدعــى عليــه وبنــاء علــى املــادة السادســة والســبعني بعــد املائــة‬\n‫مــن نظــام املرافعــات الشــرعية والئحتهــا التنفيذيــة اخلامســة‪ ،‬ملــا تقــدم‬\n‫ُحكــم بفتــح الشــقة رقــم ‪ ...‬الواقعــة يف حــي ‪ ...‬مبدينــة جــدة بحضــور‬\n‫منــدوب مــن الشــرطة ومنــدوب مــن بيــت املــال وفــرز مــا يف الشــقة مــن‬\n‫ممتلــكات وبيــع مــا يخشــى تلفــه وحفــظ قيمتــه يف بيــت املــال وحفــظ مــا‬\n‫يتمكــن حفظــه يف بيــت املــال وإعــداد محضــر يف ذلــك ومتكــن املدعــي‬\n‫مــن االســتفادة مــن الشــقة‪ ،‬قنــع املدعــي باحلكــم‪ ،‬رفــع إلــى محكمــة‬\n‫االســتئناف وذلــك لتعــذر تبليــغ املدعــى‪ ،‬صــدق احلكــم مــن الدائــرة‬\n     ‫احلقوقيــة الســابعة مبحكمــة االســتئناف مبنطقــة مكــة املكرمــة‪.‬‬\n\n\n\n\n                                                                                           ‫‪54‬‬\n\f     ‫احلمــد هلل وحــده وبعــد ففــي هــذا اليوم الثالثاء املوافــق ‪1433/11/02‬هـ‬\n     ‫افتتحــت اجللســة الســاعة ‪ 08 : 30‬وفيهــا حضــر املدعــي أصالــة ‪، ...‬‬\n     ‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ...‬ولــم يحضــر املدعــى‬\n     ‫عليــه ‪ ...‬وال مــن ميثلــه بوكالــة شــرعية ولــم يردنــا مــا يفيــد تبلغــه مبوعــد‬\n     ‫هــذه اجللســة مــن عــدم ذلــك وبســؤال املدعــي عــن دعــواه أجــاب قائــا‬\n     ‫إننــي أمتلــك العقــار الواقــع يف حــي ‪ ...‬يف مدينــة جــدة واملكــون مــن‬\n     ‫عمــارة ســكنية بهــا شــقق ســكنية كذلــك وقــد قمــت بتأجيــر املدعــى‬\n     ‫عليــه ‪ ...‬الشــقة رقــم ‪ ...‬بالطابــق ‪ ...‬بقيمــة ســنوية قدرهــا عشــرون ألــف‬\n     ‫ريــال وقــد توقــف املدعــى عليــه عــن دفــع اإليجــارات املســتحقة منــذ‬\n     ‫تاريــخ ‪1432/10/15‬ه ـ وقــد تغيــب عــن األنظــار منــذ ذلــك احلــن ال نعلــم‬\n     ‫عنــه شــيئا وقــد تضــررت مــن بقــاء الشــقة معطلــة منافعهــا أطلــب احلكــم‬\n     ‫بفتــح الشــقة املذكــورة أعــاه ومتكينــي مــن االنتفــاع بهــا هــذه دعــواي‬\n     ‫وقــد وردنــا خطــاب شــرطة محافظــة جــدة ذي الرقــم ‪ 6/6244‬وتاريــخ‬\n     ‫‪1433/05/29‬ه ـ واملقيــد يف هــذه احملكمة برقــم ‪ 331046791‬وتاريخ‬\n     ‫‪1433/06/03‬ه ـ واملتضمــن اإلفــادة التاليــة ‪ ( :‬نفيدكــم أنــه بالبحــث‬\n     ‫والتحــري عــن املســتأجر املذكــور لــم يتــم العثــور عليــه وذلــك حســب‬\n     ‫مــا يتضــح لفضيلتكــم مــن األوراق املرفقــة ) أ‪.‬ه ـ ‪ ،‬وبســؤال املدعــي‬\n     ‫عمــا يثبــت متلكــه للعقــار أبــرز مــن يــده صــورة مــن الصــك الصــادر مــن‬\n     ‫كتابــة عــدل جــدة األولــى ذي الرقــم ‪ 9315‬وتاريــخ ‪1425/11/08‬ه ـ‬\n     ‫والــذي يظهــر منــه امتــاك املدعــي للعقــار رقــم ‪ 567‬واملبــن حدودهــا‬\n     ‫وأطوالهــا يف صــورة الصــك املرفقــة كمــا أبــرز املدعــي مــن يــده عقــد‬\n\n‫‪55‬‬\n\f‫اإليجــار واملطبــوع علــى أوراق مؤسســة ‪ ...‬للتجــارة واملقــاوالت والــذي‬\n‫يظهــر منــه قيــام املدعــي بتأجيــر املدعــى عليــه ‪ ...‬الشــقة رقــم ‪ 43‬باملبلــغ‬\n‫املذكــور أعــاه كمــا يظهــر منــه أن تاريــخ العقــد هــو ‪1431/7/15‬ه ـ‬\n‫كمــا قــد قــرر املدعــي قائــا إننــي قمــت باإلعــان باجلريــدة اليوميــة‬\n‫عــن املدعــى عليــه فأبــرز مــن يــده ورقــة مــن جريــدة البــاد العــدد رقــم‬\n‫‪ 20190‬وتاريــخ ‪ 26‬جمــادى اآلخــرة لعــام ‪1433‬ه ـ ونــص اإلعــان ( تعلــن‬\n‫احملكمــة العامــة مبحافظــة جــدة بأنــه تقــدم لهــا املدعــي ‪ ، ...‬ســعودي‬\n‫اجلنســية ســجله املدنــي برقــم ‪ ...‬بدعــوى ضــد املدعــى عليــه ‪ ، ...‬ســعودي‬\n‫اجلنســية ســجله املدنــي برقــم ‪ ...‬يعمــل مديــر عــام مبكتــب ‪ ...‬لتأجيــر‬\n‫الســيارات بشــأن فتــح شــقته يف العمــارة الكائنــة يف حــي ‪ ...‬خلــف ‪...‬‬\n‫بجــدة وحــدد موعــد جلســة يف يــوم الثالثــاء املوافــق ‪1433/11/02‬ه ـ‬\n‫الســاعة ‪ 08 : 30‬صباحــا فمــن يعلــم عــن املدعــى عليــه املذكــور شــيئا‬\n‫عليــه مراجعــة احملكمــة العامــة مبحافظــة جــدة املكتــب القضائــي‬\n‫الســادس عشــر ( ‪ ) 16‬بالــدور اخلامــس واهلل املوفــق ) أ‪.‬ه ـ ‪ ،‬وبســؤال‬\n‫املدعــى عليــه وهــل لديــه مزيــد مــن البينــات علــى مــا جــاء يف دعــواه‬\n‫فأحضــر للشــهادة وأدائهــا م‪ ...‬باكســتاني اجلنســية مبوجــب رخصــة‬\n‫اإلقامــة رقــم ‪ ...‬ويظهــر أن تاريــخ ميــاده ‪1953/06/19‬م وبســؤاله عــن‬\n‫معلوماتــه املدنيــة أجــاب قائــا إننــي أســكن يف حــي ‪ ...‬مبدينــة جــدة‬\n‫ومتــزوج ولــي أوالد وبســؤاله عمــا لديــه أجــاب قائــا أشــهد بــاهلل العظيــم‬\n‫بــأن املدعــى عليــه ‪ ...‬قــد تــرك الشــقة رقــم ‪ 43‬العائــدة للمدعــي بعمارتــه‬\n‫الواقعــة يف حــي ‪ ...‬مبدينــة جــدة منــذ أكثــر مــن عــام هــذا مــا أشــهد بــه‬\n‫كمــا أحضــر للشــهادة وأدائهــا ‪ ، ...‬مصــري اجلنســية مبوجــب رخصــة‬\n‫اإلقامــة رقــم ‪ ...‬ويظهــر منهــا أن تاريــخ ميــاده ‪1977/02/15‬م وبســؤاله‬\n\n\n                                                                                       ‫‪56‬‬\n\f     ‫عــن معلوماتــه املدنيــة أجــاب قائــا إننــي أســكن يف حــي ‪ ...‬مبدينــة‬\n     ‫جــدة ومتــزوج ولــي أوالد وبســؤاله عمــا لديــه أجــاب قائــا أشــهد بــاهلل‬\n     ‫العظيــم بــأن املدعــى عليــه ‪ ...‬قــد تــرك الشــقة رقــم ‪ 43‬العائــدة للمدعــي‬\n     ‫بعمارتــه الواقعــة يف حــي الصفــا مبدينــة جــدة منــذ أكثــر مــن عــام هــذا‬\n     ‫مــا أشــهد بــه كمــا أحضــر املدعــي للشــهادة وأدائهــا ‪ ، ...‬باكســتاني‬\n     ‫اجلنســية مبوجــب رخصــة اإلقامــة رقــم ‪ ...‬و‪ ، ...‬ســعودي اجلنســية ســجله‬\n     ‫املدنــي برقــم ‪ ...‬ولــدى استشــهادهما شــهد كل واحــد منهمــا مبفــرده‬\n     ‫قائــا أشــهد أن الشــاهدين ‪ ......‬و‪ ...‬ومقبــوال الشــهادة فبنــاءا علــى‬\n     ‫مــا تقــدم مــن الدعــوى وحيــث إن املدعــي يدعــي غيــاب املدعــى عليــه‬\n     ‫وتركــه لشــقته مقفلــة وطلبــه متكينــه مــن االنتفــاع منهــا وتضــرره مــن‬\n     ‫ذلــك وحيــث إن املدعــي قــد أبــرز مــا يثبــت متلكــه للعقــار ومــا يثبــت‬\n     ‫قيامــه بتأجيــر املدعــى عليــه الشــقة محــل الدعــوى وملــا ورد مــن إفــادة‬\n     ‫شــرطة محافظــة جــدة واملتضمنــة عــدم العثــور علــى املدعــى عليــه وملــا‬\n     ‫قــام بــه املدعــي مــن اإلعــان عــن املدعــى عليــه ومــا أحضــره مــن بينــة‬\n     ‫تثبــت صحــة دعــواه مــن تغيــب املدعــى عليــه وتركــه الشــقة مغلقــة‬\n     ‫وحيــث إن تــرك الشــقة مغلقــة طيلــة هــذه الفتــرة وتغيــب مســتأجرها‬\n     ‫وعــدم دفعــه لألجــرة فيــه ضــرر علــى مالــك العقــار وحيــث إن الضــرر‬\n     ‫مرفــوع يف الشــريعة لقــول النبــي صلــى اهلل عليــه وســلم ( ال ضــرر وال‬\n     ‫ضــرار ) وملــا ظهــر مــن اإلجــراءات الــواردة أعــاه ممــا يتعــذر معــه تبليــغ‬\n     ‫املدعــى عليــه وبنــاءا علــى املــادة السادســة والســبعون بعــد املائــة مــن نظام‬\n     ‫املرافعــات الشــرعية والئحتهــا التنفيذيــة اخلامســة والتــي تنــص علــى أنــه‬\n     ‫( إذا تعــذر تســليم نســخة صــك احلكــم الغيابــي إلــى احملكــوم عليــه أو‬\n     ‫وكيلــه رفــع احلكــم إلــى محكمــة التمييــز بــدون الئحــة اعتراضيــة وال‬\n\n\n‫‪57‬‬\n\f‫مينــع ذلــك مــن التمــاس إعــادة النظــر وفــق أحكامــه املقــررة يف هــذا‬\n‫النظــام ) جلميــع مــا تقــدم فقــد حكمــت بفتــح الشــقة رقــم ‪ 43‬الواقعــة يف‬\n‫حــي الصفــا مبدينــة جــدة اململوكــة بالصــك املشــار إلــى رقمــه وتاريخــه‬\n‫أعــاه بحضــور منــدوب مــن الشــرطة ومنــدوب مــن بيــت املــال وفــرز مــا‬\n‫يف الشــقة مــن ممتلــكات وبيــع مــا يخشــى مــن تلفــه وحفــظ قيمتــه يف‬\n‫بيــت املــال وحفــظ مــا يتمكــن حفظــه يف بيــت املــال وإعــداد محضــر‬\n‫يف ذلــك ومتكــن املدعــي مــن االســتفادة مــن الشــقة وبعــرض احلكــم‬\n‫علــى املدعــي قــرر القناعــة بــه وأمــرت برفــع كامــل أوراق املعاملــة إلــى‬\n‫محكمــة االســتئناف وذلــك لتعــذر تبليــغ املدعــى عليــه وأقفلــت اجللســة‬\n‫الســاعة ‪ 09 : 00‬وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                              ‫وصحبــه وســلم حــرر يف ‪1433/10/24‬ه ـ ‪،،.‬‬\n‫احلمــد هلل وحــده‪ ،‬والصــاة والســام علــى مــن ال نبــي بعــده‪ ،‬وبعــد‪:‬‬\n‫فقــد جــرى منــا نحــن قضــا َة الدائــرة احلقوقيــة الســابعة مبحكمــة‬\n‫االســتئناف يف منطقــة مكــة املكرمــة االطــاع علــى املعاملــة الــواردة‬\n‫مــن فضيلــة رئيــس احملكمــة العامــة مبحافظــة جــدة املســاعد برقــم‬\n‫‪ 33/1046791‬وتاريــخ ‪1434/01/06‬ه ـ املرفــق بهــا الصــك الصــادر من‬\n‫فضيلــة الشــيخ ‪ ...‬القاضــي باحملكمــة العامــة مبحافظــة جــدة املســجل‬\n‫برقــم ‪ 33445093‬وتاريــخ ‪1433/11/02‬ه ـ املتضمــن دعــوى ‪ ...‬ضــد ‪...‬‬\n‫وبدراســة الصــك وص ــورة ضبط ــه تق ــررت املوافق ــة عل ــى احلكــم واهلل‬\n         ‫املوفــق وصل ــى اهلل عل ــى نبينــا محمــد وعل ــى آل ــه وصحب ــه وســلم‪.‬‬\n\n\n\n\n                                                                                       ‫‪58‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"612f1ba9-3f27-52bc-993f-69d3ecdc8564","source_page_start":53,"source_page_end":58,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"7903b335f36a7d154ed58e95bbca2486056a788c18286e35f5ec5d40e384d8a0","normalized_text_hash":"734ba991644a97ae8c855dfc6cac65d0df5d323f3152e9b2a31e31dfe3d64d77","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v7-p53-33445093"},{"id":"e8ceb43b-4df9-584b-b55d-77fcb7ed80db","document_type":"judgment","category":"judicial","subcategory":"general","title":"إجارة -إخاء عقار -حكم على غائب -تعذر إباغ خصم -تنويه بأن الغائب على حجته إذا حضر .","document_number":"33413765","case_number":"3395424","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالدمام","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/9/17","year":"1434","subject":"إجارة -إخاء عقار -حكم على غائب -تعذر إباغ خصم -تنويه بأن الغائب على حجته إذا حضر .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫تاريخه‪1433/9/17 :‬هـ‬\n                      ‫ُ‬                ‫َر ْق ُم َّ‬\n                         ‫الص ِّك‪33413765 :‬‬\n                         ‫َر ْق ُم الدعوى‪3395424 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                 ‫‪ 34228308‬تاريخه‪1434/6/3 :‬هـ‬\n\n\n\n     ‫إجــارة ‪ -‬إخــاء عقــار ‪ -‬حكــم علــى غائــب ‪ -‬تعــذر إبــاغ خصــم ‪ -‬تنويــه‬\n                                                     ‫بــأن الغائــب علــى حجتــه إذا حضــر ‪.‬‬\n\n\n\n\n                                            ‫املادة (‪ )55‬من نظام املرافعات الشرعية ‪.‬‬\n\n\n\n\n     ‫ادعــى املدعــي ضــد الغائــب عــن مجلــس احلكــم املدعــى عليــه والــذي‬\n     ‫تعــذر إبالغــه مبوعــد اجللســة بالطــرق الرســمية ومضمــون الدعــوى‬\n     ‫أن املدعــي أجــر علــى املدعــى عليــه شــقة مــن عمــارة ميلكهــا مبوجــب‬\n     ‫عقــد مبــرم بــن الطرفــن حيــث اســتأجرها املدعــى عليــه ملــدة ســنة‬\n     ‫وتأخــر يف تســليم اإليجــار وطلــب املدعــي إلــزام املدعــى عليــه بإخــاء‬\n     ‫العقــار وتســليم قيمــة اإليجــارات املتأخــرة‪ ،‬احضــر املدعــي بينتــه وهمــا‬\n     ‫شــاهدان شــهدا علــى صحــة دعــواه وعــدل الشــاهدان شــرعاً‪ ،‬صــدر‬\n     ‫احلكــم بإلــزام املدعــى عليــة بتســليم األجــرة املتأخــرة وإخــاء الشــقة‬\n                             ‫حــاالً‪ ،‬صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫‪59‬‬\n\f‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .......‬القاضــي يف احملكمــة العامــة‬\n‫بالدمــام وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بالدمــام برقــم ‪ 3395424‬وتاريــخ ‪1433/02/07‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 33249180‬وتاريــخ ‪1433/02/07‬ه ـ ففــي يــوم‬\n‫االحــد املوافق‪1433/02/21‬ه ـ أفتتحــت اجللســة وفيهــا حضــر‪.......‬‬\n‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ .......‬ولــم يحضــر املدعــى‬\n‫عليــه املدعــو‪ .......‬ولــم تردنــا افــاده مــن محضــري اخلصــوم بتبليغــه‬\n‫والنــه تعــذر ابالغــه حســب احملاضــر املرفقــه والنــه جــرى الكتابــه‬\n‫ملقــام االمــاره البالغــه ولــم تردنــا افــاده حتــى االن لــذا فقــد جــرى‬\n‫ســماع الدعــوى وقــرر املدعــي قائــا ان مــن اجلــاري يف ملكــي وحتــت‬\n‫تصــريف العمــاره الواقعــه يف حــي ‪ ...‬بالدمــام يف القطعــه رقــم ‪ ...‬يف‬\n‫مخطــط ‪ ...‬بالدمــام واململوكــه لــي مبوجــب صــك رقــم ‪4/30/3695‬‬\n‫حدودهــا واطوالهــا كالتالــي شــماال شــارع عــرض ‪20‬م بطــول ثالثــون‬\n‫متــر وجنوبــا ارض ‪ 15/‬بطــول ثالثــون متــر وشــرقا شــارع عــرض ‪ 10‬م‬\n‫بطــول خمســة وعشــرون متــر وغربــا ارض ‪ 14/‬بطــول خمســه وعشــرون‬\n‫متــر حيــث اســتأجر منــي املدعــى عليــه شــقه يف هــذه العمــاره مبوجــب‬\n‫العقــد املبــرم بيننــا واملوقــع عليــه مــن قبــل الطرفــن حيــث اســتاجرها‬\n‫بتاريــخ ‪1428/06/01‬ه ـ باجــره ســنويه و قدرهــا ثمــان وعشــرون الــف‬\n‫ريــال وطريقــة الدفــع كل ســتة اشــهر اربعــة عشــر الــف ريــال وقــد تاخــر‬\n‫املدعــى عليــه يف تســديد االيجــار عــدة مــرات حيــث بلــغ الــذي يف ذمتــه‬\n‫ثمانيــة عشــر الــف واربعمائــة وثمانــون ريــال وقــد طلبــت منــه اخــاء‬\n\n                                                                                   ‫‪60‬‬\n\f     ‫العقــار اكثــر مــن ســنه ولكنــه رفــض ذلــك وامتنــع عــن االخــاء علمــا‬\n     ‫بــان العقــد مدتــه ســنه واحــده اطلــب الزامــه باخــاء العقــار املوصــوف يف‬\n     ‫الدعــوى هــذه دعــواي وبســؤاله عــن البينــه احضــر للشــهاده علــى ذلــك‬\n     ‫كال مــن ‪ .......‬ســعودي اجلنســيه مبوجــب ســجل مدنــي رقــم ‪..............‬‬\n     ‫و‪ ..............‬ســعودي اجلنســيه مبوجــب ســجل مدنــي ‪ .......‬وشــهد كل‬\n     ‫واحــد منهــم بقولــه اشــهد بــاهلل العظيــم ان املدعــى عليــه اســتاجر مــن‬\n     ‫املدعــي الشــقه املذكــوره اعــاه باجــرة ســنويه قدرهــا ثمــان وعشــرون‬\n     ‫الــف ريــال وان املدعــى عليــه تاخــر يف ســداد االيجــارات وان الــذي‬\n     ‫بذمتــه ثمانيــة عشــر الــف واربعمائــه وثمانــون ريــال وان املدعــي طلــب‬\n     ‫منــه اخــاء العقــار ولكنــه رفــض وامتنــع وقــد حاولنــا نحــن معــه عــدة‬\n     ‫مــرات ولكــن دون جــدوى هكــذا شــهدا واحضــر لتعديــل الشــهود‬\n     ‫كال مــن ‪ .......‬ســعودي اجلنســيه مبوجــب ســجل مدنــي رقــم ‪ .......‬و ‪.......‬‬\n     ‫ســعودي اجلنســيه مبوجــب ســجل مدنــي رقــم ‪ .......‬وشــهدا بــاهلل العظيــم‬\n     ‫ان الشــهود عــدول وثقــات وال نعلــم عنهــم اال كل خيــر وليــس بينهــم‬\n     ‫وبــن املدعــى عليــه اي عــداوه هــذا مالدينــا لــذى فقــد جــرى الكتابــة‬\n     ‫منــا لكتابــة العــدل لالستفســار عــن ســريان مفعــول الصــك املشــار عليــه‬\n     ‫وقــد وردتنــا افــادة محضــري اخلصــوم عــدة مــرات والتــي تفيــد تعــذر‬\n     ‫ابالغــه رغــم الوصــول ملنزلــه وطــرق البــاب ولكــن اليــرد كمــا جــرى‬\n     ‫األتصــال بــه عــدة مــرات ولكــن جوالــه مغلــق ولــم يراجــع خــال هــذه‬\n     ‫الفتــرة احملكمــة لرفــع التعميــم عنــه ومــازل التعميــم قائمــا وقــد وردتنــا‬\n     ‫إفــادة كتابــة عــدل الدمــام برقــم ‪ 331476483‬وتاريــخ ‪1433/8/12‬ه ـ‬\n     ‫والتــي تتضمــن ســريان مفعــول الصــك وأنــه عائــد للمدعــي وبنــاء علــى‬\n     ‫املــادة اخلامســة واخلمســن مــن نظــام املرفعــات ولتغيــب املدعــى عليــه‬\n\n\n‫‪61‬‬\n\f‫عــن احلضــور ومحاولــة ابالغــه بشــتى الطــرق ولتعــذر ذلــك وبنــاء البينــه‬\n‫علــى املعدلــه شــرعا ولــكل مــا تقــدم فقــد حكمــت علــى املدعــى عليــه‬\n‫الغائــب عــن مجلــس احلكــم بــأن يســلم املدعــي مبلــغ وقــدره ثمانيــة‬\n‫عشــر الــف واربعمائــة وثمانــون ريــال وأن يخلــي الشــقه املوصوفــه اعــاه‬\n‫حــاال وقــررت بعــث نســخة مــن صــك احلكــم بعــد تســجيله للمدعــي‬\n‫عليــه ليقــدم اعتراضــه خــال املــدة املقــررة نظامـ ًا وهــي ثالثــون يومـ ًا مــن‬\n‫تاريــخ التبليــغ وأنــه إذا مضــت مــدة االعتــراض ولــم يقــدم اعتراضــه بعــد‬\n‫تبليغــه احلكــم فــإن احلكــم يكتســب القطعيــة ويعــد حضوريـ ًا يف حــق‬\n‫املدعــى عليــه حســب املــواد ‪1/55‬و‪4/176‬و‪ 178‬مــن الالئحــة التنفيذيــة‬\n‫لنظــام املرافعــات وأنــه اذا لــم يتبلــغ او تعــذر ابالغــه فــإن احلكــم يرفــع‬\n‫حملكمــة اإلســتئناف حســب النظــام وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى‬\n   ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1433/09/06‬هــ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة دائ ــرة األحــوال‬\n‫الشــخصية الثانيــة يف محكمــة االســتئناف باملنطقــة الشــرقية علــى‬\n‫املعاملــة املقيــدة لــدى احملكمــة برقــم ‪/34/1072562‬ش‪ 2‬وتاريــخ‬\n‫‪1434/5/1‬ه ـ والــواردة مــن فضيلــة رئيــس احملكمــة العامــة مبدينــة‬\n‫الدمــام برقــم ‪ 33249180‬وتاريــخ ‪1434/4/28‬ه ـ املرفــق بهــا الصــك‬\n‫الصــادر مــن فضيلــة القاضــي بهــا الشــيخ ‪ ..............‬املســجل برقــم‬\n‫‪ 33413765‬وتاريــخ ‪1433/9/17‬ه ـ اخلــاص بدعــوى ‪ ..............‬ضــد‬\n‫‪ ..............‬يف قضيــة اخــاء عقــار وقــد تضمــن الصــك حكــم فضيلتــه‬\n‫مبــا هــو مــدون ومفصــل فيــه‪ .‬وبدراســة الصــك وصــورة ضبطــه وأوراق‬\n‫املعاملــة قررنــا املصادقــة علــى حكــم فضيلتــه مــع تنبيهــه إلــى إحلــاق‬\n‫العبــارة يف الصــك (أن احلكــم يف حــق املدعــى عليــه غيابــي وأنــه علــى‬\n\n\n                                                                                        ‫‪62‬‬\n\f     ‫حجتــه) وذلــك قبــل إحالتهــا إلــى جهــة التنفيــذ واهلل املوفــق وصلــى اهلل‬\n          ‫علــى نبينــا محمــد وآلــه وصحبــه وســلم حــرر يف ‪1434/5/29‬ه ـ‬\n\n\n\n\n‫‪63‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"612f1ba9-3f27-52bc-993f-69d3ecdc8564","source_page_start":59,"source_page_end":63,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"3a626d509bd3cf9f661fa3ca1c630d4540e0585635a2489ee1afe33a20a73010","normalized_text_hash":"dc667fb986fd831269992cac5a65287bbd0b1318209fa1aad30cddf8a34d27d4","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v7-p59-33413765"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS document_files
